def _unique_strings(values: Iterable[str]) -> list[str]:
    seen: set[str] = set()
    unique: list[str] = []
    for value in values:
        if value not in seen:
            seen.add(value)
            unique.append(value)
    return unique


def _walk_json_tree(value: Any) -> Iterable[Any]:
    yield value
    if isinstance(value, dict):
        for child in value.values():
            yield from _walk_json_tree(child)
    elif isinstance(value, list):
        for child in value:
            yield from _walk_json_tree(child)


def ast_structure_summary(ast: dict[str, Any]) -> dict[str, Any]:
    """Return a stable, non-exhaustive summary for certified-fragment drift checks."""
    predicate_symbols: list[str] = []
    predicate_types: list[str] = []
    entity_symbols: list[str] = []
    state_symbols: list[str] = []
    binder_signatures: list[str] = []

    for node in _walk_json_tree(ast):
        if not isinstance(node, dict):
            continue
        for key in ("predicate", "function", "connective"):
            value = node.get(key)
            if isinstance(value, str):
                predicate_symbols.append(value)
        if isinstance(node.get("name"), str) and isinstance(
            node.get("predicate_type"),
            str,
        ):
            predicate_symbols.append(node["name"])
        if isinstance(node.get("predicate_type"), str):
            predicate_types.append(node["predicate_type"])
        if node.get("type") == "Entity":
            for key in ("name", "variable", "value"):
                value = node.get(key)
                if isinstance(value, str):
                    entity_symbols.append(value)
        if node.get("type") == "State" and isinstance(node.get("name"), str):
            state_symbols.append(node["name"])
        for key in ("source_state", "state_scale", "target_state"):
            value = node.get(key)
            if isinstance(value, str):
                state_symbols.append(value)
        if (
            set(node) == {"variable", "type"}
            and isinstance(node.get("variable"), str)
            and isinstance(node.get("type"), str)
        ):
            binder_signatures.append(f"{node['variable']}:{node['type']}")
        if (
            node.get("kind") == "sigma"
            and isinstance(node.get("witness"), str)
            and isinstance(node.get("type"), str)
        ):
            binder_signatures.append(f"{node['witness']}:{node['type']}")

    quantifier_signatures: list[str] = []
    quantifiers = ast.get("quantifiers") if isinstance(ast, dict) else None
    if isinstance(quantifiers, dict):
        quantifier_signatures = [
            f"{key}:{value}"
            for key, value in sorted(quantifiers.items())
            if isinstance(value, str)
        ]

    return {
        "kind": ast.get("kind") if isinstance(ast, dict) else None,
        "predicate_symbols": sorted(_unique_strings(predicate_symbols)),
        "predicate_types": sorted(_unique_strings(predicate_types)),
        "entity_symbols": sorted(_unique_strings(entity_symbols)),
        "state_symbols": sorted(_unique_strings(state_symbols)),
        "binder_signatures": binder_signatures,
        "quantifier_signatures": quantifier_signatures,
        "top_level_modifier_count": (
            len(ast.get("modifiers", []))
            if isinstance(ast, dict) and isinstance(ast.get("modifiers"), list)
            else 0
        ),
        "top_level_time_modifier_count": (
            len(ast.get("time_modifiers", []))
            if isinstance(ast, dict) and isinstance(ast.get("time_modifiers"), list)
            else 0
        ),
        "reading_count": (
            len(ast.get("readings", []))
            if isinstance(ast, dict) and isinstance(ast.get("readings"), list)
            else 0
        ),
        "clause_count": (
            len(ast.get("clauses", []))
            if isinstance(ast, dict) and isinstance(ast.get("clauses"), list)
            else 0
        ),
        "subject_count": (
            len(ast.get("subjects", []))
            if isinstance(ast, dict) and isinstance(ast.get("subjects"), list)
            else (
                1
                if isinstance(ast, dict) and isinstance(ast.get("subject"), dict)
                else 0
            )
        ),
        "object_count": (
            len(ast.get("objects", []))
            if isinstance(ast, dict) and isinstance(ast.get("objects"), list)
            else (
                1
                if isinstance(ast, dict) and isinstance(ast.get("object"), dict)
                else 0
            )
        ),
    }


def _safe_rule_token(value: str) -> str:
    token = re.sub(r"[^a-z0-9]+", "_", value.lower()).strip("_")
    return token or "unknown"


def fallback_candidate_rule_id(ast: dict[str, Any]) -> str:
    candidate_ast = ast
    kind = (
        str(candidate_ast.get("kind", "analysis"))
        if isinstance(candidate_ast, dict)
        else "analysis"
    )
    if kind == "repeat" and isinstance(candidate_ast.get("body"), dict):
        candidate_ast = candidate_ast["body"]
    predicate = (
        str(candidate_ast.get("function"))
        if isinstance(candidate_ast, dict) and candidate_ast.get("function")
        else kind
    )
    return f"fallback_{_safe_rule_token(predicate)}_{_safe_rule_token(kind)}_candidate"


def fallback_certification_upgrade_plan(
    sentence: str,
    ast: dict[str, Any],
    dependent_type_translation: str,
) -> dict[str, Any]:
    action_by_gap = {
        "no_registered_construction_rule": (
            "draft_construction_rule",
            "translator/natural_language_pipeline.py",
            "Add a ConstructionRule with accepted examples before fallback.",
        ),
        "no_fragment_specific_readings": (
            "add_semantic_readings_contract",
            "translator/natural_language_pipeline.py",
            "Replace fallback_single_reading with construction-specific checked readings.",
        ),
        "no_construction_hygiene_policy": (
            "add_construction_hygiene_guard",
            "scripts/verify_project.py",
            "Add forbidden Coq/Rocq fragments and verifier fixtures for the new rule.",
        ),
    }
    steps = []
    for gap in fallback_certification_gap_payload():
        action_kind, target_artifact, verification = action_by_gap[gap["id"]]
        steps.append(
            {
                "gap_id": gap["id"],
                "action_kind": action_kind,
                "label": gap["label"],
                "detail": gap["detail"],
                "target_artifact": target_artifact,
                "required_artifact": gap["required_artifact"],
                "verification": verification,
                "can_auto_apply": False,
            }
        )
    return {
        "schema_version": CERTIFICATION_UPGRADE_PLAN_SCHEMA,
        "source_verification_scope": "fallback_shallow",
        "target_certification_level": "construction_rule",
        "candidate_rule_id": fallback_candidate_rule_id(ast),
        "source_sentence": sentence,
        "dependent_type_translation": dependent_type_translation,
        "ast_summary": ast_structure_summary(ast if isinstance(ast, dict) else {}),
        "automation_mode": "human_review_required",
        "can_auto_apply": False,
        "steps": steps,
        "verification_commands": [
            "python3 scripts/verify_project.py --require-coq --require-docx",
        ],
    }


def fallback_construction_rule_registration_preflight(
    candidate_rule_id: str,
    candidate_analyzer: str,
    accepted_examples: list[str],
    semantic_reading_drafts: list[dict[str, Any]],
    forbidden_coq_fragments: list[str],
    test_draft: dict[str, Any],
) -> dict[str, Any]:
    registered_rules = construction_rules()
    registered_rule_ids = sorted(rule.rule_id for rule in registered_rules)
    registered_analyzers = sorted(rule.analyzer.__name__ for rule in registered_rules)
    checks = [
        {
            "id": "candidate_rule_id_unique",
            "ok": candidate_rule_id not in registered_rule_ids,
            "detail": "Candidate rule id must not collide with an existing ConstructionRule.",
        },
        {
            "id": "candidate_analyzer_unique",
            "ok": candidate_analyzer not in registered_analyzers,
            "detail": "Candidate analyzer name must not collide with an existing analyzer.",
        },
        {
            "id": "accepted_examples_present",
            "ok": bool(accepted_examples) and all(isinstance(item, str) and item for item in accepted_examples),
            "detail": "At least one accepted example must be available for registration tests.",
        },
        {
            "id": "semantic_reading_draft_present",
            "ok": bool(semantic_reading_drafts)
            and all(isinstance(item, dict) and item.get("name") for item in semantic_reading_drafts),
            "detail": "A promoted rule needs named, construction-specific semantic-reading drafts.",
        },
        {
            "id": "hygiene_policy_present",
            "ok": bool(forbidden_coq_fragments),
            "detail": "A promoted rule needs forbidden Coq/Rocq fragments for construction hygiene.",
        },
        {
            "id": "test_draft_present",
            "ok": bool(test_draft)
            and test_draft.get("expected_verification_scope_kind") == "registered_construction"
            and test_draft.get("expected_certification_level") == "construction_rule",
            "detail": "A promoted rule needs a test draft expecting construction-rule certification.",
        },
    ]
    blocking_issues = [
        str(check["id"])
        for check in checks
        if check.get("ok") is not True
    ]
    return {
        "schema_version": CONSTRUCTION_RULE_REGISTRATION_PREFLIGHT_SCHEMA,
        "candidate_rule_id": candidate_rule_id,
        "candidate_analyzer": candidate_analyzer,
        "ok": not blocking_issues,
        "registration_status": "human_review_required" if not blocking_issues else "blocked",
        "can_auto_register": False,
        "human_review_required": True,
        "checks": checks,
        "blocking_issues": blocking_issues,
        "registered_rule_count": len(registered_rule_ids),
        "registered_analyzer_count": len(registered_analyzers),
        "required_human_review_fields": [
            "analyzer implementation",
            "construction-specific semantic readings",
            "construction hygiene policy",
            "registration tests",
        ],
    }


def fallback_construction_rule_draft(
    sentence: str,
    ast: dict[str, Any],
    dependent_type_translation: str,
) -> dict[str, Any]:
    candidate_rule_id = fallback_candidate_rule_id(ast)
    reading_name = f"{candidate_rule_id}_single_reading"
    analyzer_name = f"{candidate_rule_id}_pipeline"
    forbidden_coq_fragments = [
        "Parameter Event : Type.",
        "exists e : Event",
        "Parameter Agent :",
        "Parameter Theme :",
    ]
    semantic_reading_drafts = [
        {
            "name": reading_name,
            "source": candidate_rule_id,
            "scope": "single_reading",
            "dependent_type_translation": dependent_type_translation,
            "coq_definition": reading_name,
            "attachment_summary_kind": "none",
        }
    ]
    test_draft = {
        "positive_sentence": sentence,
        "expected_verification_scope_kind": "registered_construction",
        "expected_certification_level": "construction_rule",
        "expected_forbidden_fragment_count": len(forbidden_coq_fragments),
    }
    return {
        "schema_version": CONSTRUCTION_RULE_DRAFT_SCHEMA,
        "source_verification_scope": "fallback_shallow",
        "candidate_rule_id": candidate_rule_id,
        "candidate_analyzer": analyzer_name,
        "label": f"Promote fallback candidate {candidate_rule_id}",
        "phenomenon": "Human-reviewed promotion of a shallow fallback analysis",
        "accepted_examples": [sentence],
        "semantic_reading_drafts": semantic_reading_drafts,
        "hygiene_policy_draft": {
            "forbidden_coq_fragments": forbidden_coq_fragments,
            "reason": (
                "The promoted construction should not reintroduce event variables "
                "or untyped neo-Davidsonian role predicates."
            ),
        },
        "test_draft": test_draft,
        "registration_preflight": fallback_construction_rule_registration_preflight(
            candidate_rule_id,
            analyzer_name,
            [sentence],
            semantic_reading_drafts,
            forbidden_coq_fragments,
            test_draft,
        ),
        "ast_summary": ast_structure_summary(ast if isinstance(ast, dict) else {}),
        "automation_mode": "human_review_required",
        "can_auto_apply": False,
        "patch_text_preview": "\n".join(
            [
                "# Candidate ConstructionRule draft",
                f"rule_id = {candidate_rule_id!r}",
                f"analyzer = {analyzer_name!r}",
                f"accepted_examples = {[sentence]!r}",
                f"semantic_reading = {reading_name!r}",
                f"forbidden_coq_fragments = {forbidden_coq_fragments!r}",
            ]
        ),
        "verification_commands": [
            "python3 scripts/verify_project.py --require-coq --require-docx",
        ],
    }


def atom(pred: str, *args: str) -> dict[str, Any]:
    return {"pred": pred, "args": list(args)}


def event_formula(*items: dict[str, Any]) -> dict[str, Any]:
    return {"exists": ["e"], "body": {"and": list(items)}}


def connective_for_coordinator(coordinator: str) -> str:
    return BOOLEAN_COORDINATORS[coordinator]


def single_boolean_coordinator(tokens: list[str]) -> tuple[str, int] | None:
    matches = [
        (token, index)
        for index, token in enumerate(tokens)
        if token in BOOLEAN_COORDINATORS
    ]
    if len(matches) != 1:
        return None
    return matches[0]


def single_temporal_relation_connector(tokens: list[str]) -> tuple[str, int] | None:
    matches = [
        (token, index)
        for index, token in enumerate(tokens)
        if token in TEMPORAL_RELATION_CONNECTORS
    ]
    if len(matches) != 1:
        return None
    return matches[0]


def strip_coordination_pair_marker(
    tokens: list[str],
    marker: str,
    coordinator: str,
    *,
    allow_initial_marker: bool,
) -> list[str]:
    if tokens.count(marker) != 1 or coordinator not in tokens:
        return tokens
    marker_index = tokens.index(marker)
    if marker_index == 0 and allow_initial_marker:
        return tokens[1:]
    if (
        marker_index > 0
        and marker_index + 1 < len(tokens)
        and is_likely_surface_verb(tokens[marker_index + 1])
    ):
        return [*tokens[:marker_index], *tokens[marker_index + 1 :]]
    return tokens


def strip_surface_coordination_marker(tokens: list[str]) -> list[str]:
    tokens = strip_coordination_pair_marker(
        tokens,
        "either",
        "or",
        allow_initial_marker=True,
    )
    tokens = strip_coordination_pair_marker(
        tokens,
        "both",
        "and",
        allow_initial_marker=False,
    )
    return tokens


def parse_relative_restrictor_variants(
    tokens: list[str],
) -> list[tuple[list[str], list[dict[str, Any]]]] | None:
    marker_indices = [
        index
        for index, token in enumerate(tokens)
        if token in RELATIVE_RESTRICTOR_MARKERS
    ]
    if not marker_indices:
        return [(tokens, [])]
    if len(marker_indices) != 1:
        return parse_stacked_simple_relative_restrictor_variants(tokens, marker_indices)
    marker_index = marker_indices[0]
    if marker_index == 0:
        return None
    relative_tokens = list(tokens[marker_index + 1 :])
    if not relative_tokens:
        return None
    leading_modifiers: list[dict[str, Any]] = []
    while relative_tokens and relative_tokens[0] in COMMON_ADVERBS:
        leading_modifiers.append(modifier_record(relative_tokens.pop(0)))
    if not relative_tokens:
        return None
    relative_surface = relative_tokens[0]
    if not (
        is_likely_surface_verb(relative_surface)
        or is_likely_transitive_verb(relative_surface)
    ):
        return None
    predicate = lemma_verb(relative_surface)
    if len(relative_tokens) == 1 or not is_likely_transitive_verb(relative_surface):
        trailing_modifiers = split_common_adv_and_time_modifiers(relative_tokens[1:])
        if trailing_modifiers is None:
            return None
        adv_modifiers, time_modifiers = trailing_modifiers
        modifiers = [*leading_modifiers, *adv_modifiers]
        if is_likely_transitive_verb(relative_surface):
            return None
        restrictor: dict[str, Any] = {
            "predicate": predicate,
            "predicate_type": (
                MODIFIER_INDEXED_UNARY_RELATION if modifiers else "Entity -> Prop"
            ),
            "surface": " ".join(tokens[marker_index:]),
            "marker": tokens[marker_index],
            "relative_verb": relative_surface,
            "kind": "relative_clause_restrictor",
        }
        if modifiers:
            restrictor["modifiers"] = modifiers
        if time_modifiers:
            restrictor["time_modifiers"] = time_modifiers
        return [(tokens[:marker_index], [restrictor])]
    if len(relative_tokens) >= 2 and is_likely_transitive_verb(relative_surface):
        relative_object_np_variants = parse_relative_object_np_variants(
            relative_tokens[1:]
        )
        if relative_object_np_variants:
            variants: list[tuple[list[str], list[dict[str, Any]]]] = []
            for (
                object_np,
                adv_modifiers,
                time_modifiers,
                _consumed,
            ) in relative_object_np_variants:
                modifiers = [*leading_modifiers, *adv_modifiers]
                restrictor = {
                    "predicate": predicate,
                    "predicate_type": (
                        MODIFIER_INDEXED_BINARY_RELATION
                        if modifiers
                        else "Entity -> Entity -> Prop"
                    ),
                    "surface": " ".join(tokens[marker_index:]),
                    "marker": tokens[marker_index],
                    "relative_verb": relative_surface,
                    "object_np": object_np,
                    "kind": "relative_clause_restrictor",
                }
                if modifiers:
                    restrictor["modifiers"] = modifiers
                if time_modifiers:
                    restrictor["time_modifiers"] = time_modifiers
                variants.append((tokens[:marker_index], [restrictor]))
            return variants
        named_object_variants = parse_relative_named_object_variants(
            relative_tokens[1:]
        )
        if not named_object_variants:
            return None
        variants: list[tuple[list[str], list[dict[str, Any]]]] = []
        for obj, adv_modifiers, time_modifiers, _consumed in named_object_variants:
            modifiers = [*leading_modifiers, *adv_modifiers]
            restrictor = {
                "predicate": predicate,
                "predicate_type": (
                    MODIFIER_INDEXED_BINARY_RELATION
                    if modifiers
                    else "Entity -> Entity -> Prop"
                ),
                "surface": " ".join(tokens[marker_index:]),
                "marker": tokens[marker_index],
                "relative_verb": relative_surface,
                "object": obj,
                "kind": "relative_clause_restrictor",
            }
            if modifiers:
                restrictor["modifiers"] = modifiers
            if time_modifiers:
                restrictor["time_modifiers"] = time_modifiers
            variants.append((tokens[:marker_index], [restrictor]))
        return variants
    return None


def parse_stacked_simple_relative_restrictor_variants(
    tokens: list[str],
    marker_indices: list[int],
) -> list[tuple[list[str], list[dict[str, Any]]]] | None:
    if not marker_indices or marker_indices[0] == 0:
        return None
    nominal_tokens = tokens[: marker_indices[0]]
    restrictors: list[dict[str, Any]] = []
    coordination_count = 0
    for offset, marker_index in enumerate(marker_indices):
        next_marker = (
            marker_indices[offset + 1]
            if offset + 1 < len(marker_indices)
            else len(tokens)
        )
        segment = tokens[marker_index:next_marker]
        relative_tokens = segment[1:]
        if not relative_tokens:
            return None
        coordination_to_next = False
        if offset + 1 < len(marker_indices) and relative_tokens[-1:] == ["and"]:
            relative_tokens = relative_tokens[:-1]
            segment = segment[:-1]
            coordination_to_next = True
            coordination_count += 1
        elif offset + 1 < len(marker_indices) and relative_tokens[-1:] == ["or"]:
            return None
        leading_modifiers: list[dict[str, Any]] = []
        while relative_tokens and relative_tokens[0] in COMMON_ADVERBS:
            leading_modifiers.append(modifier_record(relative_tokens.pop(0)))
        if not relative_tokens:
            return None
        relative_surface = relative_tokens[0]
        if (
            not is_likely_surface_verb(relative_surface)
            or is_likely_transitive_verb(relative_surface)
        ):
            return None
        trailing_modifiers = split_common_adv_and_time_modifiers(relative_tokens[1:])
        if trailing_modifiers is None:
            return None
        adv_modifiers, time_modifiers = trailing_modifiers
        modifiers = [*leading_modifiers, *adv_modifiers]
        restrictor: dict[str, Any] = {
            "predicate": lemma_verb(relative_surface),
            "predicate_type": (
                MODIFIER_INDEXED_UNARY_RELATION if modifiers else "Entity -> Prop"
            ),
            "surface": " ".join(segment),
            "marker": segment[0],
            "relative_verb": relative_surface,
            "kind": "relative_clause_restrictor",
            "stacked_relative_index": offset,
            "stacked_relative_count": len(marker_indices),
        }
        if coordination_to_next:
            restrictor["stacked_relative_coordination_to_next"] = "and"
        if modifiers:
            restrictor["modifiers"] = modifiers
        if time_modifiers:
            restrictor["time_modifiers"] = time_modifiers
        restrictors.append(restrictor)
    if coordination_count:
        for restrictor in restrictors:
            restrictor["stacked_relative_coordination_count"] = coordination_count
    return [(nominal_tokens, restrictors)]


def parse_relative_restrictor(
    tokens: list[str],
) -> tuple[list[str], list[dict[str, Any]]] | None:
    variants = parse_relative_restrictor_variants(tokens)
    if not variants:
        return None
    return variants[0]


def relative_object_np_base(
    determiner: str,
    nominal_tokens: list[str],
    surface_tokens: list[str],
) -> dict[str, Any]:
    predicates = [lemma_verb(token) for token in nominal_tokens]
    head = predicates[-1]
    variable = f"x_rel_{head}"
    restrictors = [
        {"predicate": predicate, "predicate_type": "Entity -> Prop"}
        for predicate in predicates
    ]
    return {
        "surface": " ".join(surface_tokens),
        "quantifier": determiner,
        "variable": variable,
        "type": "Entity",
        "head": head,
        "adjectives": predicates[:-1],
        "restrictors": restrictors,
    }


def pp_restrictor_record(preposition: str, phrase: list[str]) -> dict[str, Any]:
    expression = modifier_expression(preposition, phrase)
    return {
        "predicate": f"{normalize_surface_name(expression)}_np",
        "predicate_type": "Entity -> Prop",
        "expression": expression,
        "semantic_role": modifier_semantic_role(expression),
        "argument": clean_phrase(phrase),
        "kind": "pp_restrictor",
    }


def split_non_temporal_pp(
    tokens: list[str],
    start: int,
    forbidden_pp_tokens: set[str],
) -> tuple[str, list[str], int] | None:
    if start >= len(tokens):
        return None
    preposition = tokens[start]
    if preposition not in PREPOSITIONS:
        return None
    if temporal_prepositional_phrase_value(tokens, start) is not None:
        return None
    idx = start + 1
    phrase: list[str] = []
    while idx < len(tokens):
        if any(token not in ARTICLES for token in phrase):
            if tokens[idx] in PREPOSITIONS:
                break
            if tokens[idx] in COMMON_ADVERBS:
                break
            if tokens[idx] in TEMPORAL_ADVERBS:
                break
            if temporal_phrase_value(tokens, idx) is not None:
                break
            if temporal_prepositional_phrase_value(tokens, idx) is not None:
                break
        if tokens[idx] in forbidden_pp_tokens:
            return None
        phrase.append(tokens[idx])
        idx += 1
    if not any(token not in ARTICLES for token in phrase):
        return None
    return preposition, phrase, idx


def parse_relative_object_np_variants(
    tokens: list[str],
) -> list[tuple[dict[str, Any], list[dict[str, Any]], list[dict[str, str]], int]]:
    if len(tokens) < 2 or tokens[0] not in RELATIVE_OBJECT_NP_DETERMINERS:
        return []
    forbidden_nominal_tokens = (
        COMMON_ADVERBS
        | TEMPORAL_ADVERBS
        | COUNT_WORDS
        | COUNT_NOUNS
        | set(BOOLEAN_COORDINATORS)
        | set(TEMPORAL_RELATION_CONNECTORS)
        | UNSUPPORTED_CERTIFIED_CLAUSE_MARKERS
        | PREPOSITIONS
    )
    forbidden_pp_tokens = (
        (SUPPORTED_SCOPE_DETERMINERS - ARTICLES)
        | COMMON_ADVERBS
        | TEMPORAL_ADVERBS
        | COUNT_WORDS
        | COUNT_NOUNS
        | set(BOOLEAN_COORDINATORS)
        | set(TEMPORAL_RELATION_CONNECTORS)
        | UNSUPPORTED_CERTIFIED_CLAUSE_MARKERS
    )
    variants: list[
        tuple[dict[str, Any], list[dict[str, Any]], list[dict[str, str]], int]
    ] = []
    for end in range(2, len(tokens) + 1):
        nominal_tokens = tokens[1:end]
        if (
            not nominal_tokens
            or any(token in forbidden_nominal_tokens for token in nominal_tokens)
            or any(token in RELATIVE_OBJECT_NP_DETERMINERS for token in nominal_tokens)
        ):
            continue
        base_np = relative_object_np_base(tokens[0], nominal_tokens, tokens[:end])
        trailing_modifiers = split_common_adv_and_time_modifiers(tokens[end:])
        if trailing_modifiers is not None:
            adv_modifiers, time_modifiers = trailing_modifiers
            variants.append((base_np, adv_modifiers, time_modifiers, end))

        pp = split_non_temporal_pp(tokens, end, forbidden_pp_tokens)
        if pp is None:
            continue
        preposition, phrase, pp_end = pp
        trailing_after_pp = split_common_adv_and_time_modifiers(tokens[pp_end:])
        if trailing_after_pp is None:
            continue
        trailing_adv_modifiers, trailing_time_modifiers = trailing_after_pp
        expression = modifier_expression(preposition, phrase)

        object_restrictor_np = copy.deepcopy(base_np)
        object_restrictor_np["surface"] = " ".join(tokens[:pp_end])
        pp_restrictor = pp_restrictor_record(preposition, phrase)
        object_restrictor_np["restrictors"].append(pp_restrictor)
        object_restrictor_np["postnominal_restrictors"] = [pp_restrictor]
        variants.append(
            (
                object_restrictor_np,
                trailing_adv_modifiers,
                trailing_time_modifiers,
                pp_end,
            )
        )

        relative_adv_modifiers = [
            modifier_record(expression),
            *trailing_adv_modifiers,
        ]
        variants.append(
            (
                base_np,
                relative_adv_modifiers,
                trailing_time_modifiers,
                pp_end,
            )
        )
    return variants


def parse_relative_object_np(
    tokens: list[str],
) -> tuple[dict[str, Any], list[dict[str, Any]], list[dict[str, str]], int] | None:
    variants = parse_relative_object_np_variants(tokens)
    if not variants:
        return None
    return variants[0]


def parse_relative_named_object_variants(
    tokens: list[str],
) -> list[tuple[dict[str, str], list[dict[str, Any]], list[dict[str, str]], int]]:
    if not tokens:
        return []
    object_surface = tokens[0]
    if (
        object_surface in SUPPORTED_SCOPE_DETERMINERS
        or object_surface in COMMON_ADVERBS
        or object_surface in TEMPORAL_ADVERBS
        or object_surface in COUNT_WORDS
        or object_surface in COUNT_NOUNS
        or object_surface in PREPOSITIONS
        or object_surface in UNSUPPORTED_CERTIFIED_CLAUSE_MARKERS
        or object_surface in BOOLEAN_COORDINATORS
        or object_surface in TEMPORAL_RELATION_CONNECTORS
        or temporal_phrase_value(tokens, 0) is not None
    ):
        return []

    obj = {
        "name": normalize_surface_name(object_surface),
        "surface": object_surface,
        "type": "Entity",
    }
    variants: list[
        tuple[dict[str, str], list[dict[str, Any]], list[dict[str, str]], int]
    ] = []
    trailing_modifiers = split_common_adv_and_time_modifiers(tokens[1:])
    if trailing_modifiers is not None:
        adv_modifiers, time_modifiers = trailing_modifiers
        variants.append((obj, adv_modifiers, time_modifiers, 1))

    forbidden_pp_tokens = (
        SUPPORTED_SCOPE_DETERMINERS
        | COMMON_ADVERBS
        | TEMPORAL_ADVERBS
        | COUNT_WORDS
        | COUNT_NOUNS
        | set(BOOLEAN_COORDINATORS)
        | set(TEMPORAL_RELATION_CONNECTORS)
        | UNSUPPORTED_CERTIFIED_CLAUSE_MARKERS
    )
    pp = split_non_temporal_pp(tokens, 1, forbidden_pp_tokens - ARTICLES)
    if pp is None:
        return variants
    preposition, phrase, pp_end = pp
    trailing_after_pp = split_common_adv_and_time_modifiers(tokens[pp_end:])
    if trailing_after_pp is None:
        return variants
    trailing_adv_modifiers, trailing_time_modifiers = trailing_after_pp
    variants.append(
        (
            obj,
            [
                modifier_record(modifier_expression(preposition, phrase)),
                *trailing_adv_modifiers,
            ],
            trailing_time_modifiers,
            pp_end,
        )
    )
    return variants


def quantifier_np(tokens: list[str]) -> dict[str, Any] | None:
    if not tokens:
        return None
    forbidden_nominal_tokens = (
        SUPPORTED_SCOPE_DETERMINERS
        | COMMON_ADVERBS
        | TEMPORAL_ADVERBS
        | COUNT_WORDS
        | COUNT_NOUNS
        | ARTICLES
        | set(BOOLEAN_COORDINATORS)
        | set(TEMPORAL_RELATION_CONNECTORS)
        | (UNSUPPORTED_CERTIFIED_CLAUSE_MARKERS - RELATIVE_RESTRICTOR_MARKERS)
    )
    forbidden_pp_tokens = (
        (SUPPORTED_SCOPE_DETERMINERS - ARTICLES)
        | COMMON_ADVERBS
        | TEMPORAL_ADVERBS
        | COUNT_WORDS
        | COUNT_NOUNS
        | set(BOOLEAN_COORDINATORS)
        | set(TEMPORAL_RELATION_CONNECTORS)
        | UNSUPPORTED_CERTIFIED_CLAUSE_MARKERS
    )
    nominal_tokens: list[str] = []
    idx = 0
    while idx < len(tokens) and tokens[idx] not in PREPOSITIONS:
        nominal_tokens.append(tokens[idx])
        idx += 1
    if not nominal_tokens:
        return None
    relative_parse = parse_relative_restrictor(nominal_tokens)
    if relative_parse is None:
        return None
    nominal_tokens, relative_restrictors = relative_parse
    if relative_restrictors and idx < len(tokens):
        return None
    if any(token in forbidden_nominal_tokens for token in nominal_tokens):
        return None
    if not nominal_tokens:
        return None
    predicates = [lemma_verb(token) for token in nominal_tokens]
    head = predicates[-1]
    restrictors = [
        {"predicate": predicate, "predicate_type": "Entity -> Prop"}
        for predicate in predicates
    ]
    restrictors.extend(relative_restrictors)
    postnominal_restrictors: list[dict[str, Any]] = []
    while idx < len(tokens):
        preposition = tokens[idx]
        if preposition not in PREPOSITIONS:
            return None
        if temporal_prepositional_phrase_value(tokens, idx) is not None:
            return None
        idx += 1
        phrase: list[str] = []
        while idx < len(tokens) and tokens[idx] not in PREPOSITIONS:
            if tokens[idx] in forbidden_pp_tokens:
                return None
            phrase.append(tokens[idx])
            idx += 1
        if not any(token not in ARTICLES for token in phrase):
            return None
        pp_restrictor = pp_restrictor_record(preposition, phrase)
        restrictors.append(pp_restrictor)
        postnominal_restrictors.append(pp_restrictor)
    np = {
        "surface": " ".join(tokens),
        "head": head,
        "adjectives": predicates[:-1],
        "restrictors": restrictors,
    }
    if postnominal_restrictors:
        np["postnominal_restrictors"] = postnominal_restrictors
    if relative_restrictors:
        np["relative_clause_restrictors"] = relative_restrictors
    return np


def quantifier_np_variants(tokens: list[str]) -> list[dict[str, Any]]:
    if not tokens:
        return []
    if not any(token in RELATIVE_RESTRICTOR_MARKERS for token in tokens):
        np = quantifier_np(tokens)
        return [np] if np is not None else []

    forbidden_nominal_tokens = (
        SUPPORTED_SCOPE_DETERMINERS
        | COMMON_ADVERBS
        | TEMPORAL_ADVERBS
        | COUNT_WORDS
        | COUNT_NOUNS
        | ARTICLES
        | set(BOOLEAN_COORDINATORS)
        | set(TEMPORAL_RELATION_CONNECTORS)
        | (UNSUPPORTED_CERTIFIED_CLAUSE_MARKERS - RELATIVE_RESTRICTOR_MARKERS)
    )
    relative_variants = parse_relative_restrictor_variants(tokens)
    if relative_variants is None:
        return []
    variants: list[dict[str, Any]] = []
    for nominal_tokens, relative_restrictors in relative_variants:
        if not relative_restrictors:
            continue
        if not nominal_tokens or any(token in PREPOSITIONS for token in nominal_tokens):
            continue
        if any(token in forbidden_nominal_tokens for token in nominal_tokens):
            continue
        predicates = [lemma_verb(token) for token in nominal_tokens]
        head = predicates[-1]
        restrictors = [
            {"predicate": predicate, "predicate_type": "Entity -> Prop"}
            for predicate in predicates
        ]
        restrictors.extend(relative_restrictors)
        variants.append(
            {
                "surface": " ".join(tokens),
                "head": head,
                "adjectives": predicates[:-1],
                "restrictors": restrictors,
                "relative_clause_restrictors": relative_restrictors,
            }
        )
    return variants


def relative_object_np_has_postnominal_restrictor(
    restrictor: dict[str, Any],
) -> bool:
    object_np = restrictor.get("object_np")
    return isinstance(object_np, dict) and bool(object_np.get("postnominal_restrictors"))


def quantifier_np_relative_attachment_kind(
    np: dict[str, Any],
    role: str,
) -> str | None:
    relative_restrictors = np.get("relative_clause_restrictors", [])
    if not isinstance(relative_restrictors, list):
        return None
    has_adv = any(
        isinstance(restrictor, dict) and bool(restrictor.get("modifiers"))
        for restrictor in relative_restrictors
    )
    has_time = any(
        isinstance(restrictor, dict) and bool(restrictor.get("time_modifiers"))
        for restrictor in relative_restrictors
    )
    has_object_np_restrictor = any(
        isinstance(restrictor, dict)
        and relative_object_np_has_postnominal_restrictor(restrictor)
        for restrictor in relative_restrictors
    )
    has_stacked_restrictor = len(
        [restrictor for restrictor in relative_restrictors if isinstance(restrictor, dict)]
    ) > 1
    parts: list[str] = []
    if has_stacked_restrictor:
        parts.append("stacked_restrictor")
    if has_adv:
        parts.append("adv")
    if has_time:
        parts.append("time")
    if has_object_np_restrictor:
        parts.append("object_np_restrictor")
    if not parts:
        return None
    return f"{role}_relative_{'_'.join(parts)}"


def split_preverbal_adv_modifiers(
    tokens: list[str],
) -> tuple[list[str], list[dict[str, Any]]]:
    noun_tokens = list(tokens)
    modifiers: list[dict[str, Any]] = []
    while noun_tokens and noun_tokens[-1] in COMMON_ADVERBS:
        modifiers.insert(0, modifier_record(noun_tokens.pop()))
    return noun_tokens, modifiers


def quantifier_scope_predicate_names(readings: list[dict[str, Any]]) -> list[str]:
    names: list[str] = []
    for reading in readings:
        for binder in reading.get("scope_order", []):
            if not isinstance(binder, dict):
                continue
            restrictors = binder.get("restrictors")
            if isinstance(restrictors, list):
                for restrictor in restrictors:
                    if isinstance(restrictor, dict) and isinstance(
                        restrictor.get("predicate"),
                        str,
                    ):
                        names.append(restrictor["predicate"])
                continue
            if isinstance(binder.get("predicate"), str):
                    names.append(binder["predicate"])
    return unique_names(names)


def quantifier_scope_restrictor_predicate_declarations(
    readings: list[dict[str, Any]],
) -> list[tuple[str, str]]:
    declarations: list[tuple[str, str]] = []
    for reading in readings:
        for binder in reading.get("scope_order", []):
            if not isinstance(binder, dict):
                continue
            restrictors = binder.get("restrictors")
            if not isinstance(restrictors, list):
                restrictors = [
                    {
                        "predicate": binder.get("predicate"),
                        "predicate_type": binder.get("predicate_type", "Entity -> Prop"),
                    }
                ]
            for restrictor in restrictors:
                if not isinstance(restrictor, dict):
                    continue
                predicate = restrictor.get("predicate")
                predicate_type = restrictor.get("predicate_type")
                if isinstance(predicate, str) and isinstance(predicate_type, str):
                    declarations.append((predicate, predicate_type))
                object_np = restrictor.get("object_np")
                if isinstance(object_np, dict):
                    for np_restrictor in object_np.get("restrictors", []):
                        if not isinstance(np_restrictor, dict):
                            continue
                        np_predicate = np_restrictor.get("predicate")
                        np_predicate_type = np_restrictor.get("predicate_type")
                        if isinstance(np_predicate, str) and isinstance(
                            np_predicate_type,
                            str,
                        ):
                            declarations.append((np_predicate, np_predicate_type))
    return unique_typed_declarations(declarations)


def quantifier_scope_relative_object_names(readings: list[dict[str, Any]]) -> list[str]:
    names: list[str] = []
    for reading in readings:
        for binder in reading.get("scope_order", []):
            if not isinstance(binder, dict):
                continue
            restrictors = binder.get("restrictors")
            if not isinstance(restrictors, list):
                continue
            for restrictor in restrictors:
                if not isinstance(restrictor, dict):
                    continue
                obj = restrictor.get("object")
                if isinstance(obj, dict) and isinstance(obj.get("name"), str):
                    names.append(obj["name"])
    return unique_names(names)


def quantifier_scope_restrictor_time_modifiers(
    readings: list[dict[str, Any]],
) -> list[dict[str, str]]:
    modifiers: list[dict[str, str]] = []
    for reading in readings:
        for binder in reading.get("scope_order", []):
            if not isinstance(binder, dict):
                continue
            restrictors = binder.get("restrictors")
            if not isinstance(restrictors, list):
                continue
            for restrictor in restrictors:
                if not isinstance(restrictor, dict):
                    continue
                time_modifiers = restrictor.get("time_modifiers", [])
                if isinstance(time_modifiers, list):
                    modifiers.extend(
                        modifier
                        for modifier in time_modifiers
                        if isinstance(modifier, dict)
                    )
    return modifiers


def quantifier_scope_restrictor_adv_modifiers(
    readings: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    modifiers: list[dict[str, Any]] = []
    for reading in readings:
        for binder in reading.get("scope_order", []):
            if not isinstance(binder, dict):
                continue
            restrictors = binder.get("restrictors")
            if not isinstance(restrictors, list):
                continue
            for restrictor in restrictors:
                if not isinstance(restrictor, dict):
                    continue
                adv_modifiers = restrictor.get("modifiers", [])
                if isinstance(adv_modifiers, list):
                    modifiers.extend(
                        modifier
                        for modifier in adv_modifiers
                        if isinstance(modifier, dict)
                    )
    return modifiers


def quantifier_scope_reading(
    subject_np: dict[str, Any],
    subject_quantifier: str,
    verb: str,
    object_np: dict[str, Any],
    object_quantifier: str,
    subject_first: bool,
    modifiers: list[dict[str, Any]] | None = None,
    time_modifiers: list[dict[str, str]] | None = None,
    name_suffix: str | None = None,
    attachment: dict[str, Any] | None = None,
) -> dict[str, Any]:
    modifiers = list(modifiers or [])
    subject_noun = subject_np["head"]
    object_noun = object_np["head"]
    subject = {
        "role": "subject",
        "quantifier": subject_quantifier,
        "variable": f"x_{subject_noun}",
        "predicate": subject_noun,
        "predicate_type": "Entity -> Prop",
        "surface": subject_np["surface"],
        "restrictors": subject_np["restrictors"],
    }
    obj = {
        "role": "object",
        "quantifier": object_quantifier,
        "variable": f"x_{object_noun}",
        "predicate": object_noun,
        "predicate_type": "Entity -> Prop",
        "surface": object_np["surface"],
        "restrictors": object_np["restrictors"],
    }
    scope_order = [subject, obj] if subject_first else [obj, subject]
    relation = {
        "predicate": verb,
        "predicate_type": (
            "forall n : nat, ModifierSeq n -> Entity -> Entity -> PropT"
            if modifiers
            else "Entity -> Entity -> Prop"
        ),
        "arguments": [subject["variable"], obj["variable"]],
    }
    if subject_first:
        name = f"{subject_quantifier}_{subject_noun}_wide_scope"
        quantifier = subject_quantifier
    else:
        name = f"{object_quantifier}_{object_noun}_wide_scope"
        quantifier = object_quantifier
    if name_suffix:
        name = f"{name}_{name_suffix}"
    reading = {
        "name": name,
        "quantifier": quantifier,
        "scope_order": scope_order,
        "relation": relation,
        "modifiers": modifiers,
        "time_modifiers": list(time_modifiers or []),
    }
    if attachment is not None:
        reading["attachment"] = attachment
    return reading


def quantifier_readings_use_modifier_family(readings: list[dict[str, Any]]) -> bool:
    return any(
        bool(reading.get("modifiers"))
        or reading.get("relation", {}).get("predicate_type")
        == MODIFIER_INDEXED_BINARY_RELATION
        for reading in readings
    )


def quantifier_readings_use_restrictor_modifier_family(
    readings: list[dict[str, Any]],
) -> bool:
    return any(
        isinstance(binder, dict)
        and isinstance(binder.get("restrictors"), list)
        and any(
            isinstance(restrictor, dict)
            and (
                bool(restrictor.get("modifiers"))
                or restrictor.get("predicate_type")
                in {MODIFIER_INDEXED_UNARY_RELATION, MODIFIER_INDEXED_BINARY_RELATION}
            )
            for restrictor in binder["restrictors"]
        )
        for reading in readings
        for binder in reading.get("scope_order", [])
    )


def lift_quantifier_readings_to_modifier_family(
    readings: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    if not any(bool(reading.get("modifiers")) for reading in readings):
        return readings
    for reading in readings:
        reading["relation"]["predicate_type"] = MODIFIER_INDEXED_BINARY_RELATION
    return readings


def lift_quantifier_restrictors_to_modifier_family(
    readings: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    modifier_family_by_predicate: dict[str, str] = {}
    for reading in readings:
        for binder in reading.get("scope_order", []):
            if not isinstance(binder, dict):
                continue
            restrictors = binder.get("restrictors")
            if not isinstance(restrictors, list):
                continue
            for restrictor in restrictors:
                if not isinstance(restrictor, dict):
                    continue
                predicate = restrictor.get("predicate")
                predicate_type = restrictor.get("predicate_type")
                if not isinstance(predicate, str):
                    continue
                if predicate_type in {
                    MODIFIER_INDEXED_UNARY_RELATION,
                    MODIFIER_INDEXED_BINARY_RELATION,
                }:
                    modifier_family_by_predicate[predicate] = predicate_type

    if not modifier_family_by_predicate:
        return readings

    for reading in readings:
        for binder in reading.get("scope_order", []):
            if not isinstance(binder, dict):
                continue
            restrictors = binder.get("restrictors")
            if not isinstance(restrictors, list):
                continue
            for restrictor in restrictors:
                if not isinstance(restrictor, dict):
                    continue
                predicate = restrictor.get("predicate")
                lifted_type = modifier_family_by_predicate.get(predicate)
                if lifted_type is None:
                    continue
                restrictor["predicate_type"] = lifted_type
                restrictor.setdefault("modifiers", [])
    return readings


def render_quantifier_relation(reading: dict[str, Any], *, coq: bool) -> str:
    relation = reading["relation"]
    args = relation["arguments"]
    modifiers = reading.get("modifiers", [])
    if relation.get("predicate_type") == MODIFIER_INDEXED_BINARY_RELATION:
        if coq:
            return (
                f"{relation['predicate']} {len(modifiers)} "
                f"{coq_modifier_sequence(modifiers)} {' '.join(args)}"
            )
        if modifiers:
            return (
                f"{relation['predicate']}({len(modifiers)})"
                f"({readable_modifier_arguments(modifiers)}, {', '.join(args)})"
            )
        return (
            f"{relation['predicate']}(0)"
            f"({', '.join(args)})"
        )
    if coq:
        return f"{relation['predicate']} {' '.join(args)}"
    return f"{relation['predicate']}({', '.join(args)})"


def render_quantifier_time_wrapped_reading(
    body: str,
    time_modifiers: list[dict[str, str]],
    *,
    coq: bool,
) -> str:
    for modifier in time_modifiers:
        if coq:
            body = f"{modifier['operator']}_T {modifier['argument']} ({body})"
        else:
            body = f"{modifier['operator']}_T({modifier['argument']}, {body})"
    return body


def render_entity_predicate_applications(
    restrictors: list[dict[str, Any]],
    variable: str,
    *,
    coq: bool,
) -> str:
    applications = [
        f"{restrictor['predicate']} {variable}"
        if coq
        else f"{restrictor['predicate']}({variable})"
        for restrictor in restrictors
    ]
    if len(applications) == 1:
        return applications[0]
    connective = " /\\ " if coq else " and "
    return f"({connective.join(applications)})"


def relative_binary_object_variable(restrictor: dict[str, Any]) -> str:
    object_np = restrictor.get("object_np")
    if isinstance(object_np, dict):
        return object_np["variable"]
    return restrictor["object"]["name"]


def render_binary_restrictor_relation(
    restrictor: dict[str, Any],
    subject_variable: str,
    *,
    coq: bool,
) -> str:
    predicate = restrictor["predicate"]
    predicate_type = restrictor.get("predicate_type")
    modifiers = restrictor.get("modifiers", [])
    obj = relative_binary_object_variable(restrictor)
    if predicate_type == MODIFIER_INDEXED_BINARY_RELATION:
        if coq:
            return (
                f"{predicate} {len(modifiers)} "
                f"{coq_modifier_sequence(modifiers)} {subject_variable} {obj}"
            )
        if modifiers:
            return (
                f"{predicate}({len(modifiers)})"
                f"({readable_modifier_arguments(modifiers)}, {subject_variable}, {obj})"
            )
        return f"{predicate}(0)({subject_variable}, {obj})"
    if coq:
        return f"{predicate} {subject_variable} {obj}"
    return f"{predicate}({subject_variable}, {obj})"


def render_relative_object_np_application(
    restrictor: dict[str, Any],
    relation_application: str,
    *,
    coq: bool,
) -> str:
    object_np = restrictor.get("object_np")
    if not isinstance(object_np, dict):
        return relation_application
    variable = object_np["variable"]
    restrictor_application = render_entity_predicate_applications(
        object_np["restrictors"],
        variable,
        coq=coq,
    )
    if coq:
        return f"exists {variable} : Entity, {restrictor_application} /\\ {relation_application}"
    return f"exists {variable} : Entity. {restrictor_application} and {relation_application}"


def quantifier_binder_restrictor_applications(
    binder: dict[str, Any],
    *,
    coq: bool,
) -> list[str]:
    var = binder["variable"]
    restrictors = binder.get("restrictors")
    if not isinstance(restrictors, list) or not restrictors:
        restrictors = [
            {
                "predicate": binder["predicate"],
                "predicate_type": binder.get("predicate_type", "Entity -> Prop"),
            }
        ]
    applications: list[str] = []
    for restrictor in restrictors:
        predicate = restrictor["predicate"]
        predicate_type = restrictor.get("predicate_type")
        modifiers = restrictor.get("modifiers", [])
        if predicate_type == MODIFIER_INDEXED_BINARY_RELATION:
            application = render_binary_restrictor_relation(
                restrictor,
                var,
                coq=coq,
            )
            application = render_relative_object_np_application(
                restrictor,
                application,
                coq=coq,
            )
        elif predicate_type == MODIFIER_INDEXED_UNARY_RELATION:
            if coq:
                application = (
                    f"{predicate} {len(modifiers)} "
                    f"{coq_modifier_sequence(modifiers)} {var}"
                )
            else:
                if modifiers:
                    application = (
                        f"{predicate}({len(modifiers)})"
                        f"({readable_modifier_arguments(modifiers)}, {var})"
                    )
                else:
                    application = f"{predicate}(0)({var})"
        elif predicate_type == "Entity -> Entity -> Prop":
            application = render_binary_restrictor_relation(
                restrictor,
                var,
                coq=coq,
            )
            application = render_relative_object_np_application(
                restrictor,
                application,
                coq=coq,
            )
        else:
            application = f"{predicate} {var}" if coq else f"{predicate}({var})"
        applications.append(
            render_quantifier_time_wrapped_reading(
                application,
                restrictor.get("time_modifiers", []),
                coq=coq,
            )
        )
    return applications


def render_quantifier_binder_restrictor(
    binder: dict[str, Any],
    *,
    coq: bool,
) -> str:
    applications = quantifier_binder_restrictor_applications(binder, coq=coq)
    if len(applications) == 1:
        return applications[0]
    connective = " /\\ " if coq else " and "
    return f"({connective.join(applications)})"


def render_quantifier_binder(
    binder: dict[str, Any],
    body: str,
    *,
    coq: bool,
) -> str:
    var = binder["variable"]
    quantifier = binder.get("quantifier")
    restrictor_application = render_quantifier_binder_restrictor(binder, coq=coq)
    if coq:
        if quantifier in EXISTENTIAL_SCOPE_DETERMINERS:
            if body.startswith("forall "):
                body = f"({body})"
            return f"exists {var} : Entity, {restrictor_application} /\\ {body}"
        if quantifier in UNIVERSAL_SCOPE_DETERMINERS:
            return f"forall {var} : Entity, {restrictor_application} -> {body}"
        if quantifier in NEGATIVE_SCOPE_DETERMINERS:
            return f"forall {var} : Entity, {restrictor_application} -> ~ ({body})"
    else:
        if quantifier in EXISTENTIAL_SCOPE_DETERMINERS:
            if body.startswith("forall "):
                body = f"({body})"
            return f"exists {var} : Entity. {restrictor_application} and {body}"
        if quantifier in UNIVERSAL_SCOPE_DETERMINERS:
            return f"forall {var} : Entity. {restrictor_application} -> {body}"
        if quantifier in NEGATIVE_SCOPE_DETERMINERS:
            return f"forall {var} : Entity. {restrictor_application} -> not ({body})"
    raise ValueError(f"unsupported quantifier: {quantifier!r}")


def render_quantifier_reading(reading: dict[str, Any], coq: bool = False) -> str:
    body = render_quantifier_relation(reading, coq=coq)
    for binder in reversed(reading["scope_order"]):
        body = render_quantifier_binder(binder, body, coq=coq)
    return render_quantifier_time_wrapped_reading(
        body,
        reading.get("time_modifiers", []),
        coq=coq,
    )


def quantifier_scope_coq(reading: dict[str, Any]) -> str:
    return f"Definition {reading['name']} : Prop := {render_quantifier_reading(reading, coq=True)}."


def quantifier_scope_family(subject_quantifier: str, object_quantifier: str) -> str:
    if subject_quantifier == object_quantifier:
        return subject_quantifier
    if (
        subject_quantifier in EXISTENTIAL_SCOPE_DETERMINERS
        and object_quantifier in EXISTENTIAL_SCOPE_DETERMINERS
    ):
        return "existential"
    if (
        subject_quantifier in UNIVERSAL_SCOPE_DETERMINERS
        and object_quantifier in UNIVERSAL_SCOPE_DETERMINERS
    ):
        return "universal"
    if (
        subject_quantifier in NEGATIVE_SCOPE_DETERMINERS
        and object_quantifier in NEGATIVE_SCOPE_DETERMINERS
    ):
        return "negative"
    if (
        subject_quantifier in NEGATIVE_SCOPE_DETERMINERS
        or object_quantifier in NEGATIVE_SCOPE_DETERMINERS
    ):
        return "mixed_negative"
    return "mixed"


def semantic_reading(
    *,
    name: str,
    dependent_type_translation: str,
    coq_definition: str | None = None,
    scope: str | None = None,
    scope_policy: dict[str, str] | None = None,
    type_check: dict[str, Any] | None = None,
    source: str | None = None,
    attachment_summary: dict[str, Any] | None = None,
    reading_explanation: str | None = None,
) -> dict[str, Any]:
    normalized_scope = scope or "unspecified"
    normalized_source = source or "unspecified"
    normalized_attachment = (
        copy.deepcopy(attachment_summary)
        if isinstance(attachment_summary, dict)
        else empty_attachment_summary()
    )
    normalized_explanation = reading_explanation or semantic_reading_default_explanation(
        name=name,
        source=normalized_source,
        scope=normalized_scope,
        attachment_summary=normalized_attachment,
    )
    reading: dict[str, Any] = {
        "name": name,
        "source": normalized_source,
        "scope": normalized_scope,
        "dependent_type_translation": dependent_type_translation,
        "coq_definition": coq_definition or "",
        "attachment_summary": normalized_attachment,
        "reading_explanation": normalized_explanation,
    }
    if scope_policy is not None:
        reading["scope_policy"] = scope_policy
    if type_check is not None:
        reading["type_check"] = type_check
    return reading


SEMANTIC_READING_FAILURE_LABELS = {
    "duplicate_reading_name": "duplicate reading names",
    "export_count_mismatch": "wrong number of exported propositions",
    "malformed_readings": "malformed semantic readings",
    "missing_coq_export": "missing Coq/Rocq exports",
    "missing_readings": "missing semantic readings",
    "reading_type_check_failed": "reading-local type check failed",
    "unknown_reading_error": "unclassified semantic-reading error",
}


def semantic_reading_error_kind(error: str) -> str:
    if "must not be empty" in error:
        return "missing_readings"
    if "must export exactly one Prop/PropT definition" in error:
        return "export_count_mismatch"
    if " is duplicated" in error:
        return "duplicate_reading_name"
    if " is not exported" in error:
        return "missing_coq_export"
    if ".type_check must have ok=true" in error:
        return "reading_type_check_failed"
    if (
        "must be a list" in error
        or "must be an object" in error
        or ".name must be a non-empty string" in error
        or ".dependent_type_translation must be a non-empty string" in error
        or ".coq_definition must be a non-empty string" in error
        or ".reading_explanation must be a non-empty string" in error
        or "missing required contract field(s)" in error
        or ".scope must be a non-empty string" in error
        or ".source must be a non-empty string" in error
        or ".attachment_summary must be an object" in error
        or ".attachment_summary missing field(s)" in error
        or ".attachment_summary.kind must be a non-empty string" in error
        or ".attachment_summary." in error
        or ".scope_policy must map strings to strings" in error
    ):
        return "malformed_readings"
    return "unknown_reading_error"


def semantic_reading_failure_kinds(errors: list[str]) -> list[str]:
    observed = {semantic_reading_error_kind(error) for error in errors}
    return sorted(observed)


def semantic_reading_failure_summary(kinds: list[str]) -> str:
    if not kinds:
        return "No semantic-reading failures."
    labels = [SEMANTIC_READING_FAILURE_LABELS.get(kind, kind) for kind in kinds]
    return "Semantic-reading failure kind(s): " + ", ".join(labels) + "."


def semantic_readings_repair_details(
    *,
    exported_definitions: list[str] | None = None,
    expected_coq_definitions: list[str] | None = None,
    missing_coq_definitions: list[str] | None = None,
    duplicate_reading_names: list[str] | None = None,
    malformed_reading_indices: list[int] | None = None,
    failed_type_check_indices: list[int] | None = None,
    expected_export_count: int | None = None,
    observed_export_count: int | None = None,
) -> dict[str, Any]:
    exported = sorted(exported_definitions or [])
    observed = len(exported) if observed_export_count is None else observed_export_count
    return {
        "exported_definitions": exported,
        "expected_coq_definitions": sorted(expected_coq_definitions or []),
        "missing_coq_definitions": sorted(missing_coq_definitions or []),
        "duplicate_reading_names": sorted(duplicate_reading_names or []),
        "malformed_reading_indices": sorted(set(malformed_reading_indices or [])),
        "failed_type_check_indices": sorted(set(failed_type_check_indices or [])),
        "expected_export_count": expected_export_count,
        "observed_export_count": observed,
    }


def semantic_readings_check_payload(
    *,
    checked: bool,
    ok: bool | None,
    reading_count: int,
    errors: list[str],
    repair_details: dict[str, Any] | None = None,
) -> dict[str, Any]:
    failure_kinds = semantic_reading_failure_kinds(errors)
    return {
        "checked": checked,
        "ok": ok,
        "reading_count": reading_count,
        "errors": errors,
        "failure_kinds": failure_kinds,
        "failure_summary": semantic_reading_failure_summary(failure_kinds),
        "repair_details": repair_details or semantic_readings_repair_details(),
    }


def check_semantic_readings(
    readings: list[dict[str, Any]] | None,
    coq_code: str = "",
) -> dict[str, Any]:
    exported_definitions = exported_prop_definition_names(coq_code) if coq_code else []
    if readings is None:
        return semantic_readings_check_payload(
            checked=False,
            ok=None,
            reading_count=0,
            errors=[],
            repair_details=semantic_readings_repair_details(
                exported_definitions=exported_definitions,
            ),
        )
    errors: list[str] = []
    if not isinstance(readings, list):
        return semantic_readings_check_payload(
            checked=True,
            ok=False,
            reading_count=0,
            errors=["semantic_readings must be a list"],
            repair_details=semantic_readings_repair_details(
                exported_definitions=exported_definitions,
            ),
        )
    if not readings:
        errors.append("semantic_readings must not be empty when present")
    expected_coq_definitions: list[str] = []
    missing_coq_definitions: list[str] = []
    duplicate_reading_names: list[str] = []
    malformed_reading_indices: list[int] = []
    failed_type_check_indices: list[int] = []
    seen_names: set[str] = set()
    exported_definition_set = set(exported_definitions)
    for index, reading in enumerate(readings):
        if not isinstance(reading, dict):
            errors.append(f"semantic_readings[{index}] must be an object")
            malformed_reading_indices.append(index)
            continue
        malformed = False
        missing_contract_fields = sorted(
            field for field in SEMANTIC_READING_CONTRACT_FIELDS if field not in reading
        )
        if missing_contract_fields:
            errors.append(
                "semantic_readings"
                f"[{index}] missing required contract field(s): "
                + ", ".join(missing_contract_fields)
            )
            malformed = True
        name = reading.get("name")
        if not isinstance(name, str) or not name:
            errors.append(f"semantic_readings[{index}].name must be a non-empty string")
            malformed = True
        elif name in seen_names:
            errors.append(f"semantic_readings name {name!r} is duplicated")
            duplicate_reading_names.append(name)
        else:
            seen_names.add(name)
        source = reading.get("source")
        if not isinstance(source, str) or not source.strip():
            errors.append(f"semantic_readings[{index}].source must be a non-empty string")
            malformed = True
        scope = reading.get("scope")
        if not isinstance(scope, str) or not scope.strip():
            errors.append(f"semantic_readings[{index}].scope must be a non-empty string")
            malformed = True
        translation = reading.get("dependent_type_translation")
        if not isinstance(translation, str) or not translation.strip():
            errors.append(
                "semantic_readings"
                f"[{index}].dependent_type_translation must be a non-empty string"
            )
            malformed = True
        coq_definition = reading.get("coq_definition")
        if not isinstance(coq_definition, str) or not coq_definition:
            errors.append(
                f"semantic_readings[{index}].coq_definition must be a non-empty string"
            )
            malformed = True
        else:
            expected_coq_definitions.append(coq_definition)
        if (
            isinstance(coq_definition, str)
            and coq_definition
            and coq_code
            and coq_definition not in exported_definition_set
        ):
            errors.append(
                "semantic_readings"
                f"[{index}].coq_definition {coq_definition!r} is not exported"
            )
            missing_coq_definitions.append(coq_definition)
        scope_policy = reading.get("scope_policy")
        if scope_policy is not None and (
            not isinstance(scope_policy, dict)
            or any(
                not isinstance(key, str) or not isinstance(value, str)
                for key, value in scope_policy.items()
            )
        ):
            errors.append(f"semantic_readings[{index}].scope_policy must map strings to strings")
            malformed = True
        reading_explanation = reading.get("reading_explanation")
        if reading_explanation is not None and (
            not isinstance(reading_explanation, str) or not reading_explanation.strip()
        ):
            errors.append(
                f"semantic_readings[{index}].reading_explanation must be a non-empty string"
            )
            malformed = True
        attachment_summary = reading.get("attachment_summary")
        if not isinstance(attachment_summary, dict):
            errors.append(f"semantic_readings[{index}].attachment_summary must be an object")
            malformed = True
        else:
            missing_attachment_fields = sorted(
                field
                for field in SEMANTIC_READING_ATTACHMENT_FIELDS
                if field not in attachment_summary
            )
            if missing_attachment_fields:
                errors.append(
                    "semantic_readings"
                    f"[{index}].attachment_summary missing field(s): "
                    + ", ".join(missing_attachment_fields)
                )
                malformed = True
            kind = attachment_summary.get("kind")
            if not isinstance(kind, str) or not kind.strip():
                errors.append(
                    f"semantic_readings[{index}].attachment_summary.kind "
                    "must be a non-empty string"
                )
                malformed = True
            for field in (
                "typed_modifiers",
                "typed_np_restrictors",
                "typed_time_modifiers",
                "relative_objects",
            ):
                value = attachment_summary.get(field)
                if not isinstance(value, list):
                    errors.append(
                        "semantic_readings"
                        f"[{index}].attachment_summary.{field} must be a list"
                    )
                    malformed = True
        type_check = reading.get("type_check")
        if type_check is not None:
            if not isinstance(type_check, dict):
                errors.append(f"semantic_readings[{index}].type_check must be an object")
                malformed = True
            elif type_check.get("ok") is not True:
                errors.append(f"semantic_readings[{index}].type_check must have ok=true")
                failed_type_check_indices.append(index)
        else:
            errors.append(f"semantic_readings[{index}].type_check must be an object")
            malformed = True
        if malformed:
            malformed_reading_indices.append(index)
    return semantic_readings_check_payload(
        checked=True,
        ok=not errors,
        reading_count=len(readings),
        errors=errors,
        repair_details=semantic_readings_repair_details(
            exported_definitions=exported_definitions,
            expected_coq_definitions=expected_coq_definitions,
            missing_coq_definitions=missing_coq_definitions,
            duplicate_reading_names=duplicate_reading_names,
            malformed_reading_indices=malformed_reading_indices,
            failed_type_check_indices=failed_type_check_indices,
        ),
    )


def single_semantic_reading_payload(
    *,
    name: str,
    dependent_type_translation: str,
    coq_code: str,
    coq_definition: str,
    type_check: dict[str, Any],
    source: str,
    scope: str | None = None,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    reading_type_check = {
        "ok": type_check.get("ok") is True,
        "type": type_check.get("type"),
        "errors": type_check.get("errors", []),
    }
    for field in ("incompatible_state_pairs",):
        if field in type_check:
            reading_type_check[field] = type_check[field]
    readings = [
        semantic_reading(
            name=name,
            dependent_type_translation=dependent_type_translation,
            coq_definition=coq_definition,
            scope=scope,
            type_check=reading_type_check,
            source=source,
        )
    ]
    return readings, check_semantic_readings(readings, coq_code)


def attach_single_semantic_reading(
    result: dict[str, Any],
    *,
    name: str,
    coq_definition: str,
    source: str,
    scope: str | None = None,
) -> dict[str, Any]:
    semantic_readings, semantic_readings_check = single_semantic_reading_payload(
        name=name,
        dependent_type_translation=result["dependent_type_translation"],
        coq_code=result.get("coq_code", ""),
        coq_definition=coq_definition,
        type_check=result.get("type_check", {}),
        source=source,
        scope=scope,
    )
    result["semantic_readings"] = semantic_readings
    result["semantic_readings_check"] = semantic_readings_check
    event_semantics = result.setdefault("event_semantics", {})
    event_semantics["semantic_readings"] = semantic_readings
    event_semantics["semantic_readings_check"] = semantic_readings_check
    return result


def exported_prop_definition_names(coq_code: str) -> list[str]:
    names = re.findall(
        r"(?m)^Definition\s+([A-Za-z_][A-Za-z0-9_]*)\s*:\s*(?:Prop|PropT)\b",
        coq_code,
    )
    return [
        name for name in names
        if not name.endswith("_semantic_preservation_obligation")
    ]


def attach_default_registered_semantic_reading(
    result: dict[str, Any],
    rule: ConstructionRule,
) -> dict[str, Any]:
    if "semantic_readings" in result or "semantic_readings_check" in result:
        return result

    definition_names = exported_prop_definition_names(result.get("coq_code", ""))
    if len(definition_names) != 1:
        semantic_readings_check = semantic_readings_check_payload(
            checked=True,
            ok=False,
            reading_count=0,
            errors=[
                (
                    "registered construction outputs without explicit semantic_readings "
                    "must export exactly one Prop/PropT definition"
                )
            ],
            repair_details=semantic_readings_repair_details(
                exported_definitions=definition_names,
                expected_export_count=1,
                observed_export_count=len(definition_names),
            ),
        )
        result["semantic_readings"] = []
        result["semantic_readings_check"] = semantic_readings_check
        event_semantics = result.setdefault("event_semantics", {})
        event_semantics["semantic_readings"] = []
        event_semantics["semantic_readings_check"] = semantic_readings_check
        return result

    return attach_single_semantic_reading(
        result,
        name=f"{rule.rule_id}_single_reading",
        coq_definition=definition_names[0],
        source=rule.rule_id,
        scope="registered_single_reading",
    )


def typed_modifier_summary(
    modifier: dict[str, Any],
    site: str,
) -> dict[str, str]:
    summary = {
        "site": site,
        "name": str(modifier.get("name", "")),
        "type": str(modifier.get("type", "Adv")),
    }
    expression = modifier.get("expression")
    if isinstance(expression, str) and expression:
        summary["expression"] = expression
    semantic_role = modifier.get("semantic_role")
    if isinstance(semantic_role, str) and semantic_role:
        summary["semantic_role"] = semantic_role
    return summary


def typed_time_modifier_summary(
    modifier: dict[str, Any],
    site: str,
) -> dict[str, str]:
    summary = {
        "site": site,
        "operator": str(modifier.get("operator", "")),
        "argument": str(modifier.get("argument", "")),
        "type": "Time",
    }
    return summary


def typed_np_restrictor_summary(
    restrictor: dict[str, Any],
    site: str,
) -> dict[str, str]:
    summary = {
        "site": site,
        "predicate": str(restrictor.get("predicate", "")),
        "predicate_type": str(restrictor.get("predicate_type", "Entity -> Prop")),
    }
    expression = restrictor.get("expression")
    if isinstance(expression, str) and expression:
        summary["expression"] = expression
    semantic_role = restrictor.get("semantic_role")
    if isinstance(semantic_role, str) and semantic_role:
        summary["semantic_role"] = semantic_role
    return summary


def unique_summary_records(records: list[dict[str, str]]) -> list[dict[str, str]]:
    seen: set[tuple[tuple[str, str], ...]] = set()
    unique_records: list[dict[str, str]] = []
    for record in records:
        key = tuple(sorted(record.items()))
        if key in seen:
            continue
        seen.add(key)
        unique_records.append(record)
    return unique_records


def collect_np_attachment_summary(
    np: dict[str, Any],
    site: str,
    typed_modifiers: list[dict[str, str]],
    typed_time_modifiers: list[dict[str, str]],
    typed_np_restrictors: list[dict[str, str]],
    relative_objects: list[dict[str, str]],
) -> None:
    restrictors = np.get("restrictors", [])
    if not isinstance(restrictors, list):
        return
    for restrictor in restrictors:
        if not isinstance(restrictor, dict):
            continue
        kind = restrictor.get("kind")
        if kind == "relative_clause_restrictor":
            relative_site = f"{site}_relative"
            modifiers = restrictor.get("modifiers", [])
            if isinstance(modifiers, list):
                typed_modifiers.extend(
                    typed_modifier_summary(modifier, relative_site)
                    for modifier in modifiers
                    if isinstance(modifier, dict)
                )
            time_modifiers = restrictor.get("time_modifiers", [])
            if isinstance(time_modifiers, list):
                typed_time_modifiers.extend(
                    typed_time_modifier_summary(modifier, relative_site)
                    for modifier in time_modifiers
                    if isinstance(modifier, dict)
                )
            relative_object = restrictor.get("object")
            if isinstance(relative_object, dict) and isinstance(
                relative_object.get("name"),
                str,
            ):
                relative_objects.append(
                    {
                        "site": relative_site,
                        "name": relative_object["name"],
                        "type": str(relative_object.get("type", "Entity")),
                    }
                )
            object_np = restrictor.get("object_np")
            if isinstance(object_np, dict):
                collect_np_attachment_summary(
                    object_np,
                    f"{relative_site}_object",
                    typed_modifiers,
                    typed_time_modifiers,
                    typed_np_restrictors,
                    relative_objects,
                )
            continue
        if kind == "pp_restrictor":
            typed_np_restrictors.append(
                typed_np_restrictor_summary(restrictor, f"{site}_np")
            )


def quantifier_attachment_summary(reading: dict[str, Any]) -> dict[str, Any]:
    attachment = reading.get("attachment")
    if not isinstance(attachment, dict):
        return {}
    noun_phrases = attachment.get("noun_phrases", {})
    typed_modifiers: list[dict[str, str]] = []
    typed_time_modifiers: list[dict[str, str]] = []
    typed_np_restrictors: list[dict[str, str]] = []
    relative_objects: list[dict[str, str]] = []
    for modifier in attachment.get("modifiers", []):
        if isinstance(modifier, dict):
            typed_modifiers.append(typed_modifier_summary(modifier, "clause"))
    for modifier in attachment.get("time_modifiers", []):
        if isinstance(modifier, dict):
            typed_time_modifiers.append(typed_time_modifier_summary(modifier, "clause"))
    if isinstance(noun_phrases, dict):
        for role in ("subject", "object"):
            np = noun_phrases.get(role)
            if isinstance(np, dict):
                collect_np_attachment_summary(
                    np,
                    role,
                    typed_modifiers,
                    typed_time_modifiers,
                    typed_np_restrictors,
                    relative_objects,
                )
    return {
        "kind": str(attachment.get("kind", "plain")),
        "subject_relative_attachment_kind": attachment.get(
            "subject_relative_attachment_kind"
        ),
        "object_relative_attachment_kind": attachment.get(
            "object_relative_attachment_kind"
        ),
        "object_np_has_postnominal_restrictor": bool(
            attachment.get("object_np_has_postnominal_restrictor")
        ),
        "typed_modifiers": unique_summary_records(typed_modifiers),
        "typed_time_modifiers": unique_summary_records(typed_time_modifiers),
        "typed_np_restrictors": unique_summary_records(typed_np_restrictors),
        "relative_objects": unique_summary_records(relative_objects),
    }


def _summary_prefix(record: dict[str, str]) -> str:
    site = str(record.get("site", ""))
    return f"{site}: " if site else ""


def _typed_modifier_explanation_items(records: Any) -> list[str]:
    if not isinstance(records, list):
        return []
    items: list[str] = []
    for record in records:
        if not isinstance(record, dict):
            continue
        name = str(record.get("name", ""))
        if not name:
            continue
        modifier_type = str(record.get("type", "Adv"))
        items.append(f"{_summary_prefix(record)}{name} : {modifier_type}")
    return items


def _typed_time_modifier_explanation_items(records: Any) -> list[str]:
    if not isinstance(records, list):
        return []
    items: list[str] = []
    for record in records:
        if not isinstance(record, dict):
            continue
        operator = str(record.get("operator", ""))
        argument = str(record.get("argument", ""))
        if not operator or not argument:
            continue
        modifier_type = str(record.get("type", "Time"))
        items.append(
            f"{_summary_prefix(record)}{operator}_T({argument}) : {modifier_type}"
        )
    return items


def _typed_np_restrictor_explanation_items(records: Any) -> list[str]:
    if not isinstance(records, list):
        return []
    items: list[str] = []
    for record in records:
        if not isinstance(record, dict):
            continue
        predicate = str(record.get("predicate", ""))
        if not predicate:
            continue
        predicate_type = str(record.get("predicate_type", "Entity -> Prop"))
        items.append(f"{_summary_prefix(record)}{predicate} : {predicate_type}")
    return items


def _relative_object_explanation_items(records: Any) -> list[str]:
    if not isinstance(records, list):
        return []
    items: list[str] = []
    for record in records:
        if not isinstance(record, dict):
            continue
        name = str(record.get("name", ""))
        if not name:
            continue
        object_type = str(record.get("type", "Entity"))
        items.append(f"{_summary_prefix(record)}{name} : {object_type}")
    return items


def quantifier_attachment_explanation(summary: dict[str, Any]) -> str:
    kind = str(summary.get("kind", "plain"))
    clauses = [f"Attachment reading {kind}."]
    modifier_items = _typed_modifier_explanation_items(summary.get("typed_modifiers"))
    np_restrictor_items = _typed_np_restrictor_explanation_items(
        summary.get("typed_np_restrictors")
    )
    time_items = _typed_time_modifier_explanation_items(
        summary.get("typed_time_modifiers")
    )
    relative_object_items = _relative_object_explanation_items(
        summary.get("relative_objects")
    )
    if modifier_items:
        clauses.append(
            "Adv modifier(s) "
            + "; ".join(modifier_items)
            + " fill ModifierSeq slots and modify predicates, not Entity constants."
        )
    if np_restrictor_items:
        clauses.append(
            "NP restrictor(s) "
            + "; ".join(np_restrictor_items)
            + " constrain entity binders, not predicate-level Adv slots."
        )
    if time_items:
        clauses.append(
            "Time modifier(s) "
            + "; ".join(time_items)
            + " wrap Prop/PropT readings with temporal operators."
        )
    if relative_object_items:
        clauses.append(
            "Relative object(s) "
            + "; ".join(relative_object_items)
            + " remain Entity arguments of the relative predicate."
        )
    if len(clauses) == 1:
        clauses.append(
            "No extra PP or relative-clause attachment is active beyond the scope order."
        )
    return " ".join(clauses)


def quantifier_semantic_readings(readings: list[dict[str, Any]]) -> list[dict[str, Any]]:
    semantic_readings: list[dict[str, Any]] = []
    for reading in readings:
        semantic = semantic_reading(
            name=reading["name"],
            dependent_type_translation=render_quantifier_reading(reading),
            coq_definition=reading["name"],
            scope="_then_".join(binder["role"] for binder in reading["scope_order"]),
            type_check={"ok": True, "type": "Prop", "errors": []},
            source="quantifier_scope",
        )
        attachment_summary = quantifier_attachment_summary(reading)
        if attachment_summary:
            semantic["attachment_summary"] = attachment_summary
            semantic["reading_explanation"] = quantifier_attachment_explanation(
                attachment_summary
            )
        semantic_readings.append(semantic)
    return semantic_readings


def check_quantifier_scope_binder_restrictors(
    errors: list[str],
    binder: dict[str, Any],
    context: str,
) -> None:
    restrictors = binder.get("restrictors")
    if restrictors is None:
        return
    if not isinstance(restrictors, list) or not restrictors:
        errors.append(f"{context}.restrictors must be a non-empty list")
        return
    restrictor_predicates: list[str] = []
    for restrictor_index, restrictor in enumerate(restrictors):
        if not isinstance(restrictor, dict):
            errors.append(f"{context}.restrictors[{restrictor_index}] must be an object")
            continue
        predicate = restrictor.get("predicate")
        if not isinstance(predicate, str) or not predicate:
            errors.append(
                f"{context}.restrictors[{restrictor_index}].predicate must be non-empty"
            )
        else:
            restrictor_predicates.append(predicate)
        predicate_type = restrictor.get("predicate_type")
        modifier_family_types = {
            MODIFIER_INDEXED_UNARY_RELATION,
            MODIFIER_INDEXED_BINARY_RELATION,
        }
        if predicate_type not in {
            "Entity -> Prop",
            "Entity -> Entity -> Prop",
            *modifier_family_types,
        }:
            errors.append(
                f"{context}.restrictors[{restrictor_index}] "
                "must have predicate type Entity -> Prop, Entity -> Entity -> Prop, "
                "or a ModifierSeq-indexed restrictor type"
            )
        modifiers = restrictor.get("modifiers", [])
        check_coordination_modifiers(
            errors,
            modifiers,
            f"{context}.restrictors[{restrictor_index}]",
        )
        has_modifiers = isinstance(modifiers, list) and bool(modifiers)
        if predicate_type not in modifier_family_types and has_modifiers:
            errors.append(
                f"{context}.restrictors[{restrictor_index}] "
                "must use a ModifierSeq-indexed predicate type when modifiers are present"
            )
        check_time_modifiers(
            errors,
            restrictor.get("time_modifiers", []),
            f"{context}.restrictors[{restrictor_index}]",
        )
        if predicate_type in {"Entity -> Entity -> Prop", MODIFIER_INDEXED_BINARY_RELATION}:
            obj = restrictor.get("object")
            object_np = restrictor.get("object_np")
            has_object = isinstance(obj, dict)
            has_object_np = isinstance(object_np, dict)
            if has_object and has_object_np:
                errors.append(
                    f"{context}.restrictors[{restrictor_index}] "
                    "cannot contain both object and object_np"
                )
            elif has_object:
                if not isinstance(obj.get("name"), str) or not obj["name"]:
                    errors.append(
                        f"{context}.restrictors[{restrictor_index}].object.name "
                        "must be non-empty"
                    )
                if obj.get("type") != "Entity":
                    errors.append(
                        f"{context}.restrictors[{restrictor_index}].object.type "
                        "must be Entity"
                    )
            elif has_object_np:
                check_relative_object_np(
                    errors,
                    object_np,
                    f"{context}.restrictors[{restrictor_index}].object_np",
                )
            else:
                errors.append(
                    f"{context}.restrictors[{restrictor_index}].object must be an object"
                )
    if (
        isinstance(binder.get("predicate"), str)
        and restrictor_predicates
        and binder["predicate"] not in restrictor_predicates
    ):
        errors.append(f"{context}.restrictors must include the head predicate")


def check_relative_object_np(
    errors: list[str],
    object_np: dict[str, Any],
    context: str,
) -> None:
    if object_np.get("quantifier") not in RELATIVE_OBJECT_NP_DETERMINERS:
        errors.append(f"{context}.quantifier must be a supported relative-object NP determiner")
    if not isinstance(object_np.get("variable"), str) or not object_np["variable"]:
        errors.append(f"{context}.variable must be non-empty")
    if object_np.get("type") != "Entity":
        errors.append(f"{context}.type must be Entity")
    if not isinstance(object_np.get("head"), str) or not object_np["head"]:
        errors.append(f"{context}.head must be non-empty")
    restrictors = object_np.get("restrictors")
    if not isinstance(restrictors, list) or not restrictors:
        errors.append(f"{context}.restrictors must be a non-empty list")
        return
    predicates: list[str] = []
    for index, restrictor in enumerate(restrictors):
        if not isinstance(restrictor, dict):
            errors.append(f"{context}.restrictors[{index}] must be an object")
            continue
        predicate = restrictor.get("predicate")
        if not isinstance(predicate, str) or not predicate:
            errors.append(f"{context}.restrictors[{index}].predicate must be non-empty")
        else:
            predicates.append(predicate)
        if restrictor.get("predicate_type") != "Entity -> Prop":
            errors.append(
                f"{context}.restrictors[{index}].predicate_type must be Entity -> Prop"
            )
    if isinstance(object_np.get("head"), str) and object_np["head"] not in predicates:
        errors.append(f"{context}.restrictors must include the head predicate")


def check_quantifier_scope_readings(readings: list[dict[str, Any]]) -> dict[str, Any]:
    errors: list[str] = []
    if len(readings) < 2 or len(readings) % 2 != 0:
        errors.append(f"expected paired scope readings, got {len(readings)}")

    observed_orders: list[tuple[str, ...]] = []
    for index, reading in enumerate(readings):
        order = reading.get("scope_order")
        relation = reading.get("relation")
        if not isinstance(order, list) or len(order) != 2:
            errors.append(f"readings[{index}].scope_order must contain two binders")
            continue
        if not isinstance(relation, dict):
            errors.append(f"readings[{index}].relation must be an object")
            continue

        modifiers = reading.get("modifiers", [])
        check_coordination_modifiers(errors, modifiers, f"readings[{index}]")
        has_modifiers = isinstance(modifiers, list) and bool(modifiers)
        observed_orders.append(tuple(str(binder.get("role")) for binder in order))
        relation_args = relation.get("arguments")
        expected_relation_types = (
            {MODIFIER_INDEXED_BINARY_RELATION}
            if has_modifiers
            else {"Entity -> Entity -> Prop", MODIFIER_INDEXED_BINARY_RELATION}
        )
        if relation.get("predicate_type") not in expected_relation_types:
            errors.append(
                "readings[{}].relation must have type {}".format(
                    index,
                    " or ".join(sorted(expected_relation_types)),
                )
            )
        if not isinstance(relation_args, list) or len(relation_args) != 2:
            errors.append(f"readings[{index}].relation.arguments must contain two entities")
        check_time_modifiers(errors, reading.get("time_modifiers", []), f"readings[{index}]")

        for binder_index, binder in enumerate(order):
            if not isinstance(binder, dict):
                errors.append(f"readings[{index}].scope_order[{binder_index}] must be an object")
                continue
            if binder.get("quantifier") not in SUPPORTED_SCOPE_DETERMINERS:
                errors.append(
                    f"readings[{index}].scope_order[{binder_index}] "
                    "must use a supported scope quantifier"
                )
            if binder.get("predicate_type") != "Entity -> Prop":
                errors.append(
                    f"readings[{index}].scope_order[{binder_index}] "
                    "must have predicate type Entity -> Prop"
                )
            if not binder.get("variable"):
                errors.append(
                    f"readings[{index}].scope_order[{binder_index}] must bind a variable"
                )
            check_quantifier_scope_binder_restrictors(
                errors,
                binder,
                f"readings[{index}].scope_order[{binder_index}]",
            )

    if set(observed_orders) != {("subject", "object"), ("object", "subject")}:
        errors.append(
            "scope readings must include both subject-wide and object-wide orders"
        )
    return {
        "ok": not errors,
        "type": "Prop" if not errors else None,
        "errors": errors,
        "reading_count": len(readings),
    }


def quantifier_scope_pipeline(sentence: str) -> dict[str, Any] | None:
    tokens, fronted_time_modifiers = split_fronted_time_modifiers(tokenize(sentence))
    tokens, fronted_adv_modifiers = split_fronted_adv_modifiers(tokens)
    tokens, later_fronted_time_modifiers = split_fronted_time_modifiers(tokens)
    fronted_time_modifiers = [
        *fronted_time_modifiers,
        *later_fronted_time_modifiers,
    ]
    if len(tokens) < 5 or tokens[0] not in SUPPORTED_SCOPE_DETERMINERS:
        return None
    subject_quantifier = tokens[0]
    parsed_variants: list[dict[str, Any]] = []
    for object_quantifier_index in range(3, len(tokens) - 1):
        object_quantifier = tokens[object_quantifier_index]
        if object_quantifier not in SUPPORTED_SCOPE_DETERMINERS:
            continue
        predicate_index = object_quantifier_index - 1
        if not is_likely_transitive_verb(tokens[predicate_index]):
            continue
        subject_np_tokens, preverbal_adv_modifiers = split_preverbal_adv_modifiers(
            tokens[1:predicate_index]
        )
        subject_np_variants = quantifier_np_variants(subject_np_tokens)
        if not subject_np_variants:
            continue
        verb = lemma_verb(tokens[predicate_index])
        candidate_variants: list[dict[str, Any]] = []
        for subject_np in subject_np_variants:
            for object_np_end in range(object_quantifier_index + 2, len(tokens) + 1):
                object_np_variants = quantifier_np_variants(
                    tokens[object_quantifier_index + 1 : object_np_end]
                )
                if not object_np_variants:
                    continue
                trailing_modifiers = split_shared_adv_and_time_modifiers(
                    tokens[object_np_end:]
                )
                if trailing_modifiers is None:
                    continue
                trailing_adv_modifiers, trailing_time_modifiers = trailing_modifiers
                for object_np in object_np_variants:
                    subject_relative_attachment_kind = (
                        quantifier_np_relative_attachment_kind(subject_np, "subject")
                    )
                    object_relative_attachment_kind = (
                        quantifier_np_relative_attachment_kind(object_np, "object")
                    )
                    if object_np.get("postnominal_restrictors"):
                        attachment_kind = "object_np_restrictor"
                    elif object_relative_attachment_kind:
                        attachment_kind = object_relative_attachment_kind
                    elif subject_relative_attachment_kind:
                        attachment_kind = subject_relative_attachment_kind
                    elif (
                        fronted_adv_modifiers
                        or preverbal_adv_modifiers
                        or trailing_adv_modifiers
                    ):
                        attachment_kind = "clause_adv"
                    else:
                        attachment_kind = "plain"
                    candidate_variants.append(
                        {
                            "subject_np": subject_np,
                            "preverbal_adv_modifiers": preverbal_adv_modifiers,
                            "verb": verb,
                            "object_quantifier": object_quantifier,
                            "object_np": object_np,
                            "trailing_adv_modifiers": trailing_adv_modifiers,
                            "trailing_time_modifiers": trailing_time_modifiers,
                            "attachment": {
                                "kind": attachment_kind,
                                "object_np_has_postnominal_restrictor": bool(
                                    object_np.get("postnominal_restrictors")
                                ),
                                "subject_relative_attachment_kind": (
                                    subject_relative_attachment_kind
                                ),
                                "object_relative_attachment_kind": (
                                    object_relative_attachment_kind
                                ),
                                "clause_adv_modifiers": [
                                    modifier["name"]
                                    for modifier in trailing_adv_modifiers
                                ],
                            },
                        }
                    )
        if candidate_variants:
            parsed_variants = candidate_variants
            break
    if not parsed_variants:
        return None
    primary_variant = parsed_variants[0]
    subject_np = primary_variant["subject_np"]
    preverbal_adv_modifiers = primary_variant["preverbal_adv_modifiers"]
    verb = primary_variant["verb"]
    object_quantifier = primary_variant["object_quantifier"]
    object_np = primary_variant["object_np"]
    trailing_adv_modifiers = primary_variant["trailing_adv_modifiers"]
    trailing_time_modifiers = primary_variant["trailing_time_modifiers"]
    adv_modifiers = [
        *fronted_adv_modifiers,
        *preverbal_adv_modifiers,
        *trailing_adv_modifiers,
    ]
    time_modifiers = [*fronted_time_modifiers, *trailing_time_modifiers]
    attachment_is_ambiguous = len(parsed_variants) > 1
    attachment_kind_counts: dict[str, int] = {}
    for variant in parsed_variants:
        kind = variant["attachment"]["kind"]
        attachment_kind_counts[kind] = attachment_kind_counts.get(kind, 0) + 1
    attachment_kind_seen: dict[str, int] = {}
    attachment_variants: list[dict[str, Any]] = []
    readings: list[dict[str, Any]] = []
    for variant in parsed_variants:
        variant_adv_modifiers = [
            *fronted_adv_modifiers,
            *variant["preverbal_adv_modifiers"],
            *variant["trailing_adv_modifiers"],
        ]
        variant_time_modifiers = [
            *fronted_time_modifiers,
            *variant["trailing_time_modifiers"],
        ]
        attachment = {
            **variant["attachment"],
            "modifiers": variant_adv_modifiers,
            "time_modifiers": variant_time_modifiers,
            "noun_phrases": {
                "subject": variant["subject_np"],
                "object": variant["object_np"],
            },
        }
        attachment_variants.append(attachment)
        kind = variant["attachment"]["kind"]
        name_suffix = None
        if attachment_is_ambiguous and kind != "plain":
            name_suffix = kind
            if attachment_kind_counts[kind] > 1:
                attachment_kind_seen[kind] = attachment_kind_seen.get(kind, 0) + 1
                name_suffix = f"{kind}_{attachment_kind_seen[kind]}"
        readings.extend(
            [
                quantifier_scope_reading(
                    variant["subject_np"],
                    subject_quantifier,
                    verb,
                    variant["object_np"],
                    object_quantifier,
                    subject_first=True,
                    modifiers=variant_adv_modifiers,
                    time_modifiers=variant_time_modifiers,
                    name_suffix=name_suffix,
                    attachment=attachment,
                ),
                quantifier_scope_reading(
                    variant["subject_np"],
                    subject_quantifier,
                    verb,
                    variant["object_np"],
                    object_quantifier,
                    subject_first=False,
                    modifiers=variant_adv_modifiers,
                    time_modifiers=variant_time_modifiers,
                    name_suffix=name_suffix,
                    attachment=attachment,
                ),
            ]
        )
    readings = lift_quantifier_restrictors_to_modifier_family(readings)
    readings = lift_quantifier_readings_to_modifier_family(readings)
    type_check = check_quantifier_scope_readings(readings)
    semantic_readings = quantifier_semantic_readings(readings)
    all_adv_modifiers = quantifier_scope_restrictor_adv_modifiers(readings) + [
        modifier
        for reading in readings
        for modifier in reading.get("modifiers", [])
    ]
    all_time_modifiers = quantifier_scope_restrictor_time_modifiers(readings) + [
        modifier
        for reading in readings
        for modifier in reading.get("time_modifiers", [])
    ]
    uses_relation_modifier_family = quantifier_readings_use_modifier_family(readings)
    uses_modifier_scaffold = (
        uses_relation_modifier_family
        or quantifier_readings_use_restrictor_modifier_family(readings)
    )
    verb_declaration_type = (
        "forall n : nat, ModifierSeq n -> Entity -> Entity -> PropT"
        if uses_relation_modifier_family
        else "Entity -> Entity -> Prop"
    )
    predicate_declarations = unique_typed_declarations(
        [
            *quantifier_scope_restrictor_predicate_declarations(readings),
            (verb, verb_declaration_type),
        ]
    )
    event_semantics = {
        "analysis": "quantifier-scope",
        "source": sentence,
        "quantifiers": {
            "subject": subject_quantifier,
            "object": object_quantifier,
        },
        "noun_phrases": {
            "subject": subject_np,
            "object": object_np,
        },
        "modifiers": adv_modifiers,
        "time_modifiers": time_modifiers,
        "attachment_variants": attachment_variants,
        "readings": [
            {**reading, "formula": render_quantifier_reading(reading)}
            for reading in readings
        ],
        "semantic_readings": semantic_readings,
    }
    coq_code = "\n".join(
        [
            "(* Quantifier-scope scaffold for dependent-type event semantics. *)",
            "Parameter Entity : Type.",
            *(
                [
                    "Definition PropT : Type := Prop.",
                    "Definition Adv : Type := (Entity -> PropT) -> Entity -> PropT.",
                    "Parameter ModifierSeq : nat -> Type.",
                    "Parameter mods_nil : ModifierSeq 0.",
                    "Parameter mods_cons : forall n : nat, Adv -> ModifierSeq n -> ModifierSeq (S n).",
                ]
                if uses_modifier_scaffold
                else []
            ),
            *[
                f"Parameter {name} : Entity."
                for name in quantifier_scope_relative_object_names(readings)
            ],
            *[
                f"Parameter {name} : {type_name}."
                for name, type_name in predicate_declarations
            ],
            *[
                f"Parameter {modifier_name} : Adv."
                for modifier_name in unique_names(
                    [modifier["name"] for modifier in all_adv_modifiers]
                )
            ],
            *[
                f"Parameter {time_argument} : Entity."
                for time_argument in unique_names(
                    [modifier["argument"] for modifier in all_time_modifiers]
                )
            ],
            *(
                [
                    "Parameter at_T : Entity -> Prop -> Prop.",
                    "Parameter during_T : Entity -> Prop -> Prop.",
                ]
                if all_time_modifiers
                else []
            ),
            "",
            *[quantifier_scope_coq(reading) for reading in readings],
            "",
            *[f"Check {reading['name']}." for reading in readings],
            "",
        ]
    )
    semantic_readings_check = check_semantic_readings(semantic_readings, coq_code)
    event_semantics["semantic_readings_check"] = semantic_readings_check
    return {
        "kind": "quantifier_scope_ambiguity",
        "input_sentence": sentence,
        "event_semantics": event_semantics,
        "dependent_type_translation": "\n".join(
            reading["formula"] for reading in event_semantics["readings"]
        ),
        "semantic_readings": semantic_readings,
        "semantic_readings_check": semantic_readings_check,
        "ast": {
            "kind": "scope_ambiguity",
            "quantifier": quantifier_scope_family(subject_quantifier, object_quantifier),
            "quantifiers": {
                "subject": subject_quantifier,
                "object": object_quantifier,
            },
            "noun_phrases": {
                "subject": subject_np,
                "object": object_np,
            },
            "modifiers": adv_modifiers,
            "time_modifiers": time_modifiers,
            "attachment_variants": attachment_variants,
            "readings": readings,
        },
        "type_check": {
            **type_check,
            "note": (
                "Both scope readings are represented with entity predicates "
                "and a binary relation; Adv modifiers stay in a dependent "
                "modifier sequence, and time modifiers, when present, scope "
                "over each quantified proposition; no Event argument is introduced."
            ),
        },
        "coq_code": coq_code,
    }


def negated_coordination_readings(
    subject: str,
    clauses: list[dict[str, Any]],
    time_modifiers: list[dict[str, str]] | None = None,
    connective: str = "and_T",
) -> list[dict[str, Any]]:
    if connective == "or_T":
        return [
            {
                "name": "do_support_negation_wide_disjunction",
                "scope": "negation_over_disjunction",
                "subject": {"name": subject, "type": "Entity"},
                "clauses": clauses,
                "connective": connective,
                "connective_type": "PropT -> PropT -> PropT"
                if any(negated_coordination_clause_uses_propt(clause) for clause in clauses)
                else "Prop -> Prop -> Prop",
                "time_modifiers": list(time_modifiers or []),
            }
        ]
    return [
        {
            "name": "do_support_negation_wide_scope",
            "scope": "negation_over_conjunction",
            "subject": {"name": subject, "type": "Entity"},
            "clauses": clauses,
            "connective": connective,
            "connective_type": "PropT -> PropT -> PropT"
            if any(negated_coordination_clause_uses_propt(clause) for clause in clauses)
            else "Prop -> Prop -> Prop",
            "time_modifiers": list(time_modifiers or []),
        },
        {
            "name": "do_support_negation_distributed_scope",
            "scope": "distributed_negation",
            "subject": {"name": subject, "type": "Entity"},
            "clauses": clauses,
            "connective": connective,
            "connective_type": "PropT -> PropT -> PropT"
            if any(negated_coordination_clause_uses_propt(clause) for clause in clauses)
            else "Prop -> Prop -> Prop",
            "time_modifiers": list(time_modifiers or []),
        },
    ]


def disjunction_of_negations_reading(
    subject: str,
    clauses: list[dict[str, Any]],
    time_modifiers: list[dict[str, str]] | None = None,
) -> dict[str, Any]:
    return {
        "name": "do_support_negation_disjunction_of_negations",
        "scope": "disjunction_of_negations",
        "subject": {"name": subject, "type": "Entity"},
        "clauses": clauses,
        "connective": "or_T",
        "connective_type": "PropT -> PropT -> PropT"
        if any(negated_coordination_clause_uses_propt(clause) for clause in clauses)
        else "Prop -> Prop -> Prop",
        "time_modifiers": list(time_modifiers or []),
    }


def negated_coordination_clause_uses_propt(clause: dict[str, Any]) -> bool:
    predicate_type = str(clause.get("predicate", {}).get("predicate_type", ""))
    return (
        predicate_type.startswith("forall n : nat, ModifierSeq n ->")
        or bool(clause.get("modifiers"))
        or bool(clause.get("time_modifiers"))
        or "modifiers" in clause
        or "time_modifiers" in clause
    )


def negated_coordination_uses_propt(readings: list[dict[str, Any]]) -> bool:
    return any(
        negated_coordination_clause_uses_propt(clause)
        for reading in readings
        for clause in reading.get("clauses", [])
        if isinstance(clause, dict)
    )


def check_negated_coordination_readings(readings: list[dict[str, Any]]) -> dict[str, Any]:
    errors: list[str] = []
    object_declarations: list[tuple[str, str]] = []
    connectives = {str(reading.get("connective", "and_T")) for reading in readings}
    observed_scopes = {str(reading.get("scope")) for reading in readings}
    if connectives == {"and_T"}:
        if len(readings) != 2:
            errors.append(f"expected two negated coordination readings, got {len(readings)}")
        if observed_scopes != {"negation_over_conjunction", "distributed_negation"}:
            errors.append(
                "negated and-coordination readings must include wide and distributed negation"
            )
    elif connectives == {"or_T"}:
        if len(readings) != 1:
            errors.append(
                f"expected one negated disjunction reading, got {len(readings)}"
            )
        if observed_scopes not in (
            {"negation_over_disjunction"},
            {"disjunction_of_negations"},
        ):
            errors.append(
                "negated or-coordination readings must include "
                "negation_over_disjunction or disjunction_of_negations"
            )
    else:
        errors.append("negated coordination readings must use one connective: and_T or or_T")

    for reading_index, reading in enumerate(readings):
        connective = reading.get("connective", "and_T")
        if connective not in {"and_T", "or_T"}:
            errors.append(
                f"readings[{reading_index}].connective must be and_T or or_T"
            )
        subject = reading.get("subject")
        if not isinstance(subject, dict):
            errors.append(f"readings[{reading_index}].subject must be an object")
        else:
            if subject.get("type") != "Entity":
                errors.append(f"readings[{reading_index}].subject must have type Entity")
            if not isinstance(subject.get("name"), str) or not subject.get("name"):
                errors.append(
                    f"readings[{reading_index}].subject.name must be non-empty"
                )

        check_time_modifiers(
            errors,
            reading.get("time_modifiers", []),
            f"readings[{reading_index}]",
        )

        clauses = reading.get("clauses")
        if not isinstance(clauses, list) or len(clauses) != 2:
            errors.append(f"readings[{reading_index}].clauses must contain two items")
            continue
        for clause_index, clause in enumerate(clauses):
            if not isinstance(clause, dict):
                errors.append(
                    f"readings[{reading_index}].clauses[{clause_index}] must be an object"
                )
                continue
            predicate = clause.get("predicate")
            if not isinstance(predicate, dict):
                errors.append(
                    f"readings[{reading_index}].clauses[{clause_index}].predicate must be an object"
                )
                continue
            surface = predicate.get("surface")
            name = predicate.get("name")
            if not isinstance(surface, str) or not surface:
                errors.append(
                    f"readings[{reading_index}].clauses[{clause_index}].predicate.surface must be non-empty"
                )
            if not isinstance(name, str) or not name:
                errors.append(
                    f"readings[{reading_index}].clauses[{clause_index}].predicate.name must be non-empty"
                )
            elif surface and lemma_verb(str(surface)) != name:
                errors.append(
                    f"readings[{reading_index}].clauses[{clause_index}].predicate.name must match its surface lemma"
                )
            uses_propt = negated_coordination_clause_uses_propt(clause)
            if uses_propt:
                check_coordination_modifiers(
                    errors,
                    clause.get("modifiers", []),
                    f"readings[{reading_index}].clauses[{clause_index}]",
                )
                check_time_modifiers(
                    errors,
                    clause.get("time_modifiers", []),
                    f"readings[{reading_index}].clauses[{clause_index}]",
                )
            obj = clause.get("object")
            if obj is None:
                expected_type = (
                    "forall n : nat, ModifierSeq n -> Entity -> PropT"
                    if uses_propt
                    else "Entity -> Prop"
                )
            elif isinstance(obj, dict):
                object_name = obj.get("name")
                object_type = obj.get("type")
                if not isinstance(object_name, str) or not object_name:
                    errors.append(
                        f"readings[{reading_index}].clauses[{clause_index}].object.name must be non-empty"
                    )
                if not isinstance(object_type, str) or not object_type:
                    errors.append(
                        f"readings[{reading_index}].clauses[{clause_index}].object.type must be non-empty"
                    )
                    expected_type = None
                else:
                    if reading_index == 0:
                        object_declarations.append((str(object_name), object_type))
                    expected_type = (
                        "forall n : nat, ModifierSeq n -> "
                        f"Entity -> {object_type} -> PropT"
                        if uses_propt
                        else f"Entity -> {object_type} -> Prop"
                    )
            else:
                errors.append(
                    f"readings[{reading_index}].clauses[{clause_index}].object must be null or object"
                )
                expected_type = None
            if expected_type is not None and predicate.get("predicate_type") != expected_type:
                errors.append(
                    f"readings[{reading_index}].clauses[{clause_index}].predicate must have type {expected_type}"
                )
        expected_connective_type = (
            "PropT -> PropT -> PropT"
            if any(
                isinstance(clause, dict)
                and negated_coordination_clause_uses_propt(clause)
                for clause in clauses
            )
            else "Prop -> Prop -> Prop"
        )
        if reading.get("connective_type") != expected_connective_type:
            errors.append(
                f"readings[{reading_index}].connective must have type "
                f"{expected_connective_type}"
            )

    check_declaration_type_conflicts(
        errors,
        object_declarations,
        "negated coordination object",
    )

    return {
        "ok": not errors,
        "type": "Prop" if not errors else None,
        "errors": errors,
        "reading_count": len(readings),
    }


def render_negated_coordination_clause(
    clause: dict[str, Any],
    coq: bool = False,
) -> str:
    if negated_coordination_clause_uses_propt(clause):
        if coq:
            return render_branch_clause_coq(clause)
        return render_branch_clause_translation(clause)
    predicate = clause["predicate"]["name"]
    subject = clause["subject"]["name"]
    obj = clause.get("object")
    if coq:
        if obj is None:
            return f"{predicate} {subject}"
        return f"{predicate} {subject} {obj['name']}"
    if obj is None:
        return f"{predicate}({subject})"
    return f"{predicate}({subject}, {obj['name']})"


def render_negated_coordination_reading(
    reading: dict[str, Any],
    coq: bool = False,
) -> str:
    left = render_negated_coordination_clause(reading["clauses"][0], coq=coq)
    right = render_negated_coordination_clause(reading["clauses"][1], coq=coq)
    connective = reading.get("connective", "and_T")
    if coq:
        coordination = f"{connective} ({left}) ({right})"
        if reading["scope"] == "distributed_negation":
            proposition = f"and_T (not_T ({left})) (not_T ({right}))"
        elif reading["scope"] == "disjunction_of_negations":
            proposition = f"or_T (not_T ({left})) (not_T ({right}))"
        else:
            proposition = f"not_T ({coordination})"
        for modifier in reading.get("time_modifiers", []):
            proposition = f"{modifier['operator']}_T {modifier['argument']} ({proposition})"
        return proposition
    coordination = f"{connective}({left}, {right})"
    if reading["scope"] == "distributed_negation":
        proposition = f"and_T(not_T({left}), not_T({right}))"
    elif reading["scope"] == "disjunction_of_negations":
        proposition = f"or_T(not_T({left}), not_T({right}))"
    else:
        proposition = f"not_T({coordination})"
    for modifier in reading.get("time_modifiers", []):
        proposition = f"{modifier['operator']}_T({modifier['argument']}, {proposition})"
    return proposition


def render_negated_coordination_coq(
    readings: list[dict[str, Any]],
) -> str:
    clauses = readings[0]["clauses"]
    subject = readings[0]["subject"]["name"]
    uses_propt = negated_coordination_uses_propt(readings)
    object_types = list(
        dict.fromkeys(
            clause["object"]["type"]
            for clause in clauses
            if isinstance(clause.get("object"), dict)
            and clause["object"]["type"] != "Entity"
        )
    )
    object_declarations = unique_typed_declarations([
        (clause["object"]["name"], clause["object"]["type"])
        for clause in clauses
        if isinstance(clause.get("object"), dict)
    ])
    predicate_declarations = unique_typed_declarations([
        (clause["predicate"]["name"], clause["predicate"]["predicate_type"])
        for clause in clauses
    ])
    lines = [
        "(* Scope ambiguity for do-support negation over coordination. *)",
        "Parameter Entity : Type.",
    ]
    if uses_propt:
        lines.extend(
            [
                "Definition PropT : Type := Prop.",
                "Definition Adv : Type := (Entity -> PropT) -> Entity -> PropT.",
                "Parameter ModifierSeq : nat -> Type.",
                "Parameter mods_nil : ModifierSeq 0.",
                "Parameter mods_cons : forall n : nat, Adv -> ModifierSeq n -> ModifierSeq (S n).",
            ]
        )
    lines.extend(f"Parameter {object_type} : Type." for object_type in object_types)
    if uses_propt:
        all_modifiers = [
            modifier
            for clause in clauses
            for modifier in clause.get("modifiers", [])
        ]
        lines.extend(
            f"Parameter {name} : Adv."
            for name in unique_names([modifier["name"] for modifier in all_modifiers])
        )
    lines.extend(
        [
            "",
            f"Parameter {subject} : Entity.",
        ]
    )
    lines.extend(f"Parameter {name} : {type_name}." for name, type_name in object_declarations)
    lines.extend(
        f"Parameter {name} : {predicate_type}."
        for name, predicate_type in predicate_declarations
    )
    connective_names = unique_names([
        reading.get("connective", "and_T") for reading in readings
    ])
    if uses_propt:
        lines.extend(
            [
                "Parameter not_T : PropT -> PropT.",
            ]
        )
        lines.extend(
            f"Parameter {connective} : PropT -> PropT -> PropT."
            for connective in connective_names
        )
        all_time_modifiers = [
            modifier
            for reading in readings
            for modifier in reading.get("time_modifiers", [])
        ] + [
            modifier
            for clause in clauses
            for modifier in clause.get("time_modifiers", [])
        ]
        if all_time_modifiers:
            lines.extend(
                f"Parameter {name} : Entity."
                for name in unique_names([
                    modifier["argument"] for modifier in all_time_modifiers
                ])
            )
            lines.extend(
                [
                    "Parameter at_T : Entity -> PropT -> PropT.",
                    "Parameter during_T : Entity -> PropT -> PropT.",
                ]
            )
        lines.append("")
    else:
        lines.extend(
            [
                "Parameter not_T : Prop -> Prop.",
            ]
        )
        lines.extend(
            f"Parameter {connective} : Prop -> Prop -> Prop."
            for connective in connective_names
        )
        all_time_modifiers = [
            modifier
            for reading in readings
            for modifier in reading.get("time_modifiers", [])
        ]
        if all_time_modifiers:
            lines.extend(
                f"Parameter {name} : Entity."
                for name in unique_names([
                    modifier["argument"] for modifier in all_time_modifiers
                ])
            )
            lines.extend(
                [
                    "Parameter at_T : Entity -> Prop -> Prop.",
                    "Parameter during_T : Entity -> Prop -> Prop.",
                ]
            )
        lines.append("")
    for reading in readings:
        lines.extend(
            [
                f"Definition {reading['name']} : Prop :=",
                f"  {render_negated_coordination_reading(reading, coq=True)}.",
                "",
            ]
        )
    lines.extend(f"Check {reading['name']}." for reading in readings)
    lines.append("")
    return "\n".join(lines)


def negated_coordination_semantic_readings(
    readings: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    return [
        semantic_reading(
            name=reading["name"],
            dependent_type_translation=render_negated_coordination_reading(reading),
            coq_definition=reading["name"],
            scope=reading["scope"],
            type_check={"ok": True, "type": "Prop", "errors": []},
            source="do_support_negation",
        )
        for reading in readings
    ]


def negated_coordination_clause_from_tail(
    surface: str,
    tail_tokens: list[str],
    subject: str,
    shared_adv_modifiers: list[dict[str, Any]] | None = None,
) -> dict[str, Any] | None:
    shared_adv_modifiers = list(shared_adv_modifiers or [])
    modifier_parse = split_shared_adv_and_time_modifiers(tail_tokens)
    if modifier_parse is not None:
        adv_modifiers, time_modifiers = modifier_parse
        modifiers = [*shared_adv_modifiers, *adv_modifiers]
        if modifiers or time_modifiers:
            return branch_modifier_clause(
                surface,
                subject,
                modifiers,
                False,
                time_modifiers=time_modifiers,
            )
        return {
            "predicate": {
                "surface": surface,
                "name": lemma_verb(surface),
                "predicate_type": "Entity -> Prop",
            },
            "subject": {"name": subject, "type": "Entity"},
            "object": None,
        }

    if not is_likely_transitive_verb(surface):
        return None

    object_parse = split_object_tokens_and_modifiers(tail_tokens)
    if object_parse is None:
        return None
    object_tokens, adv_modifiers, time_modifiers = object_parse
    obj = clean_phrase(object_tokens)
    if obj == "entity":
        return None
    predicate = lemma_verb(surface)
    object_type = object_type_for_transitive_predicate(predicate)
    obj_record = {"name": obj, "type": object_type}
    modifiers = [*shared_adv_modifiers, *adv_modifiers]
    if modifiers or time_modifiers:
        return branch_modifier_clause(
            surface,
            subject,
            modifiers,
            False,
            obj_record,
            time_modifiers=time_modifiers,
        )
    return {
        "predicate": {
            "surface": surface,
            "name": predicate,
            "predicate_type": f"Entity -> {object_type} -> Prop",
        },
        "subject": {"name": subject, "type": "Entity"},
        "object": obj_record,
    }


def ambiguous_do_support_coordination_pipeline(
    sentence: str,
    tokens: list[str],
    negation_index: int,
    auxiliary: str,
    subject: str,
    fronted_adv_modifiers: list[dict[str, Any]] | None = None,
    fronted_time_modifiers: list[dict[str, str]] | None = None,
) -> dict[str, Any] | None:
    fronted_adv_modifiers = list(fronted_adv_modifiers or [])
    fronted_time_modifiers = list(fronted_time_modifiers or [])
    coordination = single_boolean_coordinator(tokens)
    if coordination is None:
        return None
    coordinator, coordinator_index = coordination
    connective = connective_for_coordinator(coordinator)
    if coordinator_index <= negation_index + 1 or coordinator_index + 1 >= len(tokens):
        return None
    left_surface = tokens[negation_index + 1]
    right_surface = tokens[coordinator_index + 1]
    if not is_likely_surface_verb(left_surface) or not is_likely_surface_verb(right_surface):
        return None

    left_clause = negated_coordination_clause_from_tail(
        left_surface,
        tokens[negation_index + 2 : coordinator_index],
        subject,
        fronted_adv_modifiers,
    )
    right_clause = negated_coordination_clause_from_tail(
        right_surface,
        tokens[coordinator_index + 2 :],
        subject,
        fronted_adv_modifiers,
    )
    if left_clause is None or right_clause is None:
        return None
    clauses = [left_clause, right_clause]

    readings = negated_coordination_readings(
        subject,
        clauses,
        fronted_time_modifiers,
        connective=connective,
    )
    type_check = check_negated_coordination_readings(readings)
    semantic_readings = negated_coordination_semantic_readings(readings)
    dependent_type_translation = "\n".join(
        f"{reading['scope']}: {render_negated_coordination_reading(reading)}"
        for reading in readings
    )
    coq_code = render_negated_coordination_coq(readings)
    semantic_readings_check = check_semantic_readings(semantic_readings, coq_code)
    kind = (
        "do_support_negation_disjunction"
        if connective == "or_T"
        else "do_support_negation_coordination_ambiguity"
    )
    analysis = (
        "do-support-negation-disjunction"
        if connective == "or_T"
        else "do-support-negation-coordination-ambiguity"
    )
    summary = (
        f"Do-support negation with {auxiliary} not scopes over an or-coordination; "
        "one checked negation-over-disjunction reading is exported."
        if connective == "or_T"
        else (
            f"Do-support negation with {auxiliary} not scopes ambiguously over "
            "and-coordination; both wide and distributed negation readings are exported."
        )
    )
    note = (
        "Do-support negation over or-coordination is represented as "
        "not_T over a typed disjunction rather than as a pseudo-object."
        if connective == "or_T"
        else (
            "Ambiguous do-support negation over and-coordination is represented "
            "as two typed propositions rather than collapsed into one formula."
        )
    )
    return {
        "kind": kind,
        "input_sentence": sentence,
        "construction_summary": summary,
        "event_semantics": {
            "analysis": analysis,
            "source": sentence,
            "event_style_reference": (
                "not over typed coordination, without introducing Event"
            ),
            "readings": [
                {**reading, "formula": render_negated_coordination_reading(reading)}
                for reading in readings
            ],
            "semantic_readings": semantic_readings,
            "semantic_readings_check": semantic_readings_check,
        },
        "dependent_type_translation": dependent_type_translation,
        "semantic_readings": semantic_readings,
        "semantic_readings_check": semantic_readings_check,
        "ast": {
            "kind": "do_support_negation_coordination_ambiguity",
            "auxiliary": auxiliary,
            "subject": {"name": subject, "type": "Entity"},
            "readings": readings,
        },
        "type_check": {
            **type_check,
            "note": note,
        },
        "coq_code": coq_code,
    }


def split_fronted_do_support_modifiers(
    tokens: list[str],
) -> tuple[list[str], list[dict[str, Any]], list[dict[str, str]]]:
    remaining = list(tokens)
    all_adv_modifiers: list[dict[str, Any]] = []
    all_time_modifiers: list[dict[str, str]] = []
    while remaining:
        original = list(remaining)
        remaining, time_modifiers = split_fronted_time_modifiers(remaining)
        all_time_modifiers.extend(time_modifiers)
        remaining, adv_modifiers = split_fronted_adv_modifiers(remaining)
        all_adv_modifiers.extend(adv_modifiers)
        if remaining == original:
            break
    return remaining, all_adv_modifiers, all_time_modifiers


def repeated_do_support_negation_coordination_pipeline(
    sentence: str,
    tokens: list[str],
    negation_index: int,
    auxiliary: str,
    subject: str,
    fronted_adv_modifiers: list[dict[str, Any]] | None = None,
    fronted_time_modifiers: list[dict[str, str]] | None = None,
) -> dict[str, Any] | None:
    fronted_adv_modifiers = list(fronted_adv_modifiers or [])
    fronted_time_modifiers = list(fronted_time_modifiers or [])
    coordination = single_boolean_coordinator(tokens)
    if coordination is None:
        return None
    coordinator, coordinator_index = coordination
    connective = connective_for_coordinator(coordinator)
    if coordinator_index <= negation_index + 1 or coordinator_index + 3 >= len(tokens):
        return None
    if tokens[coordinator_index + 1] not in DO_SUPPORT_AUXILIARIES:
        return None
    if tokens[coordinator_index + 2] != "not":
        return None
    left_surface = tokens[negation_index + 1]
    right_surface = tokens[coordinator_index + 3]
    if not is_likely_surface_verb(left_surface) or not is_likely_surface_verb(right_surface):
        return None

    left_clause = negated_coordination_clause_from_tail(
        left_surface,
        tokens[negation_index + 2 : coordinator_index],
        subject,
        fronted_adv_modifiers,
    )
    right_clause = negated_coordination_clause_from_tail(
        right_surface,
        tokens[coordinator_index + 4 :],
        subject,
        fronted_adv_modifiers,
    )
    if left_clause is None or right_clause is None:
        return None
    clauses = [left_clause, right_clause]
    if connective == "or_T":
        checked_readings = [
            disjunction_of_negations_reading(
                subject,
                clauses,
                fronted_time_modifiers,
            )
        ]
        exported_reading = checked_readings[0]
        surface_scope = "disjunction_of_negations"
    else:
        checked_readings = negated_coordination_readings(
            subject,
            clauses,
            fronted_time_modifiers,
        )
        exported_reading = checked_readings[1]
        surface_scope = "distributed_negation"
    type_check = check_negated_coordination_readings(checked_readings)
    type_check = {
        **type_check,
        "reading_count": 1,
        "surface_scope": surface_scope,
    }
    typed_replacement = render_negated_coordination_reading(exported_reading)
    coq_code = render_negated_coordination_coq([exported_reading])
    return attach_single_semantic_reading(
        {
            "kind": "repeated_do_support_negation_coordination",
            "input_sentence": sentence,
            "construction_summary": (
                f"Same subject {subject} coordinates two explicit do-support "
                f"negations with {coordinator}, so each typed branch is wrapped in not_T."
            ),
            "event_semantics": {
                "analysis": "repeated-do-support-negation-coordination",
                "source": sentence,
                "event_style_reference": (
                    f"not(P) {coordinator} not(Q), without introducing Event, Agent, or Theme"
                ),
                "formula": typed_replacement,
            },
            "dependent_type_translation": typed_replacement,
            "ast": {
                "kind": "repeated_do_support_negation_coordination",
                "auxiliary": auxiliary,
                "subject": {"name": subject, "type": "Entity"},
                "reading": exported_reading,
            },
            "type_check": {
                **type_check,
                "note": (
                    "Repeated do-support negation over coordination has an explicit "
                    "distributed negation surface form, so the translator exports "
                    "one checked proposition rather than an ambiguity set."
                ),
            },
            "coq_code": coq_code,
        },
        name=exported_reading["name"],
        coq_definition=exported_reading["name"],
        source="do_support_negation",
        scope=surface_scope,
    )


def do_support_negation_pipeline(sentence: str) -> dict[str, Any] | None:
    tokens = tokenize(sentence)
    negation_index = None
    for index, token in enumerate(tokens):
        if (
            token == "not"
            and index > 0
            and tokens[index - 1] in DO_SUPPORT_AUXILIARIES
        ):
            negation_index = index
            break
    if negation_index is None:
        return None

    auxiliary_index = negation_index - 1
    auxiliary = tokens[auxiliary_index]
    subject_tokens = tokens[:auxiliary_index]
    if not subject_tokens or negation_index + 1 >= len(tokens):
        return None

    subject = clean_phrase(subject_tokens)
    if subject == "entity":
        return None

    (
        tokens_without_fronted,
        fronted_adv_modifiers,
        fronted_time_modifiers,
    ) = split_fronted_do_support_modifiers(
        tokens,
    )

    if any(token in BOOLEAN_COORDINATORS for token in tokens):
        stripped_negation_index = None
        for index, token in enumerate(tokens_without_fronted):
            if (
                token == "not"
                and index > 0
                and tokens_without_fronted[index - 1] in DO_SUPPORT_AUXILIARIES
            ):
                stripped_negation_index = index
                break
        if stripped_negation_index is not None:
            stripped_auxiliary_index = stripped_negation_index - 1
            stripped_subject_tokens = tokens_without_fronted[:stripped_auxiliary_index]
            stripped_subject = clean_phrase(stripped_subject_tokens)
            if stripped_subject != "entity":
                repeated_coordination = (
                    repeated_do_support_negation_coordination_pipeline(
                        sentence,
                        tokens_without_fronted,
                        stripped_negation_index,
                        tokens_without_fronted[stripped_auxiliary_index],
                        stripped_subject,
                        fronted_adv_modifiers,
                        fronted_time_modifiers,
                    )
                )
                if repeated_coordination is not None:
                    return repeated_coordination
        coordinated = coordinated_do_support_negation_pipeline(sentence)
        if coordinated is not None:
            return coordinated
        ambiguous_coordination = None
        if stripped_negation_index is not None:
            stripped_auxiliary_index = stripped_negation_index - 1
            stripped_subject_tokens = tokens_without_fronted[:stripped_auxiliary_index]
            stripped_subject = clean_phrase(stripped_subject_tokens)
            if stripped_subject != "entity":
                ambiguous_coordination = ambiguous_do_support_coordination_pipeline(
                    sentence,
                    tokens_without_fronted,
                    stripped_negation_index,
                    tokens_without_fronted[stripped_auxiliary_index],
                    stripped_subject,
                    fronted_adv_modifiers,
                    fronted_time_modifiers,
                )
        if ambiguous_coordination is not None:
            return ambiguous_coordination
        return {
            "kind": "do_support_negation",
            "input_sentence": sentence,
            "construction_summary": (
                f"Do-support negation with {auxiliary} not was detected, "
                "but coordination under negation is not implemented in this "
                "controlled rule yet."
            ),
            "event_semantics": {
                "analysis": "do-support-negation",
                "source": sentence,
                "event_style_reference": (
                    "not(exists e. P(e) ...), with coordination left unresolved"
                ),
            },
            "dependent_type_translation": "",
            "ast": {
                "kind": "do_support_negation",
                "auxiliary": auxiliary,
                "subject": {"name": subject, "type": "Entity"},
                "unsupported": "coordination_under_negation",
            },
            "type_check": {
                "ok": False,
                "type": None,
                "errors": [
                    "do-support negation with coordination is not yet supported"
                ],
                "note": (
                    "The sentence contains do-support negation and coordination; "
                    "the parser refuses to turn it into a malformed subject or object."
                ),
            },
            "coq_code": "",
        }

    if any(token in CONTRASTIVE_COORDINATORS for token in tokens):
        contrastive = contrastive_do_support_negation_pipeline(sentence)
        if contrastive is not None:
            return contrastive
        return {
            "kind": "do_support_negation",
            "input_sentence": sentence,
            "construction_summary": (
                f"Do-support negation with {auxiliary} not and contrastive "
                "coordination was detected, but this surface pattern is not "
                "implemented in the controlled rule yet."
            ),
            "event_semantics": {
                "analysis": "do-support-negation",
                "source": sentence,
                "event_style_reference": (
                    "not(exists e. P(e) ...) with contrastive coordination unresolved"
                ),
            },
            "dependent_type_translation": "",
            "ast": {
                "kind": "do_support_negation",
                "auxiliary": auxiliary,
                "subject": {"name": subject, "type": "Entity"},
                "unsupported": "contrastive_coordination_under_negation",
            },
            "type_check": {
                "ok": False,
                "type": None,
                "errors": [
                    "do-support negation with contrastive coordination is not yet supported"
                ],
                "note": (
                    "The parser refuses to turn contrastive coordination into "
                    "a malformed object inside the negated positive clause."
                ),
            },
            "coq_code": "",
        }

    positive_sentence = " ".join(
        [*subject_tokens, lemma_verb(tokens[negation_index + 1]), *tokens[negation_index + 2 :]]
    )
    positive_translation = translate(sentence_to_event_semantics(positive_sentence))
    ast = not_term(positive_translation["ast"])
    type_check = check_term(ast)
    exports = (
        {target: export_term(ast, target) for target in ("lean", "coq")}
        if type_check["ok"]
        else {}
    )
    coq_code = export_module(
        [{"ast": ast, "type_check": type_check, "exports": exports}],
        "coq",
    ) if type_check["ok"] else ""
    typed_replacement = render_term(ast)
    return attach_single_semantic_reading(
        {
            "kind": "do_support_negation",
            "input_sentence": sentence,
            "construction_summary": (
                f"Do-support negation maps {auxiliary} not to not_T over the "
                f"positive clause {positive_sentence}."
            ),
            "event_semantics": {
                "analysis": "do-support-negation",
                "source": sentence,
                "positive_clause": positive_translation["translation"],
                "event_style_reference": (
                    f"not(exists e. {positive_translation['translation']})"
                ),
                "typed_replacement": typed_replacement,
            },
            "dependent_type_translation": typed_replacement,
            "ast": ast,
            "type_check": {
                **type_check,
                "note": (
                    "Do-support negation is represented as a proposition-level "
                    "not_T wrapper around the checked positive-clause AST."
                ),
            },
            "coq_code": coq_code,
        },
        name="do_support_negation",
        coq_definition="example_1",
        source="do_support_negation",
        scope="simple_negation",
    )


def wrap_negated_translation(term: str, negated: bool) -> str:
    return f"not_T({term})" if negated else term


def wrap_negated_coq(term: str, negated: bool) -> str:
    return f"not_T ({term})" if negated else term


def coordinated_do_support_negation_pipeline(sentence: str) -> dict[str, Any] | None:
    tokens, fronted_time_modifiers = split_fronted_time_modifiers(tokenize(sentence))
    tokens, fronted_adv_modifiers = split_fronted_adv_modifiers(tokens)
    tokens = strip_surface_coordination_marker(tokens)
    coordination = single_boolean_coordinator(tokens)
    if coordination is None:
        return None
    coordinator, coordinator_index = coordination
    connective = connective_for_coordinator(coordinator)
    if "not" in tokens[:coordinator_index]:
        return None
    if coordinator_index + 3 >= len(tokens):
        return None
    auxiliary = tokens[coordinator_index + 1]
    if auxiliary not in DO_SUPPORT_AUXILIARIES or tokens[coordinator_index + 2] != "not":
        return None
    right_surface = tokens[coordinator_index + 3]
    if not is_likely_surface_verb(right_surface):
        return None

    transitive = coordinated_transitive_do_support_negation(
        sentence,
        tokens,
        coordinator_index,
        right_surface,
        fronted_adv_modifiers,
        fronted_time_modifiers,
        coordinator,
        connective,
    )
    if transitive is not None:
        return transitive
    return coordinated_intransitive_do_support_negation(
        sentence,
        tokens,
        coordinator_index,
        right_surface,
        fronted_adv_modifiers,
        fronted_time_modifiers,
        coordinator,
        connective,
    )


def contrastive_do_support_negation_pipeline(sentence: str) -> dict[str, Any] | None:
    tokens, fronted_time_modifiers = split_fronted_time_modifiers(tokenize(sentence))
    tokens, fronted_adv_modifiers = split_fronted_adv_modifiers(tokens)
    if sum(1 for token in tokens if token in CONTRASTIVE_COORDINATORS) != 1:
        return None
    but_index = next(
        index for index, token in enumerate(tokens) if token in CONTRASTIVE_COORDINATORS
    )
    negation_index = None
    for index, token in enumerate(tokens[:but_index]):
        if (
            token == "not"
            and index > 0
            and tokens[index - 1] in DO_SUPPORT_AUXILIARIES
        ):
            negation_index = index
            break
    if negation_index is None or negation_index + 1 >= but_index:
        return None
    if but_index + 1 >= len(tokens):
        return None
    left_surface = tokens[negation_index + 1]
    right_surface = tokens[but_index + 1]
    if not is_likely_surface_verb(left_surface) or not is_likely_surface_verb(right_surface):
        return None

    transitive = contrastive_transitive_do_support_negation(
        sentence,
        tokens,
        negation_index,
        but_index,
        left_surface,
        right_surface,
        fronted_adv_modifiers,
        fronted_time_modifiers,
    )
    if transitive is not None:
        return transitive
    return contrastive_intransitive_do_support_negation(
        sentence,
        tokens,
        negation_index,
        but_index,
        left_surface,
        right_surface,
        fronted_adv_modifiers,
        fronted_time_modifiers,
    )


def contrastive_do_support_failure(
    sentence: str,
    subject: str,
    auxiliary: str,
    unsupported: str,
    error: str,
    note: str,
) -> dict[str, Any]:
    return {
        "kind": "contrastive_do_support_negation",
        "input_sentence": sentence,
        "construction_summary": (
            f"Contrastive do-support negation with {auxiliary} not was detected, "
            "but this surface pattern is outside the controlled fragment."
        ),
        "event_semantics": {
            "analysis": "contrastive-do-support-negation",
            "source": sentence,
            "event_style_reference": (
                "not(exists e1. P(e1) ...) and exists e2. Q(e2) ..."
            ),
        },
        "dependent_type_translation": "",
        "ast": {
            "kind": "contrastive_do_support_negation",
            "auxiliary": auxiliary,
            "subject": {"name": subject, "type": "Entity"},
            "unsupported": unsupported,
        },
        "type_check": {
            "ok": False,
            "type": None,
            "errors": [error],
            "note": note,
        },
        "coq_code": "",
    }


def branch_modifier_clause(
    surface: str,
    subject: str,
    modifiers: list[dict[str, Any]],
    negated: bool,
    obj: dict[str, str] | None = None,
    time_modifiers: list[dict[str, str]] | None = None,
) -> dict[str, Any]:
    predicate = lemma_verb(surface)
    if obj is None:
        predicate_type = "forall n : nat, ModifierSeq n -> Entity -> PropT"
    else:
        predicate_type = (
            "forall n : nat, ModifierSeq n -> "
            f"Entity -> {obj['type']} -> PropT"
        )
    return {
        "predicate": {
            "surface": surface,
            "name": predicate,
            "predicate_type": predicate_type,
        },
        "subject": {"name": subject, "type": "Entity"},
        "object": obj,
        "modifiers": modifiers,
        "time_modifiers": list(time_modifiers or []),
        "negated": negated,
    }


def contrastive_branch_modifier_ast(
    subject: str,
    clauses: list[dict[str, Any]],
    time_modifiers: list[dict[str, str]],
) -> dict[str, Any]:
    return {
        "kind": "contrastive_branch_modifier_coordination",
        "subject": {"name": subject, "type": "Entity"},
        "clauses": clauses,
        "connective": "and_T",
        "connective_type": "PropT -> PropT -> PropT",
        "time_modifiers": time_modifiers,
    }


def check_contrastive_branch_modifier_ast(ast: dict[str, Any]) -> dict[str, Any]:
    errors: list[str] = []
    if ast.get("kind") != "contrastive_branch_modifier_coordination":
        errors.append("ast.kind must be contrastive_branch_modifier_coordination")

    subject = ast.get("subject")
    if not isinstance(subject, dict):
        errors.append("contrastive branch modifier subject must be an object")
    else:
        if not isinstance(subject.get("name"), str) or not subject.get("name"):
            errors.append("contrastive branch modifier subject.name must be non-empty")
        if subject.get("type") != "Entity":
            errors.append("contrastive branch modifier subject must have type Entity")

    clauses = ast.get("clauses")
    object_declarations: list[tuple[str, str]] = []
    if not isinstance(clauses, list) or len(clauses) != 2:
        errors.append("contrastive branch modifier clauses must contain exactly two items")
    else:
        for index, clause in enumerate(clauses):
            if not isinstance(clause, dict):
                errors.append(f"contrastive branch modifier clauses[{index}] must be an object")
                continue
            if "negated" in clause and not isinstance(clause["negated"], bool):
                errors.append(
                    f"contrastive branch modifier clauses[{index}].negated must be boolean"
                )
            modifiers = clause.get("modifiers")
            check_coordination_modifiers(
                errors,
                modifiers,
                f"contrastive branch modifier clauses[{index}]",
            )
            time_modifiers = clause.get("time_modifiers", [])
            if not isinstance(time_modifiers, list):
                errors.append(
                    f"contrastive branch modifier clauses[{index}].time_modifiers must be a list"
                )
            else:
                check_time_modifiers(
                    errors,
                    time_modifiers,
                    f"contrastive branch modifier clauses[{index}]",
                )
            predicate = clause.get("predicate")
            if not isinstance(predicate, dict):
                errors.append(
                    f"contrastive branch modifier clauses[{index}].predicate must be an object"
                )
                continue
            surface = predicate.get("surface")
            name = predicate.get("name")
            if not isinstance(surface, str) or not surface:
                errors.append(
                    "contrastive branch modifier "
                    f"clauses[{index}].predicate.surface must be non-empty"
                )
            if not isinstance(name, str) or not name:
                errors.append(
                    "contrastive branch modifier "
                    f"clauses[{index}].predicate.name must be non-empty"
                )
            elif surface and lemma_verb(str(surface)) != name:
                errors.append(
                    "contrastive branch modifier "
                    f"clauses[{index}].predicate.name must match its surface lemma"
                )

            obj = clause.get("object")
            if obj is None:
                expected_predicate_type = (
                    "forall n : nat, ModifierSeq n -> Entity -> PropT"
                )
            elif isinstance(obj, dict):
                object_name = obj.get("name")
                object_type = obj.get("type")
                if not isinstance(object_name, str) or not object_name:
                    errors.append(
                        "contrastive branch modifier "
                        f"clauses[{index}].object.name must be non-empty"
                    )
                if not isinstance(object_type, str) or not object_type:
                    errors.append(
                        "contrastive branch modifier "
                        f"clauses[{index}].object.type must be non-empty"
                    )
                    expected_predicate_type = None
                else:
                    expected_predicate_type = (
                        "forall n : nat, ModifierSeq n -> "
                        f"Entity -> {object_type} -> PropT"
                    )
                    object_declarations.append((str(object_name), object_type))
            else:
                errors.append(
                    f"contrastive branch modifier clauses[{index}].object must be null or object"
                )
                expected_predicate_type = None
            if (
                expected_predicate_type is not None
                and predicate.get("predicate_type") != expected_predicate_type
            ):
                errors.append(
                    "contrastive branch modifier "
                    f"clauses[{index}].predicate must have type {expected_predicate_type}"
                )

    check_declaration_type_conflicts(
        errors,
        object_declarations,
        "contrastive branch modifier object",
    )

    if ast.get("connective") != "and_T":
        errors.append("contrastive branch modifier connective must be and_T")
    if ast.get("connective_type") != "PropT -> PropT -> PropT":
        errors.append(
            "contrastive branch modifier connective must have type PropT -> PropT -> PropT"
        )

    time_modifiers = ast.get("time_modifiers")
    if not isinstance(time_modifiers, list):
        errors.append("contrastive branch modifier time_modifiers must be a list")
    else:
        for index, modifier in enumerate(time_modifiers):
            if not isinstance(modifier, dict):
                errors.append(
                    f"contrastive branch modifier time_modifiers[{index}] must be an object"
                )
                continue
            if modifier.get("operator") not in {"at", "during"}:
                errors.append(
                    "contrastive branch modifier "
                    f"time_modifiers[{index}].operator must be at or during"
                )
            if not isinstance(modifier.get("argument"), str) or not modifier.get("argument"):
                errors.append(
                    "contrastive branch modifier "
                    f"time_modifiers[{index}].argument must be non-empty"
                )

    return {
        "ok": not errors,
        "type": "Prop" if not errors else None,
        "errors": errors,
    }


def render_branch_clause_translation(clause: dict[str, Any]) -> str:
    predicate = clause["predicate"]["name"]
    subject = clause["subject"]["name"]
    modifiers = clause.get("modifiers", [])
    modifier_args = readable_modifier_arguments(modifiers)
    modifier_count = len(modifiers)
    obj = clause.get("object")
    if obj is None:
        if modifiers:
            term = f"{predicate}({modifier_count})({modifier_args}, {subject})"
        else:
            term = f"{predicate}(0)({subject})"
    elif modifiers:
        term = (
            f"{predicate}({modifier_count})"
            f"({modifier_args}, {subject}, {obj['name']})"
        )
    else:
        term = f"{predicate}(0)({subject}, {obj['name']})"
    for modifier in clause.get("time_modifiers", []):
        term = f"{modifier['operator']}_T({modifier['argument']}, {term})"
    return wrap_negated_translation(term, bool(clause.get("negated")))


def render_branch_clause_coq(clause: dict[str, Any]) -> str:
    predicate = clause["predicate"]["name"]
    subject = clause["subject"]["name"]
    modifiers = clause.get("modifiers", [])
    modifier_count = len(modifiers)
    modifier_sequence = coq_modifier_sequence(modifiers)
    obj = clause.get("object")
    if obj is None:
        term = f"{predicate} {modifier_count} {modifier_sequence} {subject}"
    else:
        term = (
            f"{predicate} {modifier_count} {modifier_sequence} "
            f"{subject} {obj['name']}"
        )
    for modifier in clause.get("time_modifiers", []):
        term = f"{modifier['operator']}_T {modifier['argument']} ({term})"
    return wrap_negated_coq(term, bool(clause.get("negated")))


def render_contrastive_branch_modifier_translation(ast: dict[str, Any]) -> str:
    left = render_branch_clause_translation(ast["clauses"][0])
    right = render_branch_clause_translation(ast["clauses"][1])
    proposition = f"and_T({left}, {right})"
    for modifier in ast["time_modifiers"]:
        proposition = f"{modifier['operator']}_T({modifier['argument']}, {proposition})"
    return proposition


def render_contrastive_branch_modifier_coq(
    definition_name: str,
    ast: dict[str, Any],
) -> str:
    clauses = ast["clauses"]
    subject = ast["subject"]["name"]
    left = render_branch_clause_coq(clauses[0])
    right = render_branch_clause_coq(clauses[1])
    proposition = f"and_T ({left}) ({right})"
    for modifier in ast["time_modifiers"]:
        proposition = f"{modifier['operator']}_T {modifier['argument']} ({proposition})"

    all_modifiers = [
        modifier
        for clause in clauses
        for modifier in clause.get("modifiers", [])
    ]
    object_types = list(
        dict.fromkeys(
            clause["object"]["type"]
            for clause in clauses
            if isinstance(clause.get("object"), dict)
            and clause["object"]["type"] != "Entity"
        )
    )
    lines = [
        "(* Contrastive do-support negation with branch-local modifiers. *)",
        "Parameter Entity : Type.",
        "Definition PropT : Type := Prop.",
        "Definition Adv : Type := (Entity -> PropT) -> Entity -> PropT.",
        "Parameter ModifierSeq : nat -> Type.",
        "Parameter mods_nil : ModifierSeq 0.",
        "Parameter mods_cons : forall n : nat, Adv -> ModifierSeq n -> ModifierSeq (S n).",
    ]
    lines.extend(f"Parameter {object_type} : Type." for object_type in object_types)
    lines.extend(
        f"Parameter {name} : Adv."
        for name in unique_names([modifier["name"] for modifier in all_modifiers])
    )
    lines.extend(["", f"Parameter {subject} : Entity."])
    for name, type_name in unique_typed_declarations([
        (clause["object"]["name"], clause["object"]["type"])
        for clause in clauses
        if isinstance(clause.get("object"), dict)
    ]):
        lines.append(f"Parameter {name} : {type_name}.")
    for name, predicate_type in unique_typed_declarations([
        (clause["predicate"]["name"], clause["predicate"]["predicate_type"])
        for clause in clauses
    ]):
        lines.append(f"Parameter {name} : {predicate_type}.")
    lines.extend(
        [
            "Parameter not_T : PropT -> PropT.",
            "Parameter and_T : PropT -> PropT -> PropT.",
        ]
    )
    all_time_modifiers = [
        *ast["time_modifiers"],
        *[
            modifier
            for clause in clauses
            for modifier in clause.get("time_modifiers", [])
        ],
    ]
    if all_time_modifiers:
        lines.extend(
            f"Parameter {name} : Entity."
            for name in unique_names([
                modifier["argument"] for modifier in all_time_modifiers
            ])
        )
        lines.extend(
            [
                "",
                "Parameter at_T : Entity -> PropT -> PropT.",
                "Parameter during_T : Entity -> PropT -> PropT.",
            ]
        )
    lines.extend(
        [
            "",
            f"Definition {definition_name} : Prop :=",
            f"  {proposition}.",
            "",
            f"Check {definition_name}.",
            "",
        ]
    )
    return "\n".join(lines)


def timed_after_ast(
    first_predicate: str,
    first_theme: str,
    second_predicate: str,
    second_agent: str,
    second_theme: str,
) -> dict[str, Any]:
    return {
        "kind": "timed_after",
        "binders": [
            {"variable": "t_sing", "type": "Time"},
            {"variable": "t_salute", "type": "Time"},
        ],
        "first": {
            "predicate": first_predicate,
            "predicate_type": "Entity -> Time -> Prop",
            "theme": {
                "name": first_theme,
                "type": "Entity",
            },
            "time": "t_sing",
        },
        "second": {
            "predicate": second_predicate,
            "predicate_type": "Entity -> Entity -> Time -> Prop",
            "agent": {
                "name": second_agent,
                "type": "Entity",
            },
            "theme": {
                "name": second_theme,
                "type": "Entity",
            },
            "time": "t_salute",
        },
        "relation": {
            "predicate": "before",
            "predicate_type": "Time -> Time -> Prop",
            "arguments": ["t_sing", "t_salute"],
        },
    }


def check_timed_after_ast(ast: dict[str, Any]) -> dict[str, Any]:
    errors: list[str] = []
    if ast.get("kind") != "timed_after":
        errors.append("ast.kind must be timed_after")

    binders = ast.get("binders")
    expected_binders = [
        {"variable": "t_sing", "type": "Time"},
        {"variable": "t_salute", "type": "Time"},
    ]
    if binders != expected_binders:
        errors.append("timed_after.binders must bind t_sing and t_salute as Time")

    first = ast.get("first")
    if not isinstance(first, dict):
        errors.append("timed_after.first must be an object")
    else:
        if first.get("predicate_type") != "Entity -> Time -> Prop":
            errors.append("timed_after.first must have type Entity -> Time -> Prop")
        theme = first.get("theme")
        if not isinstance(theme, dict) or theme.get("type") != "Entity":
            errors.append("timed_after.first.theme must have type Entity")
        if first.get("time") != "t_sing":
            errors.append("timed_after.first must use bound time t_sing")

    second = ast.get("second")
    if not isinstance(second, dict):
        errors.append("timed_after.second must be an object")
    else:
        if second.get("predicate_type") != "Entity -> Entity -> Time -> Prop":
            errors.append(
                "timed_after.second must have type Entity -> Entity -> Time -> Prop"
            )
        for role in ("agent", "theme"):
            value = second.get(role)
            if not isinstance(value, dict) or value.get("type") != "Entity":
                errors.append(f"timed_after.second.{role} must have type Entity")
        if second.get("time") != "t_salute":
            errors.append("timed_after.second must use bound time t_salute")

    relation = ast.get("relation")
    if not isinstance(relation, dict):
        errors.append("timed_after.relation must be an object")
    else:
        if relation.get("predicate_type") != "Time -> Time -> Prop":
            errors.append("timed_after.relation must have type Time -> Time -> Prop")
        if relation.get("arguments") != ["t_sing", "t_salute"]:
            errors.append("timed_after.relation must relate t_sing before t_salute")

    return {
        "ok": not errors,
        "type": "Prop" if not errors else None,
        "errors": errors,
    }


def timed_after_pipeline(sentence: str) -> dict[str, Any] | None:
    tokens = tokenize(sentence)
    expected = [
        "after",
        "the",
        "singing",
        "of",
        "the",
        "marseillaise",
        "john",
        "saluted",
        "the",
        "flag",
    ]
    if tokens != expected:
        return None

    first_predicate = lemma_verb(tokens[2])
    first_theme = "Marseillaise"
    second_agent = "John"
    second_predicate = lemma_verb(tokens[7])
    second_theme = "flag"
    coq_code = "\n".join(
        [
            "(* Timed Luo-Shi-style replacement for Parsons-style event talk. *)",
            "Parameter Entity : Type.",
            "Parameter Time : Type.",
            "",
            f"Parameter {first_theme} : Entity.",
            f"Parameter {second_agent} : Entity.",
            f"Parameter {second_theme} : Entity.",
            "",
            f"Parameter {first_predicate} : Entity -> Time -> Prop.",
            f"Parameter {second_predicate} : Entity -> Entity -> Time -> Prop.",
            "Parameter before : Time -> Time -> Prop.",
            "",
            "Definition after_singing_salute : Prop :=",
            "  exists t_sing : Time,",
            "  exists t_salute : Time,",
            f"    {first_predicate} {first_theme} t_sing /\\",
            f"    {second_predicate} {second_agent} {second_theme} t_salute /\\",
            "    before t_sing t_salute.",
            "",
            "Check after_singing_salute.",
            "",
        ]
    )
    event_semantics = {
        "analysis": "parsons-after-event-talk",
        "source": sentence,
        "event_style_reference": (
            "exists e e'. singing(e') and Theme(e', Marseillaise) and "
            "saluting(e) and Agent(e, John) and Theme(e, flag) and after(e', e)"
        ),
        "typed_replacement": (
            "exists t_sing t_salute : Time. "
            "sing(Marseillaise, t_sing) and salute(John, flag, t_salute) "
            "and before(t_sing, t_salute)"
        ),
    }
    ast = timed_after_ast(
        first_predicate,
        first_theme,
        second_predicate,
        second_agent,
        second_theme,
    )
    type_check = check_timed_after_ast(ast)
    return attach_single_semantic_reading(
        {
            "kind": "timed_after",
            "input_sentence": sentence,
            "event_semantics": event_semantics,
            "dependent_type_translation": event_semantics["typed_replacement"],
            "ast": ast,
            "type_check": {
                **type_check,
                "note": "The Parsons-style event relation is represented with Time variables, not an Event parameter.",
            },
            "coq_code": coq_code,
        },
        name="timed_after_singing_salute",
        coq_definition="after_singing_salute",
        source="timed_after",
        scope="time_before_salute",
    )


def simple_conditional_clause_ast(
    predicate: str,
    subject: str | None = None,
    *,
    surface_predicate: str,
    subjects: list[str] | None = None,
    connective: str | None = None,
    obj: str | None = None,
    object_type: str | None = None,
    modifiers: list[dict[str, Any]] | None = None,
    time_modifiers: list[dict[str, str]] | None = None,
    negated: bool = False,
    auxiliary: str | None = None,
) -> dict[str, Any]:
    modifiers = list(modifiers or [])
    time_modifiers = list(time_modifiers or [])
    if obj is not None and object_type is not None:
        predicate_type = (
            f"forall n : nat, ModifierSeq n -> Entity -> {object_type} -> PropT"
            if modifiers
            else f"Entity -> {object_type} -> Prop"
        )
    else:
        predicate_type = (
            "forall n : nat, ModifierSeq n -> Entity -> PropT"
            if modifiers
            else "Entity -> Prop"
        )
    clause = {
        "predicate": predicate,
        "predicate_type": predicate_type,
        "surface_predicate": surface_predicate,
    }
    if subjects is not None:
        clause["subjects"] = [
            {
                "name": subject_name,
                "type": "Entity",
            }
            for subject_name in subjects
        ]
        clause["subject_connective"] = {
            "name": connective or "and_T",
            "type": "PropT -> PropT -> PropT" if modifiers else "Prop -> Prop -> Prop",
        }
    else:
        if subject is None:
            raise ValueError("simple conditional clause requires a subject")
        clause["subject"] = {
            "name": subject,
            "type": "Entity",
        }
    if negated:
        clause["negated"] = True
        clause["negation"] = {
            "auxiliary": auxiliary,
            "operator": "not_T",
            "type": "Prop -> Prop",
        }
    if obj is not None and object_type is not None:
        clause["object"] = {
            "name": obj,
            "type": object_type,
        }
    if modifiers:
        clause["modifiers"] = modifiers
    if time_modifiers:
        clause["time_modifiers"] = time_modifiers
    return clause


def simple_conditional_ast(
    antecedent: dict[str, Any],
    consequent: dict[str, Any],
) -> dict[str, Any]:
    return {
        "kind": "conditional_implication",
        "antecedent": antecedent,
        "consequent": consequent,
        "connective": {
            "name": "implies",
            "type": "Prop -> Prop -> Prop",
        },
    }


def simple_conditional_clause_object_type(clause: dict[str, Any]) -> str | None:
    obj = clause.get("object")
    if isinstance(obj, dict) and isinstance(obj.get("type"), str):
        return obj["type"]
    return None


def simple_conditional_modifier_indexed_predicate_type(clause: dict[str, Any]) -> str:
    object_type = simple_conditional_clause_object_type(clause)
    if object_type is None:
        return "forall n : nat, ModifierSeq n -> Entity -> PropT"
    return f"forall n : nat, ModifierSeq n -> Entity -> {object_type} -> PropT"


def simple_conditional_plain_predicate_type(clause: dict[str, Any]) -> str:
    object_type = simple_conditional_clause_object_type(clause)
    if object_type is None:
        return "Entity -> Prop"
    return f"Entity -> {object_type} -> Prop"


def simple_conditional_clause_uses_modifier_signature(clause: dict[str, Any]) -> bool:
    return clause.get("predicate_type") == simple_conditional_modifier_indexed_predicate_type(clause)


def normalize_simple_conditional_predicate_signatures(ast: dict[str, Any]) -> dict[str, Any]:
    clauses = [
        clause
        for clause in (ast.get("antecedent"), ast.get("consequent"))
        if isinstance(clause, dict)
    ]
    predicate_groups: dict[tuple[str, str | None], list[dict[str, Any]]] = {}
    for clause in clauses:
        predicate = clause.get("predicate")
        if not isinstance(predicate, str) or not predicate:
            continue
        key = (predicate, simple_conditional_clause_object_type(clause))
        predicate_groups.setdefault(key, []).append(clause)

    for group in predicate_groups.values():
        if not any(
            clause.get("modifiers")
            or clause.get("predicate_type") == simple_conditional_modifier_indexed_predicate_type(clause)
            for clause in group
        ):
            continue
        for clause in group:
            clause["predicate_type"] = simple_conditional_modifier_indexed_predicate_type(clause)
            clause.setdefault("modifiers", [])
            subject_connective = clause.get("subject_connective")
            if isinstance(subject_connective, dict):
                subject_connective["type"] = "PropT -> PropT -> PropT"
    return ast


def check_simple_conditional_ast(ast: dict[str, Any]) -> dict[str, Any]:
    errors: list[str] = []
    if ast.get("kind") != "conditional_implication":
        errors.append("conditional.kind must be conditional_implication")

    declarations: dict[str, str] = {}
    predicate_types: dict[str, str] = {}

    for field in ("antecedent", "consequent"):
        clause = ast.get(field)
        if not isinstance(clause, dict):
            errors.append(f"conditional.{field} must be a clause object")
            continue
        predicate = clause.get("predicate")
        predicate_type = clause.get("predicate_type")
        if not isinstance(predicate, str) or not predicate:
            errors.append(f"conditional.{field}.predicate must be a non-empty string")
        elif isinstance(predicate_type, str) and predicate_type:
            previous_predicate_type = predicate_types.setdefault(predicate, predicate_type)
            if previous_predicate_type != predicate_type:
                errors.append(
                    f"conditional predicate {predicate} has conflicting types: "
                    f"{previous_predicate_type} vs {predicate_type}"
                )
        if not isinstance(predicate_type, str) or not predicate_type:
            errors.append(
                f"conditional.{field}.predicate_type must be a non-empty string"
            )
        if not isinstance(clause.get("surface_predicate"), str) or not clause.get("surface_predicate"):
            errors.append(
                f"conditional.{field}.surface_predicate must be a non-empty string"
            )
        negated = clause.get("negated", False)
        if not isinstance(negated, bool):
            errors.append(f"conditional.{field}.negated must be a boolean")
        if negated:
            negation = clause.get("negation")
            if not isinstance(negation, dict):
                errors.append(f"conditional.{field}.negation must be an object")
            else:
                if negation.get("auxiliary") not in DO_SUPPORT_AUXILIARIES:
                    errors.append(
                        f"conditional.{field}.negation.auxiliary must be do, does, or did"
                    )
                if negation.get("operator") != "not_T":
                    errors.append(
                        f"conditional.{field}.negation.operator must be not_T"
                    )
                if negation.get("type") != "Prop -> Prop":
                    errors.append(
                        f"conditional.{field}.negation.type must be Prop -> Prop"
                    )
        elif "negation" in clause:
            errors.append(
                f"conditional.{field}.negation is allowed only when negated is true"
            )
        check_time_modifiers(
            errors,
            clause.get("time_modifiers", []),
            f"conditional.{field}",
        )
        modifiers = clause.get("modifiers", [])
        has_modifiers = isinstance(modifiers, list) and bool(modifiers)
        uses_modifier_signature = has_modifiers or (
            isinstance(predicate_type, str)
            and predicate_type == simple_conditional_modifier_indexed_predicate_type(clause)
        )
        check_coordination_modifiers(
            errors,
            modifiers,
            f"conditional.{field}",
        )
        subjects = clause.get("subjects")
        subject = clause.get("subject")
        if subjects is not None:
            if subject is not None:
                errors.append(
                    f"conditional.{field}.subject is not allowed with coordinated subjects"
                )
            if not isinstance(subjects, list) or len(subjects) != 2:
                errors.append(
                    f"conditional.{field}.subjects must contain exactly two items"
                )
            else:
                for subject_index, coordinated_subject in enumerate(subjects):
                    if not isinstance(coordinated_subject, dict):
                        errors.append(
                            f"conditional.{field}.subjects[{subject_index}] must be an object"
                        )
                        continue
                    subject_name = coordinated_subject.get("name")
                    if not isinstance(subject_name, str) or not subject_name:
                        errors.append(
                            f"conditional.{field}.subjects[{subject_index}].name must be non-empty"
                        )
                    if coordinated_subject.get("type") != "Entity":
                        errors.append(
                            f"conditional.{field}.subjects[{subject_index}] must have type Entity"
                        )
                    elif isinstance(subject_name, str) and subject_name:
                        previous_type = declarations.setdefault(subject_name, "Entity")
                        if previous_type != "Entity":
                            errors.append(
                                f"conditional declaration {subject_name} has conflicting "
                                f"types: {previous_type} vs Entity"
                            )
            subject_connective = clause.get("subject_connective")
            if not isinstance(subject_connective, dict):
                errors.append(
                    f"conditional.{field}.subject_connective must be an object"
                )
            else:
                expected_subject_connective_type = (
                    "PropT -> PropT -> PropT"
                    if uses_modifier_signature
                    else "Prop -> Prop -> Prop"
                )
                if subject_connective.get("name") not in {"and_T", "or_T"}:
                    errors.append(
                        f"conditional.{field}.subject_connective.name must be and_T or or_T"
                    )
                if subject_connective.get("type") != expected_subject_connective_type:
                    errors.append(
                        "conditional."
                        f"{field}.subject_connective.type must be "
                        f"{expected_subject_connective_type}"
                    )
        elif not isinstance(subject, dict):
            errors.append(f"conditional.{field}.subject must be an object")
        else:
            subject_name = subject.get("name")
            if not isinstance(subject_name, str) or not subject_name:
                errors.append(f"conditional.{field}.subject.name must be non-empty")
            if subject.get("type") != "Entity":
                errors.append(f"conditional.{field}.subject must have type Entity")
            elif isinstance(subject_name, str) and subject_name:
                previous_type = declarations.setdefault(subject_name, "Entity")
                if previous_type != "Entity":
                    errors.append(
                        f"conditional declaration {subject_name} has conflicting "
                        f"types: {previous_type} vs Entity"
                    )

        obj = clause.get("object")
        if obj is None:
            expected_predicate_type = (
                "forall n : nat, ModifierSeq n -> Entity -> PropT"
                if uses_modifier_signature
                else "Entity -> Prop"
            )
            if predicate_type != expected_predicate_type:
                errors.append(
                    f"conditional.{field}.predicate_type must be {expected_predicate_type} "
                    "when no object is present"
                )
        elif not isinstance(obj, dict):
            errors.append(f"conditional.{field}.object must be an object")
        else:
            object_name = obj.get("name")
            object_type = obj.get("type")
            if not isinstance(object_name, str) or not object_name:
                errors.append(f"conditional.{field}.object.name must be non-empty")
            if not isinstance(object_type, str) or not object_type:
                errors.append(f"conditional.{field}.object.type must be non-empty")
            else:
                expected_predicate_type = (
                    f"forall n : nat, ModifierSeq n -> Entity -> {object_type} -> PropT"
                    if uses_modifier_signature
                    else f"Entity -> {object_type} -> Prop"
                )
            if (
                isinstance(object_type, str)
                and object_type
                and predicate_type != expected_predicate_type
            ):
                errors.append(
                    f"conditional.{field}.predicate_type must be "
                    f"{expected_predicate_type}"
                )
            if (
                isinstance(object_name, str)
                and object_name
                and isinstance(object_type, str)
                and object_type
            ):
                previous_type = declarations.setdefault(object_name, object_type)
                if previous_type != object_type:
                    errors.append(
                        f"conditional declaration {object_name} has conflicting "
                        f"types: {previous_type} vs {object_type}"
                    )

    connective = ast.get("connective")
    if not isinstance(connective, dict):
        errors.append("conditional.connective must be an object")
    else:
        if connective.get("name") != "implies":
            errors.append("conditional.connective.name must be implies")
        if connective.get("type") != "Prop -> Prop -> Prop":
            errors.append("conditional.connective.type must be Prop -> Prop -> Prop")

    return {
        "ok": not errors,
        "type": "Prop" if not errors else None,
        "errors": errors,
    }


def parse_simple_conditional_object_tokens(tokens: list[str]) -> str | None:
    if len(tokens) == 1:
        object_tokens = tokens
    elif len(tokens) == 2 and tokens[0] in ARTICLES:
        object_tokens = tokens
    else:
        return None
    if any(
        token in PREPOSITIONS
        or token in UNSUPPORTED_CERTIFIED_CLAUSE_MARKERS
        or token in COMMON_ADVERBS
        or token in TEMPORAL_ADVERBS
        for token in object_tokens
    ):
        return None
    obj = clean_phrase(object_tokens)
    if not obj or obj == "entity":
        return None
    return obj


def parse_simple_conditional_time_modifiers(
    tokens: list[str],
) -> list[dict[str, str]] | None:
    modifier_parse = split_shared_adv_and_time_modifiers(tokens)
    if modifier_parse is None:
        return None
    adv_modifiers, time_modifiers = modifier_parse
    if adv_modifiers:
        return None
    return time_modifiers


def parse_simple_conditional_modifiers(
    tokens: list[str],
) -> tuple[list[dict[str, Any]], list[dict[str, str]]] | None:
    return split_shared_adv_and_time_modifiers(tokens)


def parse_simple_conditional_subject_coordination_clause(
    tokens: list[str],
) -> dict[str, Any] | None:
    if len(tokens) < 4:
        return None
    leading_both = bool(tokens and tokens[0] == "both")
    if leading_both:
        if "and" not in tokens:
            return None
        tokens = tokens[1:]
    coordination = single_boolean_coordinator(tokens)
    if coordination is None:
        return None
    coordinator, coordinator_index = coordination
    if leading_both and coordinator != "and":
        return None
    left_subject_tokens = tokens[:coordinator_index]
    right_side_tokens = tokens[coordinator_index + 1 :]
    if not left_subject_tokens or len(right_side_tokens) < 2:
        return None
    if any(
        token in UNSUPPORTED_CERTIFIED_CLAUSE_MARKERS
        or token in COMMON_ADVERBS
        or token in TEMPORAL_ADVERBS
        for token in left_subject_tokens
    ):
        return None
    predicate_offsets = [
        index
        for index, token in enumerate(right_side_tokens)
        if is_likely_surface_verb(token)
    ]
    if len(predicate_offsets) != 1:
        return None
    predicate_offset = predicate_offsets[0]
    if predicate_offset == 0:
        return None
    right_subject_tokens = right_side_tokens[:predicate_offset]
    if any(
        token in UNSUPPORTED_CERTIFIED_CLAUSE_MARKERS
        or token in COMMON_ADVERBS
        or token in TEMPORAL_ADVERBS
        for token in right_subject_tokens
    ):
        return None
    surface_predicate = right_side_tokens[predicate_offset]
    if surface_predicate in UNSUPPORTED_CERTIFIED_CLAUSE_MARKERS:
        return None
    predicate = lemma_verb(surface_predicate)
    subjects = [
        clean_phrase(left_subject_tokens),
        clean_phrase(right_subject_tokens),
    ]
    if any(subject == "entity" for subject in subjects):
        return None
    tail_tokens = right_side_tokens[predicate_offset + 1 :]
    connective = connective_for_coordinator(coordinator)
    if not is_likely_transitive_verb(surface_predicate):
        modifier_parse = parse_simple_conditional_modifiers(tail_tokens)
        if modifier_parse is None:
            return None
        modifiers, time_modifiers = modifier_parse
        return {
            "subjects": subjects,
            "connective": connective,
            "predicate": predicate,
            "surface_predicate": surface_predicate,
            "modifiers": modifiers,
            "time_modifiers": time_modifiers,
        }
    candidates: list[dict[str, Any]] = []
    for split_index in range(1, len(tail_tokens) + 1):
        object_tokens = tail_tokens[:split_index]
        modifier_tokens = tail_tokens[split_index:]
        obj = parse_simple_conditional_object_tokens(object_tokens)
        modifier_parse = parse_simple_conditional_modifiers(modifier_tokens)
        if obj is not None and modifier_parse is not None:
            modifiers, time_modifiers = modifier_parse
            candidates.append(
                {
                    "subjects": subjects,
                    "connective": connective,
                    "predicate": predicate,
                    "surface_predicate": surface_predicate,
                    "obj": obj,
                    "object_type": object_type_for_transitive_predicate(predicate),
                    "modifiers": modifiers,
                    "time_modifiers": time_modifiers,
                }
            )
    if len(candidates) != 1:
        return None
    return candidates[0]


def parse_simple_conditional_clause(tokens: list[str]) -> dict[str, Any] | None:
    subject_coordination = parse_simple_conditional_subject_coordination_clause(tokens)
    if subject_coordination is not None:
        return subject_coordination
    if len(tokens) < 2:
        return None
    subject = tokens[0]
    negated = False
    auxiliary: str | None = None
    if len(tokens) >= 4 and tokens[1] in DO_SUPPORT_AUXILIARIES and tokens[2] == "not":
        auxiliary = tokens[1]
        surface_predicate = tokens[3]
        tail_tokens = tokens[4:]
        negated = True
    else:
        surface_predicate = tokens[1]
        tail_tokens = tokens[2:]
    if (
        subject in ARTICLES
        or subject in PREPOSITIONS
        or subject in UNSUPPORTED_CERTIFIED_CLAUSE_MARKERS
        or surface_predicate in UNSUPPORTED_CERTIFIED_CLAUSE_MARKERS
        or not is_likely_surface_verb(surface_predicate)
    ):
        return None
    predicate = lemma_verb(surface_predicate)
    if len(tokens) == 2:
        if is_likely_transitive_verb(surface_predicate):
            return None
        return {
            "subject": clean_phrase([subject]),
            "predicate": predicate,
            "surface_predicate": surface_predicate,
            "negated": negated,
            "auxiliary": auxiliary,
        }
    if not is_likely_transitive_verb(surface_predicate):
        modifier_parse = parse_simple_conditional_modifiers(tail_tokens)
        if modifier_parse is None:
            return None
        modifiers, time_modifiers = modifier_parse
        return {
            "subject": clean_phrase([subject]),
            "predicate": predicate,
            "surface_predicate": surface_predicate,
            "modifiers": modifiers,
            "time_modifiers": time_modifiers,
            "negated": negated,
            "auxiliary": auxiliary,
        }
    candidates: list[dict[str, Any]] = []
    for split_index in range(1, len(tail_tokens) + 1):
        object_tokens = tail_tokens[:split_index]
        modifier_tokens = tail_tokens[split_index:]
        obj = parse_simple_conditional_object_tokens(object_tokens)
        modifier_parse = parse_simple_conditional_modifiers(modifier_tokens)
        if obj is not None and modifier_parse is not None:
            modifiers, time_modifiers = modifier_parse
            candidates.append(
                {
                    "subject": clean_phrase([subject]),
                    "predicate": predicate,
                    "surface_predicate": surface_predicate,
                    "obj": obj,
                    "object_type": object_type_for_transitive_predicate(predicate),
                    "modifiers": modifiers,
                    "time_modifiers": time_modifiers,
                    "negated": negated,
                    "auxiliary": auxiliary,
                }
            )
    if len(candidates) != 1:
        return None
    return candidates[0]


def split_simple_conditional_tokens(tokens: list[str]) -> tuple[list[str], list[str]] | None:
    if not tokens or tokens[0] != "if":
        return None
    if "then" in tokens:
        then_index = tokens.index("then")
        antecedent_tokens = tokens[1:then_index]
        consequent_tokens = tokens[then_index + 1 :]
        return antecedent_tokens, consequent_tokens
    body = tokens[1:]
    candidates: list[tuple[list[str], list[str]]] = []
    for split_index in range(2, len(body) - 1):
        antecedent_tokens = body[:split_index]
        consequent_tokens = body[split_index:]
        if (
            parse_simple_conditional_clause(antecedent_tokens) is not None
            and parse_simple_conditional_clause(consequent_tokens) is not None
        ):
            candidates.append((antecedent_tokens, consequent_tokens))
    if len(candidates) == 1:
        return candidates[0]
    return None


def simple_conditional_clause_formula(clause: dict[str, Any], *, coq: bool) -> str:
    predicate = clause["predicate"]
    obj = clause.get("object")
    modifiers = clause.get("modifiers", [])
    uses_modifier_signature = simple_conditional_clause_uses_modifier_signature(clause)

    def atomic_formula(subject_name: str) -> str:
        if uses_modifier_signature:
            modifier_count = len(modifiers)
            if coq:
                modifier_sequence = coq_modifier_sequence(modifiers)
                if obj is None:
                    return f"{predicate} {modifier_count} {modifier_sequence} {subject_name}"
                return (
                    f"{predicate} {modifier_count} {modifier_sequence} "
                    f"{subject_name} {obj['name']}"
                )
            modifier_args = readable_modifier_arguments(modifiers)
            if obj is None:
                if modifier_args:
                    return f"{predicate}({modifier_count})({modifier_args}, {subject_name})"
                return f"{predicate}(0)({subject_name})"
            return (
                f"{predicate}({modifier_count})"
                f"({modifier_args + ', ' if modifier_args else ''}{subject_name}, {obj['name']})"
            )
        if obj is None:
            return f"{predicate} {subject_name}" if coq else f"{predicate}({subject_name})"
        object_name = obj["name"]
        if coq:
            return f"{predicate} {subject_name} {object_name}"
        return f"{predicate}({subject_name}, {object_name})"

    if "subjects" in clause:
        arguments = [
            atomic_formula(subject["name"])
            for subject in clause["subjects"]
            if isinstance(subject, dict)
        ]
        connective = clause["subject_connective"]["name"]
        body = (
            render_binary_connective_coq(connective, arguments)
            if coq
            else render_binary_connective_translation(connective, arguments)
        )
    else:
        body = atomic_formula(clause["subject"]["name"])
    timed_body = render_quantifier_time_wrapped_reading(
        body,
        clause.get("time_modifiers", []),
        coq=coq,
    )
    if coq:
        return wrap_negated_coq(timed_body, bool(clause.get("negated", False)))
    return wrap_negated_translation(timed_body, bool(clause.get("negated", False)))


def simple_conditional_event_reference(clause: dict[str, Any], event_name: str) -> str:
    subject_name = clause.get("subject", {}).get("name")
    if not subject_name:
        raise ValueError("simple conditional event reference requires a singular subject")
    parts = [
        f"{clause['predicate']}({event_name})",
        f"Agent({event_name}, {subject_name})",
    ]
    obj = clause.get("object")
    if isinstance(obj, dict):
        parts.append(f"Theme({event_name}, {obj['name']})")
    for modifier in clause.get("modifiers", []):
        expression = modifier["expression"]
        if "(" in expression and expression.endswith(")"):
            role_name, argument = expression.split("(", 1)
            parts.append(f"{role_name}({event_name}, {argument[:-1]})")
        else:
            parts.append(f"{expression}({event_name})")
    for modifier in clause.get("time_modifiers", []):
        parts.append(f"{modifier['operator']}({event_name}, {modifier['argument']})")
    return " and ".join(parts)


def simple_conditional_event_quantified_reference(
    clause: dict[str, Any],
    event_name: str,
) -> str:
    if "subjects" in clause:
        connective = clause["subject_connective"]["name"]
        joiner = " and " if connective == "and_T" else " or "
        references = []
        for index, subject in enumerate(clause["subjects"], start=1):
            scoped_clause = {
                key: value
                for key, value in clause.items()
                if key not in {"subjects", "subject_connective"}
            }
            scoped_clause["subject"] = subject
            scoped_event_name = f"{event_name}{index}"
            references.append(
                f"exists {scoped_event_name}. "
                f"{simple_conditional_event_reference(scoped_clause, scoped_event_name)}"
            )
        reference = joiner.join(f"({reference})" for reference in references)
    else:
        reference = f"exists {event_name}. {simple_conditional_event_reference(clause, event_name)}"
    if clause.get("negated", False):
        return f"not({reference})"
    return reference


def simple_conditional_declarations(
    antecedent: dict[str, Any],
    consequent: dict[str, Any],
) -> tuple[dict[str, str], dict[str, str]]:
    value_declarations: dict[str, str] = {}
    predicate_declarations: dict[str, str] = {}
    for clause in (antecedent, consequent):
        if "subjects" in clause:
            for subject in clause["subjects"]:
                value_declarations[subject["name"]] = "Entity"
        else:
            value_declarations[clause["subject"]["name"]] = "Entity"
        obj = clause.get("object")
        if isinstance(obj, dict):
            value_declarations[obj["name"]] = obj["type"]
        for modifier in clause.get("time_modifiers", []):
            value_declarations[modifier["argument"]] = "Entity"
        predicate_declarations[clause["predicate"]] = clause["predicate_type"]
    return value_declarations, predicate_declarations


def simple_conditional_pipeline(sentence: str) -> dict[str, Any] | None:
    tokens = tokenize(sentence)
    split = split_simple_conditional_tokens(tokens)
    if split is None:
        return None
    antecedent_tokens, consequent_tokens = split
    antecedent_clause = parse_simple_conditional_clause(antecedent_tokens)
    consequent_clause = parse_simple_conditional_clause(consequent_tokens)
    if antecedent_clause is None or consequent_clause is None:
        return None

    antecedent = simple_conditional_clause_ast(**antecedent_clause)
    consequent = simple_conditional_clause_ast(**consequent_clause)
    ast = simple_conditional_ast(antecedent, consequent)
    normalize_simple_conditional_predicate_signatures(ast)
    type_check = check_simple_conditional_ast(ast)
    antecedent_formula = simple_conditional_clause_formula(antecedent, coq=False)
    consequent_formula = simple_conditional_clause_formula(consequent, coq=False)
    typed_replacement = f"{antecedent_formula} -> {consequent_formula}"
    coq_definition = "simple_conditional_implication"
    value_declarations, predicate_declarations = simple_conditional_declarations(
        antecedent,
        consequent,
    )
    object_type_declarations = list(
        dict.fromkeys(
            value_type
            for value_type in value_declarations.values()
            if value_type != "Entity"
        )
    )
    time_modifiers = [
        modifier
        for clause in (antecedent, consequent)
        for modifier in clause.get("time_modifiers", [])
    ]
    adv_modifiers = [
        modifier
        for clause in (antecedent, consequent)
        for modifier in clause.get("modifiers", [])
    ]
    has_modifier_signature = any(
        simple_conditional_clause_uses_modifier_signature(clause)
        for clause in (antecedent, consequent)
    )
    has_negation = any(
        clause.get("negated", False) for clause in (antecedent, consequent)
    )
    subject_connective_types: dict[str, str] = {}
    for clause in (antecedent, consequent):
        subject_connective = clause.get("subject_connective")
        if isinstance(subject_connective, dict):
            connective_name = subject_connective["name"]
            connective_type = (
                "PropT -> PropT -> PropT"
                if has_modifier_signature
                else subject_connective["type"]
            )
            previous_type = subject_connective_types.get(connective_name)
            if previous_type is None or previous_type == "Prop -> Prop -> Prop":
                subject_connective_types[connective_name] = connective_type
    coq_antecedent = simple_conditional_clause_formula(antecedent, coq=True)
    coq_consequent = simple_conditional_clause_formula(consequent, coq=True)
    coq_code = "\n".join(
        [
            "(* Simple conditional replacement without an event variable. *)",
            "Parameter Entity : Type.",
            *[f"Parameter {type_name} : Type." for type_name in object_type_declarations],
            *(
                [
                    "Definition PropT : Type := Prop.",
                    "Definition Adv : Type := (Entity -> PropT) -> Entity -> PropT.",
                    "Parameter ModifierSeq : nat -> Type.",
                    "Parameter mods_nil : ModifierSeq 0.",
                    "Parameter mods_cons : forall n : nat, Adv -> ModifierSeq n -> ModifierSeq (S n).",
                ]
                if has_modifier_signature
                else []
            ),
            *[
                f"Parameter {name} : Adv."
                for name in unique_names([modifier["name"] for modifier in adv_modifiers])
            ],
            "",
            *[
                f"Parameter {name} : {value_type}."
                for name, value_type in value_declarations.items()
            ],
            "",
            *[
                f"Parameter {name} : {predicate_type}."
                for name, predicate_type in predicate_declarations.items()
            ],
            *(
                [
                    "Parameter at_T : Entity -> Prop -> Prop.",
                    "Parameter during_T : Entity -> Prop -> Prop.",
                ]
                if time_modifiers
                else []
            ),
            *[
                f"Parameter {connective} : {connective_type}."
                for connective, connective_type in subject_connective_types.items()
            ],
            *(["Parameter not_T : Prop -> Prop."] if has_negation else []),
            "",
            f"Definition {coq_definition} : Prop :=",
            f"  {coq_antecedent} -> {coq_consequent}.",
            "",
            f"Check {coq_definition}.",
            "",
        ]
    )
    consequent_event_name = "e'"
    event_semantics = {
        "analysis": "simple-conditional",
        "source": sentence,
        "event_style_reference": (
            f"({simple_conditional_event_quantified_reference(antecedent, 'e')}) -> "
            f"({simple_conditional_event_quantified_reference(consequent, consequent_event_name)})"
        ),
        "typed_replacement": typed_replacement,
    }
    return attach_single_semantic_reading(
        {
            "kind": "simple_conditional",
            "input_sentence": sentence,
            "event_semantics": event_semantics,
            "dependent_type_translation": typed_replacement,
            "ast": ast,
            "type_check": {
                **type_check,
                "note": (
                    "The if-clause is represented as implication between typed "
                    "propositions; no Event, Agent, or Theme declaration is exported."
                ),
            },
            "coq_code": coq_code,
        },
        name="simple_conditional_implication",
        coq_definition=coq_definition,
        source="simple_conditional",
        scope="antecedent_implies_consequent",
    )


def causal_because_ast(
    cause: dict[str, Any],
    effect: dict[str, Any],
) -> dict[str, Any]:
    return {
        "kind": "causal_because",
        "cause": cause,
        "effect": effect,
        "connective": {
            "name": "because_T",
            "type": "Prop -> Prop -> Prop",
        },
    }


def check_causal_because_ast(ast: dict[str, Any]) -> dict[str, Any]:
    errors: list[str] = []
    incompatible_state_pairs: list[dict[str, str]] = []
    if ast.get("kind") != "causal_because":
        errors.append("causal_because.kind must be causal_because")

    connective = ast.get("connective")
    if not isinstance(connective, dict):
        errors.append("causal_because.connective must be an object")
    else:
        if connective.get("name") != "because_T":
            errors.append("causal_because.connective.name must be because_T")
        if connective.get("type") != "Prop -> Prop -> Prop":
            errors.append(
                "causal_because.connective.type must be Prop -> Prop -> Prop"
            )

    cause = ast.get("cause")
    effect = ast.get("effect")
    for field, clause in (("cause", cause), ("effect", effect)):
        if causal_because_clause_is_state_change(clause):
            state_check = check_lexical_state_change_ast(clause)
            errors.extend(
                f"causal_because.{field}: {error}"
                for error in state_check["errors"]
            )
        elif causal_because_clause_is_stative_state(clause):
            stative_check = check_stative_result_state_ast(clause)
            errors.extend(
                f"causal_because.{field}: {error}"
                for error in stative_check["errors"]
            )
            incompatible_state_pairs.extend(
                {
                    **pair,
                    "clause": field,
                    "path": f"causal_because.{field}",
                }
                for pair in stative_check.get("incompatible_state_pairs", [])
                if isinstance(pair, dict)
            )
        elif isinstance(clause, dict):
            simple_check = check_simple_conditional_ast(
                {
                    "kind": "conditional_implication",
                    "antecedent": clause,
                    "consequent": copy.deepcopy(clause),
                    "connective": {
                        "name": "implies",
                        "type": "Prop -> Prop -> Prop",
                    },
                }
            )
            errors.extend(
                error.replace("conditional.antecedent", f"causal_because.{field}")
                .replace("conditional.consequent", f"causal_because.{field}")
                .replace("conditional predicate", "causal_because predicate")
                for error in simple_check["errors"]
            )
        else:
            errors.append(f"causal_because.{field} must be a clause object")
    errors.extend(causal_because_declaration_conflicts(cause, effect))

    result = {
        "ok": not errors,
        "type": "Prop" if not errors else None,
        "errors": errors,
    }
    if incompatible_state_pairs:
        result["incompatible_state_pairs"] = incompatible_state_pairs
    return result


def split_causal_because_tokens(tokens: list[str]) -> tuple[list[str], list[str]] | None:
    if tokens.count("because") != 1:
        return None
    because_index = tokens.index("because")
    if because_index == 0 or because_index == len(tokens) - 1:
        return None
    effect_tokens = tokens[:because_index]
    cause_tokens = tokens[because_index + 1 :]
    if "if" in effect_tokens or "if" in cause_tokens:
        return None
    return effect_tokens, cause_tokens


def causal_because_clause_is_state_change(clause: Any) -> bool:
    return isinstance(clause, dict) and clause.get("kind") == "lexical_state_change"


def causal_because_clause_is_stative_state(clause: Any) -> bool:
    return isinstance(clause, dict) and clause.get("kind") == "stative_result_state"


def causal_because_clause_is_simple_predication(clause: Any) -> bool:
    return (
        isinstance(clause, dict)
        and not causal_because_clause_is_state_change(clause)
        and not causal_because_clause_is_stative_state(clause)
    )


def parse_causal_because_clause(
    tokens: list[str],
    *,
    include_invalid_stative: bool = False,
) -> dict[str, Any] | None:
    sentence = " ".join(tokens)
    state_change = lexical_state_change_pipeline(sentence)
    if (
        state_change is not None
        and state_change.get("type_check", {}).get("ok") is True
    ):
        return copy.deepcopy(state_change["ast"])

    stative_state = stative_result_state_pipeline(sentence)
    if stative_state is not None and (
        stative_state.get("type_check", {}).get("ok") is True
        or include_invalid_stative
    ):
        return copy.deepcopy(stative_state["ast"])

    simple_clause = parse_simple_conditional_clause(tokens)
    if simple_clause is None:
        return None
    return simple_conditional_clause_ast(**simple_clause)


def causal_because_stative_state_records(clause: dict[str, Any]) -> list[dict[str, Any]]:
    states = clause.get("states")
    if isinstance(states, list) and states:
        return [state for state in states if isinstance(state, dict)]
    state = clause.get("state")
    return [state] if isinstance(state, dict) else []


def causal_because_stative_state_names(clause: dict[str, Any]) -> list[str]:
    return [
        state["name"]
        for state in causal_because_stative_state_records(clause)
        if isinstance(state.get("name"), str)
    ]


def causal_because_stative_state_scales(clause: dict[str, Any]) -> list[str]:
    scales = []
    for state in causal_because_stative_state_records(clause):
        scale = state.get("state_scale")
        if isinstance(scale, str):
            scales.append(scale)
            continue
        state_name = state.get("name")
        if isinstance(state_name, str) and state_name in STATE_SCALE_BY_STATE:
            scales.append(STATE_SCALE_BY_STATE[state_name])
    if not scales and isinstance(clause.get("state_scale"), str):
        scales.append(clause["state_scale"])
    return scales


def causal_because_patient_candidates(
    clause: dict[str, Any],
    *,
    source_clause: str,
) -> list[dict[str, str]]:
    if causal_because_clause_is_state_change(clause):
        theme = clause.get("transition", {}).get("theme", {})
        state_scale = clause.get("transition", {}).get("state_scale")
        if (
            isinstance(theme, dict)
            and isinstance(theme.get("name"), str)
            and theme["name"] not in ANAPHORIC_ENTITY_PRONOUNS
        ):
            return [
                {
                    "name": theme["name"],
                    "type": "Entity",
                    "source_clause": source_clause,
                    "source_role": "theme",
                    **(
                        {"state_scales": state_scale}
                        if isinstance(state_scale, str)
                        else {}
                    ),
                }
            ]
        return []

    if causal_because_clause_is_stative_state(clause):
        subject = clause.get("subject", {})
        if (
            isinstance(subject, dict)
            and isinstance(subject.get("name"), str)
            and subject["name"] not in ANAPHORIC_ENTITY_PRONOUNS
        ):
            return [
                {
                    "name": subject["name"],
                    "type": "Entity",
                    "source_clause": source_clause,
                    "source_role": "subject",
                    "state_scales": ",".join(causal_because_stative_state_scales(clause)),
                }
            ]
        return []

    obj = clause.get("object")
    if (
        isinstance(obj, dict)
        and isinstance(obj.get("name"), str)
        and obj.get("type") == "Entity"
        and obj["name"] not in ANAPHORIC_ENTITY_PRONOUNS
    ):
        return [
            {
                "name": obj["name"],
                "type": "Entity",
                "source_clause": source_clause,
                "source_role": "object",
            }
        ]
    return []


def causal_because_candidate_compatible_with_state_change(
    clause: dict[str, Any],
    candidate: dict[str, str],
) -> bool:
    verb = clause.get("verb")
    if not isinstance(verb, str):
        return False
    transition = clause.get("transition", {})
    state_scale = transition.get("state_scale") if isinstance(transition, dict) else None
    candidate_scales = set(
        scale
        for scale in candidate.get("state_scales", "").split(",")
        if scale
    )
    if isinstance(state_scale, str) and state_scale in candidate_scales:
        return True
    compatible_themes = STATE_CHANGE_ANAPHORA_COMPATIBLE_THEMES.get(verb, set())
    return candidate.get("name") in compatible_themes


def causal_because_candidate_compatible_with_stative_state(
    clause: dict[str, Any],
    candidate: dict[str, str],
) -> bool:
    candidate_scales = set(
        scale
        for scale in candidate.get("state_scales", "").split(",")
        if scale
    )
    state_scales = set(causal_because_stative_state_scales(clause))
    if candidate_scales:
        return bool(state_scales) and state_scales <= candidate_scales
    state_names = causal_because_stative_state_names(clause)
    candidate_name = candidate.get("name")
    return all(
        candidate_name in STATE_ANAPHORA_COMPATIBLE_THEMES.get(state_name, set())
        for state_name in state_names
    )


def resolve_causal_because_state_change_anaphora(
    cause: dict[str, Any],
    effect: dict[str, Any],
) -> list[str]:
    errors: list[str] = []
    pairs = (
        ("cause", cause, "effect", effect),
        ("effect", effect, "cause", cause),
    )
    for label, clause, other_label, other_clause in pairs:
        if causal_because_clause_is_state_change(clause):
            pronoun_holder = clause.get("transition", {}).get("theme")
            subject_label = "theme"
            compatibility = causal_because_candidate_compatible_with_state_change
        elif causal_because_clause_is_stative_state(clause):
            pronoun_holder = clause.get("subject")
            subject_label = "subject"
            compatibility = causal_because_candidate_compatible_with_stative_state
        else:
            continue
        if not isinstance(pronoun_holder, dict):
            continue
        pronoun = pronoun_holder.get("name")
        if pronoun not in ANAPHORIC_ENTITY_PRONOUNS:
            continue
        candidates = [
            candidate
            for candidate in causal_because_patient_candidates(
                other_clause,
                source_clause=other_label,
            )
            if compatibility(clause, candidate)
        ]
        if len(candidates) != 1:
            if candidates:
                candidate_names = ", ".join(candidate["name"] for candidate in candidates)
                errors.append(
                    f"causal_because.{label}.{subject_label} pronoun {pronoun} is ambiguous "
                    f"among compatible antecedents: {candidate_names}"
                )
            else:
                errors.append(
                    f"causal_because.{label}.{subject_label} pronoun {pronoun} has no "
                    "unique compatible antecedent"
                )
            continue
        antecedent = candidates[0]
        pronoun_holder["name"] = antecedent["name"]
        pronoun_holder["anaphora"] = {
            "pronoun": pronoun,
            "resolved_to": antecedent["name"],
            "source_clause": antecedent["source_clause"],
            "source_role": antecedent["source_role"],
            "resolution_policy": "single_compatible_patient",
        }
    return errors


def state_change_coq_expression(ast: dict[str, Any]) -> str:
    transition = ast["transition"]
    theme = transition["theme"]["name"]
    state_scale = transition["state_scale"]
    source_state = transition["source_state"]
    target_state = transition["target_state"]["name"]
    transition_coq = f"Transition {theme} {state_scale} {source_state} {target_state}"
    causer = ast.get("causer")
    instrument = ast.get("instrument")
    if instrument is not None and causer is not None:
        return (
            f"CauseWithInstrument {causer['name']} {instrument['name']} "
            f"({transition_coq})"
        )
    if causer is not None:
        return f"Cause {causer['name']} ({transition_coq})"
    return f"Change ({transition_coq})"


def stative_result_state_expression(ast: dict[str, Any], *, coq: bool) -> str:
    subject = ast["subject"]["name"]
    assertions = []
    for state in causal_because_stative_state_records(ast):
        state_name = state["name"]
        state_scale = state.get("state_scale", STATE_SCALE_BY_STATE[state_name])
        if coq:
            assertions.append(f"holds_state {subject} {state_scale} {state_name}")
        else:
            assertions.append(f"holds_state({subject}, {state_scale}, {state_name})")
    expression = assertions[0]
    for next_assertion in assertions[1:]:
        expression = (
            f"and_T ({expression}) ({next_assertion})"
            if coq
            else f"and_T({expression}, {next_assertion})"
        )
    if ast.get("polarity", "positive") == "negative":
        expression = f"not_T ({expression})" if coq else f"not_T({expression})"
    return expression


def causal_because_clause_formula(clause: dict[str, Any], *, coq: bool) -> str:
    if causal_because_clause_is_state_change(clause):
        return state_change_coq_expression(clause) if coq else render_state_change_translation(clause)
    if causal_because_clause_is_stative_state(clause):
        return stative_result_state_expression(clause, coq=coq)
    return simple_conditional_clause_formula(clause, coq=coq)


def causal_because_clause_event_reference(
    clause: dict[str, Any],
    event_name: str,
) -> str:
    if (
        not causal_because_clause_is_state_change(clause)
        and not causal_because_clause_is_stative_state(clause)
    ):
        return simple_conditional_event_quantified_reference(clause, event_name)
    if causal_because_clause_is_stative_state(clause):
        subject = clause["subject"]["name"]
        state_parts = [
            f"ResultState({event_name}, {state_name})"
            for state_name in causal_because_stative_state_names(clause)
        ]
        reference = (
            f"exists {event_name}. Theme({event_name}, {subject}) and "
            + " and ".join(state_parts)
        )
        if clause.get("polarity", "positive") == "negative":
            return f"not({reference})"
        return reference
    transition = clause["transition"]
    parts = [
        f"{clause['verb']}({event_name})",
        f"Theme({event_name}, {transition['theme']['name']})",
        f"SourceState({event_name}, {transition['source_state']})",
        f"ResultState({event_name}, {transition['target_state']['name']})",
    ]
    causer = clause.get("causer")
    if isinstance(causer, dict):
        parts.append(f"Causer({event_name}, {causer['name']})")
    instrument = clause.get("instrument")
    if isinstance(instrument, dict):
        parts.append(f"Instrument({event_name}, {instrument['name']})")
    return f"exists {event_name}. " + " and ".join(parts)


def add_typed_declaration(
    declarations: dict[str, str],
    errors: list[str],
    name: str,
    type_name: str,
    *,
    label: str,
) -> None:
    previous = declarations.setdefault(name, type_name)
    if previous != type_name:
        errors.append(
            f"causal_because declaration {name} has conflicting types in {label}: "
            f"{previous} vs {type_name}"
        )


def causal_because_collect_clause_declarations(
    clause: Any,
    declarations: dict[str, str],
    errors: list[str],
    *,
    label: str,
) -> None:
    if not isinstance(clause, dict):
        return
    if causal_because_clause_is_state_change(clause):
        transition = clause.get("transition", {})
        if isinstance(transition, dict):
            theme = transition.get("theme", {})
            target_state = transition.get("target_state", {})
            if isinstance(theme, dict) and isinstance(theme.get("name"), str):
                add_typed_declaration(
                    declarations,
                    errors,
                    theme["name"],
                    "Entity",
                    label=label,
                )
            source_state = transition.get("source_state")
            if isinstance(source_state, str):
                add_typed_declaration(
                    declarations,
                    errors,
                    source_state,
                    "State",
                    label=label,
                )
            if isinstance(target_state, dict) and isinstance(target_state.get("name"), str):
                add_typed_declaration(
                    declarations,
                    errors,
                    target_state["name"],
                    "State",
                    label=label,
                )
            state_scale = transition.get("state_scale")
            if isinstance(state_scale, str):
                add_typed_declaration(
                    declarations,
                    errors,
                    state_scale,
                    "StateScale",
                    label=label,
                )
        causer = clause.get("causer")
        if isinstance(causer, dict) and isinstance(causer.get("name"), str):
            add_typed_declaration(
                declarations,
                errors,
                causer["name"],
                "Entity",
                label=label,
            )
        instrument = clause.get("instrument")
        if isinstance(instrument, dict) and isinstance(instrument.get("name"), str):
            add_typed_declaration(
                declarations,
                errors,
                instrument["name"],
                "Entity",
                label=label,
            )
        return

    if causal_because_clause_is_stative_state(clause):
        subject = clause.get("subject", {})
        if isinstance(subject, dict) and isinstance(subject.get("name"), str):
            add_typed_declaration(
                declarations,
                errors,
                subject["name"],
                "Entity",
                label=label,
            )
        for state_name in causal_because_stative_state_names(clause):
            add_typed_declaration(
                declarations,
                errors,
                state_name,
                "State",
                label=label,
            )
        for state_scale in causal_because_stative_state_scales(clause):
            add_typed_declaration(
                declarations,
                errors,
                state_scale,
                "StateScale",
                label=label,
            )
        return

    if "subjects" in clause:
        for subject in clause["subjects"]:
            if isinstance(subject, dict) and isinstance(subject.get("name"), str):
                add_typed_declaration(
                    declarations,
                    errors,
                    subject["name"],
                    "Entity",
                    label=label,
                )
    else:
        subject = clause.get("subject")
        if isinstance(subject, dict) and isinstance(subject.get("name"), str):
            add_typed_declaration(
                declarations,
                errors,
                subject["name"],
                "Entity",
                label=label,
            )
    obj = clause.get("object")
    if isinstance(obj, dict) and isinstance(obj.get("name"), str) and isinstance(obj.get("type"), str):
        add_typed_declaration(
            declarations,
            errors,
            obj["name"],
            obj["type"],
            label=label,
        )
    for modifier in clause.get("time_modifiers", []):
        if isinstance(modifier, dict) and isinstance(modifier.get("argument"), str):
            add_typed_declaration(
                declarations,
                errors,
                modifier["argument"],
                "Entity",
                label=label,
            )


def causal_because_declaration_conflicts(
    cause: Any,
    effect: Any,
) -> list[str]:
    errors: list[str] = []
    declarations: dict[str, str] = {}
    causal_because_collect_clause_declarations(
        cause,
        declarations,
        errors,
        label="cause",
    )
    causal_because_collect_clause_declarations(
        effect,
        declarations,
        errors,
        label="effect",
    )
    return errors


def causal_because_state_value_declarations(
    clauses: tuple[dict[str, Any], dict[str, Any]],
) -> tuple[dict[str, str], list[str]]:
    declarations: dict[str, str] = {}
    errors: list[str] = []
    for label, clause in zip(("cause", "effect"), clauses):
        causal_because_collect_clause_declarations(
            clause,
            declarations,
            errors,
            label=label,
        )
    return declarations, errors


def causal_because_pipeline(sentence: str) -> dict[str, Any] | None:
    tokens = tokenize(sentence)
    split = split_causal_because_tokens(tokens)
    if split is None:
        return None
    effect_tokens, cause_tokens = split
    effect = parse_causal_because_clause(
        effect_tokens,
        include_invalid_stative=True,
    )
    cause = parse_causal_because_clause(
        cause_tokens,
        include_invalid_stative=True,
    )
    if effect is None or cause is None:
        return None

    anaphora_errors = resolve_causal_because_state_change_anaphora(cause, effect)
    normalize_simple_conditional_predicate_signatures(
        {
            "antecedent": cause if causal_because_clause_is_simple_predication(cause) else None,
            "consequent": effect if causal_because_clause_is_simple_predication(effect) else None,
        }
    )
    ast = causal_because_ast(cause, effect)
    type_check = check_causal_because_ast(ast)
    if anaphora_errors and type_check["ok"]:
        type_check = {
            "ok": False,
            "type": None,
            "errors": anaphora_errors,
        }
    cause_formula = causal_because_clause_formula(cause, coq=False)
    effect_formula = causal_because_clause_formula(effect, coq=False)
    typed_replacement = f"because_T({cause_formula}, {effect_formula})"
    coq_definition = "causal_because"
    simple_clauses = [
        clause
        for clause in (cause, effect)
        if causal_because_clause_is_simple_predication(clause)
    ]
    if len(simple_clauses) == 2:
        value_declarations, predicate_declarations = simple_conditional_declarations(
            simple_clauses[0],
            simple_clauses[1],
        )
    elif len(simple_clauses) == 1:
        value_declarations, predicate_declarations = simple_conditional_declarations(
            simple_clauses[0],
            copy.deepcopy(simple_clauses[0]),
        )
    else:
        value_declarations, predicate_declarations = {}, {}
    state_declarations, declaration_errors = causal_because_state_value_declarations(
        (cause, effect),
    )
    for name, value_type in state_declarations.items():
        previous = value_declarations.setdefault(name, value_type)
        if previous != value_type:
            declaration_errors.append(
                f"causal_because declaration {name} has conflicting types: "
                f"{previous} vs {value_type}"
            )
    if declaration_errors and type_check["ok"]:
        type_check = {
            "ok": False,
            "type": None,
            "errors": declaration_errors,
        }
    object_type_declarations = list(
        dict.fromkeys(
            value_type
            for value_type in value_declarations.values()
            if value_type != "Entity"
        )
    )
    time_modifiers = [
        modifier
        for clause in (cause, effect)
        if causal_because_clause_is_simple_predication(clause)
        for modifier in clause.get("time_modifiers", [])
    ]
    adv_modifiers = [
        modifier
        for clause in (cause, effect)
        if causal_because_clause_is_simple_predication(clause)
        for modifier in clause.get("modifiers", [])
    ]
    has_modifier_signature = any(
        simple_conditional_clause_uses_modifier_signature(clause)
        for clause in (cause, effect)
        if causal_because_clause_is_simple_predication(clause)
    )
    has_negation = any(
        clause.get("negated", False)
        for clause in (cause, effect)
        if causal_because_clause_is_simple_predication(clause)
    ) or any(
        causal_because_clause_is_stative_state(clause)
        and clause.get("polarity", "positive") == "negative"
        for clause in (cause, effect)
    )
    subject_connective_types: dict[str, str] = {}
    for clause in (cause, effect):
        if not causal_because_clause_is_simple_predication(clause):
            continue
        subject_connective = clause.get("subject_connective")
        if isinstance(subject_connective, dict):
            connective_name = subject_connective["name"]
            connective_type = (
                "PropT -> PropT -> PropT"
                if has_modifier_signature
                else subject_connective["type"]
            )
            previous_type = subject_connective_types.get(connective_name)
            if previous_type is None or previous_type == "Prop -> Prop -> Prop":
                subject_connective_types[connective_name] = connective_type
    requires_stative_and = any(
        causal_because_clause_is_stative_state(clause)
        and len(causal_because_stative_state_records(clause)) > 1
        for clause in (cause, effect)
    )
    if requires_stative_and and "and_T" not in subject_connective_types:
        subject_connective_types["and_T"] = "Prop -> Prop -> Prop"

    requires_state_change = any(
        causal_because_clause_is_state_change(clause)
        for clause in (cause, effect)
    )
    requires_stative_state = any(
        causal_because_clause_is_stative_state(clause)
        for clause in (cause, effect)
    )
    if requires_state_change or requires_stative_state:
        object_type_declarations.extend(["State", "StateScale"])
    if requires_state_change:
        object_type_declarations.append("TransitionT")
    object_type_declarations = list(dict.fromkeys(object_type_declarations))

    coq_cause = causal_because_clause_formula(cause, coq=True)
    coq_effect = causal_because_clause_formula(effect, coq=True)
    coq_code = "\n".join(
        [
            "(* Proposition-level causal because replacement without an event variable. *)",
            "Parameter Entity : Type.",
            *[f"Parameter {type_name} : Type." for type_name in object_type_declarations],
            *(
                [
                    "Definition PropT : Type := Prop.",
                    "Definition Adv : Type := (Entity -> PropT) -> Entity -> PropT.",
                    "Parameter ModifierSeq : nat -> Type.",
                    "Parameter mods_nil : ModifierSeq 0.",
                    "Parameter mods_cons : forall n : nat, Adv -> ModifierSeq n -> ModifierSeq (S n).",
                ]
                if has_modifier_signature
                else []
            ),
            *[
                f"Parameter {name} : Adv."
                for name in unique_names([modifier["name"] for modifier in adv_modifiers])
            ],
            "",
            *[
                f"Parameter {name} : {value_type}."
                for name, value_type in value_declarations.items()
            ],
            "",
            *[
                f"Parameter {name} : {predicate_type}."
                for name, predicate_type in predicate_declarations.items()
            ],
            *(
                [
                    "Parameter at_T : Entity -> Prop -> Prop.",
                    "Parameter during_T : Entity -> Prop -> Prop.",
                ]
                if time_modifiers
                else []
            ),
            *(
                [
                    "Parameter holds_state : Entity -> StateScale -> State -> Prop.",
                ]
                if requires_stative_state
                else []
            ),
            *(
                [
                    "Parameter Transition : Entity -> StateScale -> State -> State -> TransitionT.",
                    "Parameter Change : TransitionT -> Prop.",
                    "Parameter Cause : Entity -> TransitionT -> Prop.",
                    "Parameter CauseWithInstrument : Entity -> Entity -> TransitionT -> Prop.",
                ]
                if requires_state_change
                else []
            ),
            *[
                f"Parameter {connective} : {connective_type}."
                for connective, connective_type in subject_connective_types.items()
            ],
            *(["Parameter not_T : Prop -> Prop."] if has_negation else []),
            "Parameter because_T : Prop -> Prop -> Prop.",
            "",
            f"Definition {coq_definition} : Prop :=",
            f"  because_T ({coq_cause}) ({coq_effect}).",
            "",
            f"Check {coq_definition}.",
            "",
        ]
    )
    event_semantics = {
        "analysis": "causal-because",
        "source": sentence,
        "event_style_reference": (
            f"({causal_because_clause_event_reference(effect, 'e_effect')}) "
            "because "
            f"({causal_because_clause_event_reference(cause, 'e_cause')})"
        ),
        "typed_replacement": typed_replacement,
    }
    state_change_clauses = [
        clause
        for clause in (cause, effect)
        if causal_because_clause_is_state_change(clause)
    ]
    stative_state_clauses = [
        clause
        for clause in (cause, effect)
        if causal_because_clause_is_stative_state(clause)
    ]
    result_state_lexicon = []
    state_change_verb_entries = []
    seen_states: set[str] = set()
    seen_verbs: set[str] = set()
    for clause in state_change_clauses:
        target_state = clause["transition"]["target_state"]["name"]
        if target_state not in seen_states:
            result_state_lexicon.append(state_lexicon_metadata(target_state))
            seen_states.add(target_state)
        verb = clause["verb"]
        if verb not in seen_verbs:
            state_change_verb_entries.append(state_change_verb_metadata(verb))
            seen_verbs.add(verb)
    for clause in stative_state_clauses:
        for state_name in causal_because_stative_state_names(clause):
            if state_name not in seen_states:
                result_state_lexicon.append(state_lexicon_metadata(state_name))
                seen_states.add(state_name)
    result = {
        "kind": "causal_because",
        "input_sentence": sentence,
        "event_semantics": event_semantics,
        "dependent_type_translation": typed_replacement,
        "ast": ast,
        "type_check": {
            **type_check,
            "note": (
                "The because-clause is represented as a proposition-level "
                "causal connective from cause to effect; no Event, Agent, "
                "or Theme declaration is exported."
            ),
        },
        "coq_code": coq_code,
    }
    if result_state_lexicon:
        result["result_state_lexicon"] = result_state_lexicon
        result["state_change_verb_entries"] = state_change_verb_entries
    return attach_single_semantic_reading(
        result,
        name="causal_because_single_reading",
        coq_definition=coq_definition,
        source="causal_because",
        scope="cause_explains_effect",
    )


def perception_nominalization_ast(
    perception_predicate: str,
    experiencer: str,
    embedded_proposition: dict[str, Any],
) -> dict[str, Any]:
    return {
        "kind": "perception_nominalization",
        "perception": {
            "predicate": perception_predicate,
            "predicate_type": "Entity -> Entity -> Prop",
            "experiencer": {
                "name": experiencer,
                "type": "Entity",
            },
            "object": {
                "kind": "nominalized_proposition",
                "nominalizer": "E",
                "nominalizer_type": "Prop -> Entity",
                "proposition": embedded_proposition,
            },
        },
    }


def simple_perception_embedded_proposition(
    embedded_predicate: str,
    embedded_subject: str,
) -> dict[str, Any]:
    return {
        "predicate": embedded_predicate,
        "predicate_type": "Entity -> Prop",
        "subject": {
            "name": embedded_subject,
            "type": "Entity",
        },
    }


def time_modified_perception_embedded_proposition(
    body: dict[str, Any],
    *,
    operator: str,
    argument: str,
) -> dict[str, Any]:
    return {
        "kind": "time_modified_proposition",
        "operator": operator,
        "operator_name": f"{operator}_T",
        "operator_type": "Entity -> Prop -> Prop",
        "argument": {
            "name": argument,
            "type": "Entity",
        },
        "body": body,
    }


def timed_perception_embedded_proposition(
    embedded_predicate: str,
    embedded_subject: str,
    time_variable: str,
) -> dict[str, Any]:
    return {
        "predicate": embedded_predicate,
        "predicate_type": "Entity -> Time -> Prop",
        "subject": {
            "name": embedded_subject,
            "type": "Entity",
        },
        "time": time_variable,
    }


def proposition_coordination_ast(
    clauses: list[dict[str, Any]],
    connective: str = "and_T",
) -> dict[str, Any]:
    return {
        "kind": "proposition_coordination",
        "clauses": clauses,
        "connective": connective,
        "connective_type": "Prop -> Prop -> Prop",
    }


def timed_proposition_coordination_ast(
    clauses: list[dict[str, Any]],
    connective: str = "and_T",
) -> dict[str, Any]:
    return {
        "kind": "timed_proposition_coordination",
        "clauses": clauses,
        "connective": connective,
        "connective_type": "Prop -> Prop -> Prop",
    }


def timed_coordination_group_ast(
    clauses: list[dict[str, Any]],
    coordinator: str,
) -> dict[str, Any]:
    if len(clauses) == 1:
        return clauses[0]
    return timed_proposition_coordination_ast(
        clauses,
        connective_for_coordinator(coordinator),
    )


def split_boolean_coordinate_tokens(
    tokens: list[str],
) -> tuple[list[list[str]], list[str]] | None:
    if not tokens or tokens[0] in BOOLEAN_COORDINATORS or tokens[-1] in BOOLEAN_COORDINATORS:
        return None
    groups: list[list[str]] = [[]]
    coordinators: list[str] = []
    for token in tokens:
        if token in BOOLEAN_COORDINATORS:
            if not groups[-1]:
                return None
            coordinators.append(token)
            groups.append([])
            continue
        groups[-1].append(token)
    if not coordinators or any(not group for group in groups):
        return None
    return groups, coordinators


def fold_timed_boolean_coordination_with_precedence(
    clauses: list[dict[str, Any]],
    coordinators: list[str],
    *,
    tight_coordinator: str,
) -> dict[str, Any] | None:
    if len(clauses) != len(coordinators) + 1:
        return None
    if tight_coordinator not in BOOLEAN_COORDINATORS:
        return None
    loose_coordinator = "or" if tight_coordinator == "and" else "and"
    loose_terms: list[dict[str, Any]] = []
    current_tight_terms = [clauses[0]]
    for coordinator, clause in zip(coordinators, clauses[1:]):
        if coordinator == tight_coordinator:
            current_tight_terms.append(clause)
            continue
        loose_terms.append(
            timed_coordination_group_ast(current_tight_terms, tight_coordinator)
        )
        current_tight_terms = [clause]
    loose_terms.append(
        timed_coordination_group_ast(current_tight_terms, tight_coordinator)
    )
    return timed_coordination_group_ast(loose_terms, loose_coordinator)


def fold_mixed_timed_boolean_coordination(
    clauses: list[dict[str, Any]],
    coordinators: list[str],
) -> dict[str, Any] | None:
    primary = fold_timed_boolean_coordination_with_precedence(
        clauses,
        coordinators,
        tight_coordinator="and",
    )
    if primary is None:
        return None
    if len(set(coordinators)) > 1:
        alternative = fold_timed_boolean_coordination_with_precedence(
            copy.deepcopy(clauses),
            coordinators,
            tight_coordinator="or",
        )
        if alternative is not None:
            primary["coordination_scope"] = {
                "primary_policy": "and_before_or",
                "alternative_policy": "or_before_and",
                "coordinators": [
                    connective_for_coordinator(coordinator)
                    for coordinator in coordinators
                ],
                "alternative_ast": alternative,
            }
    return primary


def temporal_relation_arguments(
    relation_surface: str,
    main_time: str,
    reference_time: str,
) -> list[str]:
    return (
        [reference_time, main_time]
        if relation_surface == "after"
        else [main_time, reference_time]
    )


def perception_timed_proposition_times(proposition: dict[str, Any]) -> list[str]:
    if proposition.get("kind") == "timed_proposition_coordination":
        clauses = proposition.get("clauses")
        if not isinstance(clauses, list):
            return []
        times: list[str] = []
        for clause in clauses:
            if isinstance(clause, dict):
                times.extend(perception_timed_proposition_times(clause))
        return times
    time_variable = proposition.get("time")
    return [time_variable] if isinstance(time_variable, str) else []


def perception_timed_proposition_leaf_clauses(
    proposition: dict[str, Any],
) -> list[dict[str, Any]]:
    if proposition.get("kind") == "timed_proposition_coordination":
        leaves: list[dict[str, Any]] = []
        clauses = proposition.get("clauses")
        if not isinstance(clauses, list):
            return leaves
        for clause in clauses:
            if isinstance(clause, dict):
                leaves.extend(perception_timed_proposition_leaf_clauses(clause))
        return leaves
    return [proposition]


def base_temporal_relation_proposition_ast(
    main_clause: dict[str, Any],
    reference_clause: dict[str, Any],
    relation_surface: str,
) -> dict[str, Any]:
    main_times = perception_timed_proposition_times(main_clause)
    reference_times = perception_timed_proposition_times(reference_clause)
    relations = [
        {
            "predicate": "before",
            "predicate_type": "Time -> Time -> Prop",
            "arguments": temporal_relation_arguments(
                relation_surface,
                main_time,
                reference_time,
            ),
        }
        for main_time in main_times
        for reference_time in reference_times
    ]
    ast = {
        "kind": "temporal_relation",
        "relation_surface": relation_surface,
        "binders": [
            *[{"variable": time_variable, "type": "Time"} for time_variable in main_times],
            *[{"variable": time_variable, "type": "Time"} for time_variable in reference_times],
        ],
        "main": main_clause,
        "reference": reference_clause,
    }
    if len(relations) == 1:
        ast["relation"] = relations[0]
    else:
        ast["relations"] = relations
    return ast


def timed_proposition_scope_variants(
    proposition: dict[str, Any],
) -> list[dict[str, Any]]:
    variants = [
        {
            "policy": "and_before_or",
            "is_primary": True,
            "proposition": proposition,
        }
    ]
    scope = proposition.get("coordination_scope")
    if isinstance(scope, dict) and isinstance(scope.get("alternative_ast"), dict):
        variants.append(
            {
                "policy": str(scope.get("alternative_policy", "or_before_and")),
                "is_primary": False,
                "proposition": scope["alternative_ast"],
            }
        )
    return variants


def temporal_relation_alternative_scope_readings(
    proposition: dict[str, Any],
) -> list[dict[str, Any]]:
    relation_surface = proposition.get("relation_surface")
    if relation_surface not in TEMPORAL_RELATION_CONNECTORS:
        return []
    alternatives: list[dict[str, Any]] = []
    main_variants = timed_proposition_scope_variants(proposition["main"])
    reference_variants = timed_proposition_scope_variants(proposition["reference"])
    for main_variant in main_variants:
        for reference_variant in reference_variants:
            if main_variant["is_primary"] and reference_variant["is_primary"]:
                continue
            alt_ast = base_temporal_relation_proposition_ast(
                main_variant["proposition"],
                reference_variant["proposition"],
                str(relation_surface),
            )
            errors: list[str] = []
            check_perception_embedded_proposition(alt_ast, errors)
            changed_sides = [
                side
                for side, variant in (
                    ("main", main_variant),
                    ("reference", reference_variant),
                )
                if not variant["is_primary"]
            ]
            name = "or_before_and_" + "_".join(changed_sides)
            alternatives.append(
                {
                    "name": name,
                    "scope_policy": {
                        "main": main_variant["policy"],
                        "reference": reference_variant["policy"],
                    },
                    "dependent_type_translation": (
                        render_perception_embedded_translation(alt_ast)
                    ),
                    "ast": alt_ast,
                    "branch_count": (
                        len(timed_disjunction_branch_options(alt_ast["main"]))
                        * len(timed_disjunction_branch_options(alt_ast["reference"]))
                    ),
                    "type_check": {
                        "ok": not errors,
                        "type": "Prop" if not errors else None,
                        "errors": errors,
                    },
                }
            )
    return alternatives


def temporal_relation_proposition_ast(
    main_clause: dict[str, Any],
    reference_clause: dict[str, Any],
    relation_surface: str,
) -> dict[str, Any]:
    ast = base_temporal_relation_proposition_ast(
        main_clause,
        reference_clause,
        relation_surface,
    )
    alternatives = temporal_relation_alternative_scope_readings(ast)
    if alternatives:
        ast["alternative_scope_readings"] = alternatives
    return ast


def unsupported_mixed_temporal_perception_coordination(
    sentence: str,
    embedded_tokens: list[str],
) -> dict[str, Any]:
    return {
        "kind": "perception_nominalization",
        "input_sentence": sentence,
        "construction_summary": (
            "A perception complement with a temporal relation and mixed boolean "
            "coordination was detected, but it falls outside the current "
            "and-before-or timed-proposition policy."
        ),
        "event_semantics": {
            "analysis": "perception-temporal-mixed-coordination-boundary",
            "source": sentence,
            "event_style_reference": (
                "exists e. Seeing(e) and Experiencer(e, Mary) and "
                "Theme(e, mixed boolean temporal proposition)"
            ),
        },
        "dependent_type_translation": "",
        "ast": {
            "kind": "perception_nominalization",
            "unsupported": "mixed_temporal_perception_coordination",
            "embedded_tokens": embedded_tokens,
            "connectives": [
                BOOLEAN_COORDINATORS[token]
                for token in embedded_tokens
                if token in BOOLEAN_COORDINATORS
            ],
        },
        "type_check": {
            "ok": False,
            "type": None,
            "errors": [
                (
                    "mixed timed perception coordination is malformed or outside "
                    "the explicit and-before-or reading policy; refusing to treat "
                    "temporal material as an Entity"
                )
            ],
            "note": (
                "The parser recognized after/before inside a perception complement "
                "together with mixed boolean coordination, but could not build a typed "
                "timed proposition under the current precedence policy."
            ),
        },
        "coq_code": "",
    }


def perception_entity_name(tokens: list[str]) -> str:
    cleaned = clean_phrase(tokens)
    return "_".join(part.capitalize() for part in cleaned.split("_"))


def is_perception_embedded_intransitive_surface(token: str) -> bool:
    return is_likely_surface_verb(token) and not is_likely_transitive_verb(token)


def parse_simple_perception_embedded_clause(
    tokens: list[str],
) -> dict[str, Any] | None:
    if len(tokens) < 2:
        return None
    if any(
        token in BOOLEAN_COORDINATORS
        or token in TEMPORAL_RELATION_CONNECTORS
        or token == "both"
        for token in tokens
    ):
        return None
    embedded_surface = tokens[-1]
    if not is_perception_embedded_intransitive_surface(embedded_surface):
        return None
    embedded_subject = perception_entity_name(tokens[:-1])
    if embedded_subject == "Entity":
        return None
    return simple_perception_embedded_proposition(
        lemma_verb(embedded_surface),
        embedded_subject,
    )


def parse_time_modified_perception_embedded_proposition(
    tokens: list[str],
) -> dict[str, Any] | None:
    if len(tokens) < 3 or tokens[-1] not in TEMPORAL_ADVERBS:
        return None
    body = parse_simple_perception_embedded_clause(tokens[:-1])
    if body is None:
        return None
    return time_modified_perception_embedded_proposition(
        body,
        operator="at",
        argument=tokens[-1],
    )


def parse_timed_perception_embedded_clause(
    tokens: list[str],
    time_variable: str,
) -> dict[str, Any] | None:
    if len(tokens) < 2:
        return None
    if any(
        token in BOOLEAN_COORDINATORS
        or token in TEMPORAL_RELATION_CONNECTORS
        or token == "both"
        for token in tokens
    ):
        return None
    embedded_surface = tokens[-1]
    if not is_perception_embedded_intransitive_surface(embedded_surface):
        return None
    embedded_subject = perception_entity_name(tokens[:-1])
    if embedded_subject == "Entity":
        return None
    return timed_perception_embedded_proposition(
        lemma_verb(embedded_surface),
        embedded_subject,
        time_variable,
    )


def parse_timed_perception_side(
    tokens: list[str],
    *,
    simple_time: str,
    coordination_time_prefix: str,
) -> dict[str, Any] | None:
    simple_clause = parse_timed_perception_embedded_clause(tokens, simple_time)
    if simple_clause is not None:
        return simple_clause

    coordination = split_boolean_coordinate_tokens(tokens)
    if coordination is None:
        return None
    groups, coordinators = coordination
    clauses: list[dict[str, Any]] = []
    for index, group in enumerate(groups, start=1):
        clause = parse_timed_perception_embedded_clause(
            group,
            f"{coordination_time_prefix}_{index}",
        )
        if clause is None:
            return None
        clauses.append(clause)
    return fold_mixed_timed_boolean_coordination(clauses, coordinators)


def parse_timed_perception_main(tokens: list[str]) -> dict[str, Any] | None:
    return parse_timed_perception_side(
        tokens,
        simple_time="t_main",
        coordination_time_prefix="t_main",
    )


def parse_timed_perception_reference(tokens: list[str]) -> dict[str, Any] | None:
    return parse_timed_perception_side(
        tokens,
        simple_time="t_reference",
        coordination_time_prefix="t_reference",
    )


def parse_temporal_perception_embedded_proposition(
    tokens: list[str],
) -> dict[str, Any] | None:
    relation = single_temporal_relation_connector(tokens)
    if relation is None:
        return None
    relation_surface, relation_index = relation
    main_tokens = tokens[:relation_index]
    reference_tokens = tokens[relation_index + 1 :]
    if not main_tokens or not reference_tokens:
        return None
    main_clause = parse_timed_perception_main(main_tokens)
    reference_clause = parse_timed_perception_reference(reference_tokens)
    if main_clause is None or reference_clause is None:
        return None
    return temporal_relation_proposition_ast(
        main_clause,
        reference_clause,
        relation_surface,
    )


def perception_clause_definition_suffix(clause: dict[str, Any]) -> str:
    return f"{clause['subject']['name'].lower()}_{clause['predicate']}"


def perception_embedded_definition_suffix(proposition: dict[str, Any]) -> str:
    if proposition.get("kind") == "time_modified_proposition":
        argument = proposition["argument"]["name"]
        return (
            f"{perception_embedded_definition_suffix(proposition['body'])}_"
            f"{proposition['operator']}_{argument}"
        )
    if proposition.get("kind") == "subject_coordination":
        subjects = [subject["name"].lower() for subject in proposition["subjects"]]
        connective = str(proposition["connective"]).replace("_T", "")
        return f"{subjects[0]}_{connective}_{subjects[1]}_{proposition['predicate']['name']}"
    if proposition.get("kind") in {
        "proposition_coordination",
        "timed_proposition_coordination",
    }:
        connective = str(proposition["connective"]).replace("_T", "")
        return f"_{connective}_".join(
            perception_embedded_definition_suffix(clause)
            for clause in proposition["clauses"]
        )
    if proposition.get("kind") == "temporal_relation":
        return (
            f"{perception_embedded_definition_suffix(proposition['main'])}_"
            f"{proposition['relation_surface']}_"
            f"{perception_embedded_definition_suffix(proposition['reference'])}"
        )
    return perception_clause_definition_suffix(proposition)


def render_perception_timed_clause_translation(clause: dict[str, Any]) -> str:
    return f"{clause['predicate']}({clause['subject']['name']}, {clause['time']})"


def render_binary_connective_translation(connective: str, arguments: list[str]) -> str:
    rendered = arguments[-1]
    for argument in reversed(arguments[:-1]):
        rendered = f"{connective}({argument}, {rendered})"
    return rendered


def render_perception_timed_proposition_translation(
    proposition: dict[str, Any],
) -> str:
    if proposition.get("kind") == "timed_proposition_coordination":
        return render_binary_connective_translation(
            proposition["connective"],
            [
                render_perception_timed_proposition_translation(clause)
                for clause in proposition["clauses"]
            ],
        )
    return render_perception_timed_clause_translation(proposition)


def render_perception_temporal_relations_translation(
    proposition: dict[str, Any],
) -> str:
    if proposition.get("relations") is not None:
        return " and ".join(
            f"before({relation['arguments'][0]}, {relation['arguments'][1]})"
            for relation in proposition["relations"]
        )
    relation = proposition["relation"]
    return f"before({relation['arguments'][0]}, {relation['arguments'][1]})"


def timed_disjunction_branch_options(
    proposition: dict[str, Any],
) -> list[dict[str, Any]]:
    if proposition.get("kind") != "timed_proposition_coordination":
        return [proposition]
    clauses = proposition.get("clauses")
    if not isinstance(clauses, list) or not clauses:
        return [proposition]
    if proposition.get("connective") == "or_T":
        branches: list[dict[str, Any]] = []
        for clause in clauses:
            if isinstance(clause, dict):
                branches.extend(timed_disjunction_branch_options(clause))
        return branches
    if proposition.get("connective") == "and_T":
        branch_groups: list[list[dict[str, Any]]] = [[]]
        for clause in clauses:
            if not isinstance(clause, dict):
                return [proposition]
            clause_options = timed_disjunction_branch_options(clause)
            branch_groups = [
                [*branch_group, option]
                for branch_group in branch_groups
                for option in clause_options
            ]
        return [
            timed_coordination_group_ast(branch_group, "and")
            for branch_group in branch_groups
        ]
    return [proposition]


def timed_proposition_has_disjunction(proposition: dict[str, Any]) -> bool:
    if proposition.get("kind") != "timed_proposition_coordination":
        return False
    if proposition.get("connective") == "or_T":
        return True
    clauses = proposition.get("clauses")
    return isinstance(clauses, list) and any(
        isinstance(clause, dict) and timed_proposition_has_disjunction(clause)
        for clause in clauses
    )


def temporal_relation_has_timed_disjunction(proposition: dict[str, Any]) -> bool:
    return any(
        timed_proposition_has_disjunction(side)
        for side in (proposition["main"], proposition["reference"])
    )


def render_temporal_relation_branch_translation(
    main: dict[str, Any],
    reference: dict[str, Any],
    relation_surface: str,
) -> str:
    time_variables = [
        *perception_timed_proposition_times(main),
        *perception_timed_proposition_times(reference),
    ]
    relation_text = " and ".join(
        f"before({arguments[0]}, {arguments[1]})"
        for arguments in expected_temporal_relation_arguments(
            main,
            reference,
            relation_surface,
        )
    )
    return (
        f"exists {' '.join(time_variables)} : Time. "
        f"{render_perception_timed_proposition_translation(main)} and "
        f"{render_perception_timed_proposition_translation(reference)} and "
        f"{relation_text}"
    )


def render_disjunctive_temporal_relation_translation(proposition: dict[str, Any]) -> str:
    branches = [
        render_temporal_relation_branch_translation(
            main,
            reference,
            proposition["relation_surface"],
        )
        for main in timed_disjunction_branch_options(proposition["main"])
        for reference in timed_disjunction_branch_options(proposition["reference"])
    ]
    return render_binary_connective_translation("or_T", branches)


def render_perception_embedded_translation(proposition: dict[str, Any]) -> str:
    if proposition.get("kind") == "time_modified_proposition":
        return (
            f"{proposition['operator_name']}("
            f"{proposition['argument']['name']}, "
            f"{render_perception_embedded_translation(proposition['body'])})"
        )
    if proposition.get("kind") == "subject_coordination":
        return render_subject_coordination_translation(proposition)
    if proposition.get("kind") == "proposition_coordination":
        left, right = proposition["clauses"]
        return (
            f"{proposition['connective']}("
            f"{render_perception_embedded_translation(left)}, "
            f"{render_perception_embedded_translation(right)})"
        )
    if proposition.get("kind") == "temporal_relation":
        main = proposition["main"]
        reference = proposition["reference"]
        if temporal_relation_has_timed_disjunction(proposition):
            return render_disjunctive_temporal_relation_translation(proposition)
        return (
            f"exists {' '.join(binder['variable'] for binder in proposition['binders'])} : Time. "
            f"{render_perception_timed_proposition_translation(main)} and "
            f"{render_perception_timed_proposition_translation(reference)} and "
            f"{render_perception_temporal_relations_translation(proposition)}"
        )
    return f"{proposition['predicate']}({proposition['subject']['name']})"


def render_perception_timed_clause_coq(clause: dict[str, Any]) -> str:
    return f"{clause['predicate']} {clause['subject']['name']} {clause['time']}"


def render_binary_connective_coq(connective: str, arguments: list[str]) -> str:
    rendered = arguments[-1]
    for argument in reversed(arguments[:-1]):
        rendered = f"{connective} ({argument}) ({rendered})"
    return rendered


def render_perception_timed_proposition_coq(proposition: dict[str, Any]) -> str:
    if proposition.get("kind") == "timed_proposition_coordination":
        return render_binary_connective_coq(
            proposition["connective"],
            [
                render_perception_timed_proposition_coq(clause)
                for clause in proposition["clauses"]
            ],
        )
    return render_perception_timed_clause_coq(proposition)


def render_perception_temporal_relations_coq(proposition: dict[str, Any]) -> str:
    if proposition.get("relations") is not None:
        return " /\\\n".join(
            f"    before {relation['arguments'][0]} {relation['arguments'][1]}"
            for relation in proposition["relations"]
        )
    relation = proposition["relation"]
    return f"    before {relation['arguments'][0]} {relation['arguments'][1]}"


def render_temporal_relation_branch_coq(
    main: dict[str, Any],
    reference: dict[str, Any],
    relation_surface: str,
) -> str:
    time_variables = [
        *perception_timed_proposition_times(main),
        *perception_timed_proposition_times(reference),
    ]
    quantifiers = "".join(
        f"exists {time_variable} : Time,\n  "
        for time_variable in time_variables
    )
    relation_text = " /\\\n".join(
        f"    before {arguments[0]} {arguments[1]}"
        for arguments in expected_temporal_relation_arguments(
            main,
            reference,
            relation_surface,
        )
    )
    return (
        quantifiers
        + f"  {render_perception_timed_proposition_coq(main)} /\\\n"
        + f"    {render_perception_timed_proposition_coq(reference)} /\\\n"
        + relation_text
    )


def render_disjunctive_temporal_relation_coq(proposition: dict[str, Any]) -> str:
    branches = [
        render_temporal_relation_branch_coq(
            main,
            reference,
            proposition["relation_surface"],
        )
        for main in timed_disjunction_branch_options(proposition["main"])
        for reference in timed_disjunction_branch_options(proposition["reference"])
    ]
    return render_binary_connective_coq("or_T", branches)


def render_perception_embedded_coq(proposition: dict[str, Any]) -> str:
    if proposition.get("kind") == "time_modified_proposition":
        return (
            f"{proposition['operator_name']} {proposition['argument']['name']} "
            f"({render_perception_embedded_coq(proposition['body'])})"
        )
    if proposition.get("kind") == "subject_coordination":
        predicate = proposition["predicate"]["name"]
        subjects = [subject["name"] for subject in proposition["subjects"]]
        return (
            f"{proposition['connective']} "
            f"({predicate} {subjects[0]}) ({predicate} {subjects[1]})"
        )
    if proposition.get("kind") == "proposition_coordination":
        left, right = proposition["clauses"]
        return (
            f"{proposition['connective']} "
            f"({render_perception_embedded_coq(left)}) "
            f"({render_perception_embedded_coq(right)})"
        )
    if proposition.get("kind") == "temporal_relation":
        main = proposition["main"]
        reference = proposition["reference"]
        if temporal_relation_has_timed_disjunction(proposition):
            return render_disjunctive_temporal_relation_coq(proposition)
        quantifiers = "".join(
            f"exists {binder['variable']} : Time,\n  "
            for binder in proposition["binders"]
        )
        return (
            quantifiers
            + f"  {render_perception_timed_proposition_coq(main)} /\\\n"
            + f"    {render_perception_timed_proposition_coq(reference)} /\\\n"
            + render_perception_temporal_relations_coq(proposition)
        )
    return f"{proposition['predicate']} {proposition['subject']['name']}"


def perception_embedded_subjects(proposition: dict[str, Any]) -> list[str]:
    if proposition.get("kind") == "time_modified_proposition":
        return perception_embedded_subjects(proposition["body"])
    if proposition.get("kind") == "subject_coordination":
        return [subject["name"] for subject in proposition["subjects"]]
    if proposition.get("kind") in {
        "proposition_coordination",
        "timed_proposition_coordination",
    }:
        subjects: list[str] = []
        for clause in proposition["clauses"]:
            subjects.extend(perception_embedded_subjects(clause))
        return subjects
    if proposition.get("kind") == "temporal_relation":
        return (
            perception_embedded_subjects(proposition["main"])
            + perception_embedded_subjects(proposition["reference"])
        )
    return [proposition["subject"]["name"]]


def perception_embedded_predicate_declarations(
    proposition: dict[str, Any],
) -> list[tuple[str, str]]:
    if proposition.get("kind") == "time_modified_proposition":
        return perception_embedded_predicate_declarations(proposition["body"])
    if proposition.get("kind") == "subject_coordination":
        return [(proposition["predicate"]["name"], "Entity -> Prop")]
    if proposition.get("kind") == "proposition_coordination":
        declarations: list[tuple[str, str]] = []
        for clause in proposition["clauses"]:
            declarations.extend(perception_embedded_predicate_declarations(clause))
        return declarations
    if proposition.get("kind") == "timed_proposition_coordination":
        declarations = []
        for clause in proposition["clauses"]:
            declarations.extend(perception_embedded_predicate_declarations(clause))
        return declarations
    if proposition.get("kind") == "temporal_relation":
        return [
            *perception_embedded_predicate_declarations(proposition["main"]),
            *perception_embedded_predicate_declarations(proposition["reference"]),
        ]
    predicate_type = proposition.get("predicate_type", "Entity -> Prop")
    return [(proposition["predicate"], predicate_type)]


def perception_embedded_connectives(proposition: dict[str, Any]) -> list[str]:
    if proposition.get("kind") == "time_modified_proposition":
        return perception_embedded_connectives(proposition["body"])
    if proposition.get("kind") == "subject_coordination":
        return [proposition["connective"]]
    if proposition.get("kind") in {
        "proposition_coordination",
        "timed_proposition_coordination",
    }:
        connectives = [proposition["connective"]]
        for clause in proposition["clauses"]:
            connectives.extend(perception_embedded_connectives(clause))
        return connectives
    if proposition.get("kind") == "temporal_relation":
        return (
            perception_embedded_connectives(proposition["main"])
            + perception_embedded_connectives(proposition["reference"])
        )
    return []


def perception_embedded_uses_time(proposition: dict[str, Any]) -> bool:
    if proposition.get("kind") == "time_modified_proposition":
        return perception_embedded_uses_time(proposition["body"])
    if proposition.get("kind") == "temporal_relation":
        return True
    if proposition.get("kind") == "proposition_coordination":
        return any(perception_embedded_uses_time(clause) for clause in proposition["clauses"])
    return False


def perception_embedded_time_arguments(proposition: dict[str, Any]) -> list[str]:
    if proposition.get("kind") == "time_modified_proposition":
        return [
            proposition["argument"]["name"],
            *perception_embedded_time_arguments(proposition["body"]),
        ]
    if proposition.get("kind") in {
        "subject_coordination",
        "proposition_coordination",
        "timed_proposition_coordination",
    }:
        arguments: list[str] = []
        for clause in proposition.get("clauses", []):
            if isinstance(clause, dict):
                arguments.extend(perception_embedded_time_arguments(clause))
        return arguments
    if proposition.get("kind") == "temporal_relation":
        return (
            perception_embedded_time_arguments(proposition["main"])
            + perception_embedded_time_arguments(proposition["reference"])
        )
    return []


def perception_embedded_time_operators(proposition: dict[str, Any]) -> list[str]:
    if proposition.get("kind") == "time_modified_proposition":
        return [
            proposition["operator_name"],
            *perception_embedded_time_operators(proposition["body"]),
        ]
    if proposition.get("kind") in {
        "subject_coordination",
        "proposition_coordination",
        "timed_proposition_coordination",
    }:
        operators: list[str] = []
        for clause in proposition.get("clauses", []):
            if isinstance(clause, dict):
                operators.extend(perception_embedded_time_operators(clause))
        return operators
    if proposition.get("kind") == "temporal_relation":
        return (
            perception_embedded_time_operators(proposition["main"])
            + perception_embedded_time_operators(proposition["reference"])
        )
    return []


def perception_time_attachment_summary(
    *,
    kind: str,
    proposition: dict[str, Any],
    target: str,
) -> dict[str, Any]:
    summary = empty_attachment_summary(kind)
    summary["typed_time_modifiers"] = [
        {
            "name": proposition["argument"]["name"],
            "type": proposition["argument"]["type"],
            "operator": proposition["operator_name"],
            "operator_type": proposition["operator_type"],
            "target": target,
        }
    ]
    return summary


def check_timed_perception_clause(
    clause: dict[str, Any],
    expected_time: str,
    label: str,
    errors: list[str],
) -> None:
    if clause.get("predicate_type") != "Entity -> Time -> Prop":
        errors.append(
            f"embedded temporal relation {label} predicate must have type Entity -> Time -> Prop"
        )
    subject = clause.get("subject")
    if not isinstance(subject, dict) or subject.get("type") != "Entity":
        errors.append(f"embedded temporal relation {label} subject must have type Entity")
    if clause.get("time") != expected_time:
        errors.append(
            f"embedded temporal relation {label} must use bound time {expected_time}"
        )


def check_timed_side_proposition(
    proposition: dict[str, Any],
    *,
    simple_time: str,
    coordination_time_prefix: str,
    label: str,
    errors: list[str],
) -> None:
    if proposition.get("kind") == "timed_proposition_coordination":
        if proposition.get("connective") not in {"and_T", "or_T"}:
            errors.append(f"embedded timed {label} coordination connective must be and_T or or_T")
        if proposition.get("connective_type") != "Prop -> Prop -> Prop":
            errors.append(
                f"embedded timed {label} coordination connective must have type Prop -> Prop -> Prop"
            )
        if not isinstance(proposition.get("clauses"), list) or len(proposition["clauses"]) < 2:
            errors.append(f"embedded timed {label} coordination must contain at least two clauses")
            return
        leaves = perception_timed_proposition_leaf_clauses(proposition)
        if len(leaves) < 2:
            errors.append(f"embedded timed {label} coordination must contain at least two leaf clauses")
            return
        for index, clause in enumerate(leaves, start=1):
            check_timed_perception_clause(
                clause,
                f"{coordination_time_prefix}_{index}",
                f"{label} leaf[{index - 1}]",
                errors,
            )
        return

    check_timed_perception_clause(proposition, simple_time, label, errors)


def expected_temporal_relation_arguments(
    main: dict[str, Any],
    reference: dict[str, Any],
    relation_surface: str,
) -> list[list[str]]:
    return [
        temporal_relation_arguments(relation_surface, main_time, reference_time)
        for main_time in perception_timed_proposition_times(main)
        for reference_time in perception_timed_proposition_times(reference)
    ]


def temporal_relation_count_error(
    main_times: list[str],
    reference_times: list[str],
) -> str:
    if len(main_times) == 1 and len(reference_times) > 1:
        return "embedded timed reference coordination must contain one before relation per clause"
    if len(main_times) > 1 and len(reference_times) == 1:
        return "embedded timed main coordination must contain one before relation per clause"
    return "embedded temporal relation must contain one before relation per main/reference time pair"


def check_temporal_relation_node(
    relation: Any,
    expected_arguments: list[str],
    relation_surface: str,
    errors: list[str],
) -> None:
    if not isinstance(relation, dict):
        errors.append("embedded temporal relation relation must be an object")
        return
    if relation.get("predicate") != "before":
        errors.append("embedded temporal relation predicate must be before")
    if relation.get("predicate_type") != "Time -> Time -> Prop":
        errors.append("embedded before relation must have type Time -> Time -> Prop")
    if relation.get("arguments") != expected_arguments:
        errors.append(
            f"embedded {relation_surface} relation has the wrong before-argument order"
        )


def check_perception_embedded_proposition(
    proposition: dict[str, Any],
    errors: list[str],
) -> None:
    if proposition.get("kind") == "time_modified_proposition":
        if proposition.get("operator") not in {"at", "during"}:
            errors.append("embedded time-modified proposition operator must be at or during")
        if proposition.get("operator_name") != f"{proposition.get('operator')}_T":
            errors.append("embedded time-modified proposition operator_name must match operator")
        if proposition.get("operator_type") != "Entity -> Prop -> Prop":
            errors.append(
                "embedded time-modified proposition operator must have type Entity -> Prop -> Prop"
            )
        argument = proposition.get("argument")
        if not isinstance(argument, dict) or argument.get("type") != "Entity":
            errors.append("embedded time-modified proposition argument must have type Entity")
        body = proposition.get("body")
        if not isinstance(body, dict):
            errors.append("embedded time-modified proposition body must be a proposition")
            return
        check_perception_embedded_proposition(body, errors)
        return

    if proposition.get("kind") == "subject_coordination":
        if proposition.get("modifiers") != []:
            errors.append(
                "perception embedded subject coordination currently requires no shared modifiers"
            )
        if proposition.get("time_modifiers") != []:
            errors.append(
                "perception embedded subject coordination currently requires no time modifiers"
            )
        type_check = check_subject_coordination_ast(proposition)
        errors.extend(
            f"embedded subject coordination: {error}"
            for error in type_check["errors"]
        )
        return

    if proposition.get("kind") == "proposition_coordination":
        if proposition.get("connective") not in {"and_T", "or_T"}:
            errors.append("embedded proposition coordination connective must be and_T or or_T")
        if proposition.get("connective_type") != "Prop -> Prop -> Prop":
            errors.append(
                "embedded proposition coordination connective must have type Prop -> Prop -> Prop"
            )
        clauses = proposition.get("clauses")
        if not isinstance(clauses, list) or len(clauses) != 2:
            errors.append("embedded proposition coordination must contain exactly two clauses")
            return
        for clause in clauses:
            check_perception_embedded_proposition(clause, errors)
        return

    if proposition.get("kind") == "temporal_relation":
        relation_surface = proposition.get("relation_surface")
        if relation_surface not in TEMPORAL_RELATION_CONNECTORS:
            errors.append("embedded temporal relation must be after or before")
        main = proposition.get("main")
        if not isinstance(main, dict):
            errors.append("embedded temporal relation main must be an object")
            main_times: list[str] = []
        else:
            main_times = perception_timed_proposition_times(main)
            check_timed_side_proposition(
                main,
                simple_time="t_main",
                coordination_time_prefix="t_main",
                label="main",
                errors=errors,
            )
        reference = proposition.get("reference")
        if not isinstance(reference, dict):
            errors.append("embedded temporal relation reference must be an object")
            reference_times = []
        else:
            reference_times = perception_timed_proposition_times(reference)
            check_timed_side_proposition(
                reference,
                simple_time="t_reference",
                coordination_time_prefix="t_reference",
                label="reference",
                errors=errors,
            )
        expected_binders = [
            *[
                {"variable": time_variable, "type": "Time"}
                for time_variable in main_times
            ],
            *[
                {"variable": time_variable, "type": "Time"}
                for time_variable in reference_times
            ],
        ]
        if proposition.get("binders") != expected_binders:
            errors.append(
                "embedded temporal relation must bind its main and reference times as Time"
            )
        if not isinstance(main, dict) or not isinstance(reference, dict):
            return
        if relation_surface not in TEMPORAL_RELATION_CONNECTORS:
            return
        expected_arguments = expected_temporal_relation_arguments(
            main,
            reference,
            str(relation_surface),
        )
        if len(expected_arguments) == 1:
            if proposition.get("relations") is not None:
                errors.append(
                    "embedded simple temporal relation must use relation, not relations"
                )
            check_temporal_relation_node(
                proposition.get("relation"),
                expected_arguments[0],
                str(relation_surface),
                errors,
            )
            return

        if proposition.get("relation") is not None:
            errors.append(
                "embedded timed coordination must use relations, not a single relation"
            )
        relations = proposition.get("relations")
        if not isinstance(relations, list) or len(relations) != len(expected_arguments):
            errors.append(temporal_relation_count_error(main_times, reference_times))
            return
        for relation, expected_relation_arguments in zip(relations, expected_arguments):
            check_temporal_relation_node(
                relation,
                expected_relation_arguments,
                str(relation_surface),
                errors,
            )
        return

    if proposition.get("kind") == "timed_proposition_coordination":
        if proposition.get("connective") not in {"and_T", "or_T"}:
            errors.append("embedded timed proposition coordination connective must be and_T or or_T")
        if proposition.get("connective_type") != "Prop -> Prop -> Prop":
            errors.append(
                "embedded timed proposition coordination connective must have type Prop -> Prop -> Prop"
            )
        if not isinstance(proposition.get("clauses"), list) or len(proposition["clauses"]) < 2:
            errors.append("embedded timed proposition coordination must contain at least two clauses")
            return
        leaves = perception_timed_proposition_leaf_clauses(proposition)
        if len(leaves) < 2:
            errors.append("embedded timed proposition coordination must contain at least two leaf clauses")
            return
        for index, clause in enumerate(leaves, start=1):
            check_timed_perception_clause(
                clause,
                f"t_reference_{index}",
                f"timed leaf[{index - 1}]",
                errors,
            )
        return

    if proposition.get("predicate_type") != "Entity -> Prop":
        errors.append("embedded predicate must have type Entity -> Prop")
    subject = proposition.get("subject")
    if not isinstance(subject, dict) or subject.get("type") != "Entity":
        errors.append("embedded subject must have type Entity")


def check_perception_nominalization_ast(ast: dict[str, Any]) -> dict[str, Any]:
    errors: list[str] = []
    perception = ast.get("perception")
    if ast.get("kind") != "perception_nominalization":
        errors.append("ast.kind must be perception_nominalization")
    if not isinstance(perception, dict):
        errors.append("ast.perception must be an object")
    else:
        if perception.get("predicate_type") != "Entity -> Entity -> Prop":
            errors.append("perception predicate must have type Entity -> Entity -> Prop")
        experiencer = perception.get("experiencer")
        if not isinstance(experiencer, dict) or experiencer.get("type") != "Entity":
            errors.append("perception.experiencer must have type Entity")

        obj = perception.get("object")
        if not isinstance(obj, dict):
            errors.append("perception.object must be a nominalized proposition")
        else:
            if obj.get("kind") != "nominalized_proposition":
                errors.append("perception.object.kind must be nominalized_proposition")
            if obj.get("nominalizer_type") != "Prop -> Entity":
                errors.append("nominalizer E must have type Prop -> Entity")
            proposition = obj.get("proposition")
            if not isinstance(proposition, dict):
                errors.append("nominalized object must contain a proposition")
            else:
                check_perception_embedded_proposition(proposition, errors)

    return {
        "ok": not errors,
        "type": "Prop" if not errors else None,
        "errors": errors,
    }


def perception_nominalization_pipeline(sentence: str) -> dict[str, Any] | None:
    tokens = tokenize(sentence)
    if len(tokens) < 4 or tokens[0] != "mary" or tokens[1] != "saw":
        return None

    experiencer = "Mary"
    perception_predicate = lemma_verb(tokens[1])
    embedded_tokens = tokens[2:]
    embedded_proposition: dict[str, Any] | None = None

    time_modified = parse_time_modified_perception_embedded_proposition(embedded_tokens)
    if time_modified is not None:
        embedded_proposition = time_modified
    else:
        simple_clause = parse_simple_perception_embedded_clause(embedded_tokens)
        if simple_clause is not None:
            embedded_proposition = simple_clause
        else:
            temporal_relation = parse_temporal_perception_embedded_proposition(
                embedded_tokens,
            )
            if temporal_relation is not None:
                embedded_proposition = temporal_relation

    if embedded_proposition is None:
        if (
            "or" in embedded_tokens
            and any(token in TEMPORAL_RELATION_CONNECTORS for token in embedded_tokens)
        ):
            return unsupported_mixed_temporal_perception_coordination(sentence, embedded_tokens)
        leading_both = bool(embedded_tokens and embedded_tokens[0] == "both")
        if leading_both:
            embedded_tokens = embedded_tokens[1:]
        coordination = single_boolean_coordinator(embedded_tokens)
        if coordination is None:
            return None
        coordinator, coordinator_index = coordination
        if leading_both and coordinator != "and":
            return None
        left_subject_tokens = embedded_tokens[:coordinator_index]
        right_tokens = embedded_tokens[coordinator_index + 1 :]
        if not left_subject_tokens or len(right_tokens) < 2:
            return None
        left_clause = parse_simple_perception_embedded_clause(left_subject_tokens)
        right_clause = parse_simple_perception_embedded_clause(right_tokens)
        if left_clause is not None and right_clause is not None:
            embedded_proposition = proposition_coordination_ast(
                [left_clause, right_clause],
                connective_for_coordinator(coordinator),
            )
        else:
            embedded_surface = right_tokens[-1]
            if not is_perception_embedded_intransitive_surface(embedded_surface):
                return None
            right_subject_tokens = right_tokens[:-1]
            if not right_subject_tokens:
                return None
            embedded_predicate = lemma_verb(embedded_surface)
            subjects = [
                perception_entity_name(left_subject_tokens),
                perception_entity_name(right_subject_tokens),
            ]
            embedded_proposition = subject_coordination_ast(
                subjects,
                {
                    "surface": embedded_surface,
                    "name": embedded_predicate,
                    "predicate_type": "Entity -> Prop",
                },
                [],
                [],
                connective_for_coordinator(coordinator),
            )

    if embedded_proposition is None:
        return None
    definition_suffix = perception_embedded_definition_suffix(embedded_proposition)
    embedded_translation = render_perception_embedded_translation(embedded_proposition)
    embedded_coq = render_perception_embedded_coq(embedded_proposition)
    alternative_scope_readings = [
        dict(reading)
        for reading in embedded_proposition.get("alternative_scope_readings", [])
        if isinstance(reading, dict)
    ]
    for reading in alternative_scope_readings:
        reading["typed_replacement"] = (
            f"see(Mary, E({reading['dependent_type_translation']}))"
        )
        reading["coq_definition"] = (
            f"mary_saw_{definition_suffix}_{reading['name']}"
        )
    time_modified_attachment = (
        embedded_proposition
        if embedded_proposition.get("kind") == "time_modified_proposition"
        else None
    )
    matrix_time_attachment: dict[str, Any] | None = None
    if time_modified_attachment is not None:
        matrix_body = time_modified_attachment["body"]
        matrix_body_suffix = perception_embedded_definition_suffix(matrix_body)
        matrix_body_translation = render_perception_embedded_translation(matrix_body)
        matrix_body_coq = render_perception_embedded_coq(matrix_body)
        matrix_operator = time_modified_attachment["operator_name"]
        matrix_argument = time_modified_attachment["argument"]["name"]
        matrix_time_attachment = {
            "name": "matrix_time_attachment",
            "dependent_type_translation": (
                f"{matrix_operator}("
                f"{matrix_argument}, "
                f"see(Mary, E({matrix_body_translation})))"
            ),
            "coq_definition": (
                f"mary_saw_{matrix_body_suffix}_"
                f"{time_modified_attachment['operator']}_{matrix_argument}_matrix"
            ),
            "coq_term": (
                f"{matrix_operator} {matrix_argument} "
                f"({perception_predicate} {experiencer} (E ({matrix_body_coq})))"
            ),
            "attachment_summary": perception_time_attachment_summary(
                kind="matrix_time_attachment",
                proposition=time_modified_attachment,
                target="matrix_perception",
            ),
            "reading_explanation": (
                f"The temporal modifier {matrix_argument} attaches to the matrix "
                "perception proposition, while the perceived complement remains "
                f"E({matrix_body_translation})."
            ),
        }
    semantic_readings = [
        semantic_reading(
            name=(
                "complement_time_attachment"
                if time_modified_attachment is not None
                else "primary"
            ),
            dependent_type_translation=f"see(Mary, E({embedded_translation}))",
            coq_definition=f"mary_saw_{definition_suffix}",
            scope=(
                "embedded_complement_time"
                if time_modified_attachment is not None
                else None
            ),
            scope_policy=(
                {
                    "main": "and_before_or",
                    "reference": "and_before_or",
                }
                if alternative_scope_readings
                else None
            ),
            attachment_summary=(
                perception_time_attachment_summary(
                    kind="complement_time_attachment",
                    proposition=time_modified_attachment,
                    target="embedded_complement",
                )
                if time_modified_attachment is not None
                else None
            ),
            reading_explanation=(
                "The temporal modifier attaches inside the perceived complement "
                f"before E nominalizes {embedded_translation}."
                if time_modified_attachment is not None
                else None
            ),
            type_check={
                "ok": True,
                "type": "Prop",
                "errors": [],
            },
            source="perception_nominalization",
        )
    ]
    if matrix_time_attachment is not None:
        semantic_readings.append(
            semantic_reading(
                name=matrix_time_attachment["name"],
                dependent_type_translation=matrix_time_attachment[
                    "dependent_type_translation"
                ],
                coq_definition=matrix_time_attachment["coq_definition"],
                scope="matrix_perception_time",
                type_check={
                    "ok": True,
                    "type": "Prop",
                    "errors": [],
                },
                source="perception_nominalization",
                attachment_summary=matrix_time_attachment["attachment_summary"],
                reading_explanation=matrix_time_attachment["reading_explanation"],
            )
        )
    semantic_readings.extend(
        semantic_reading(
            name=reading["name"],
            dependent_type_translation=reading["typed_replacement"],
            coq_definition=reading["coq_definition"],
            scope_policy=reading["scope_policy"],
            type_check=reading["type_check"],
            source="perception_nominalization",
        )
        for reading in alternative_scope_readings
    )
    embedded_predicate_declarations = unique_typed_declarations(
        perception_embedded_predicate_declarations(embedded_proposition)
    )
    embedded_subjects = perception_embedded_subjects(embedded_proposition)
    connectives = unique_names(perception_embedded_connectives(embedded_proposition))
    embedded_time_arguments = unique_names(
        perception_embedded_time_arguments(embedded_proposition)
    )
    embedded_time_operators = unique_names(
        perception_embedded_time_operators(embedded_proposition)
    )
    coq_code = "\n".join(
        [
            "(* Luo-Shi-style nominalization for perception complements. *)",
            "Parameter Entity : Type.",
            *(["Parameter Time : Type."] if perception_embedded_uses_time(embedded_proposition) else []),
            "",
            f"Parameter {experiencer} : Entity.",
            *[
                f"Parameter {subject} : Entity."
                for subject in unique_names(embedded_subjects)
            ],
            *[
                f"Parameter {argument} : Entity."
                for argument in embedded_time_arguments
            ],
            "",
            "Parameter E : Prop -> Entity.",
            *[
                f"Parameter {predicate} : {predicate_type}."
                for predicate, predicate_type in embedded_predicate_declarations
            ],
            f"Parameter {perception_predicate} : Entity -> Entity -> Prop.",
            *[
                f"Parameter {operator} : Entity -> Prop -> Prop."
                for operator in embedded_time_operators
            ],
            *(
                ["Parameter before : Time -> Time -> Prop."]
                if perception_embedded_uses_time(embedded_proposition)
                else []
            ),
            *(
                f"Parameter {connective} : Prop -> Prop -> Prop."
                for connective in connectives
            ),
            "",
            f"Definition mary_saw_{definition_suffix} : Prop :=",
            f"  {perception_predicate} {experiencer} (E ({embedded_coq})).",
            *(
                [
                    "",
                    (
                        f"Definition {matrix_time_attachment['coq_definition']} "
                        ": Prop :="
                    ),
                    f"  {matrix_time_attachment['coq_term']}.",
                ]
                if matrix_time_attachment is not None
                else []
            ),
            *[
                line
                for reading in alternative_scope_readings
                for line in (
                    "",
                    f"Definition {reading['coq_definition']} : Prop :=",
                    (
                        f"  {perception_predicate} {experiencer} "
                        f"(E ({render_perception_embedded_coq(reading['ast'])}))."
                    ),
                )
            ],
            "",
            f"Check mary_saw_{definition_suffix}.",
            *(
                [f"Check {matrix_time_attachment['coq_definition']}."]
                if matrix_time_attachment is not None
                else []
            ),
            *[
                f"Check {reading['coq_definition']}."
                for reading in alternative_scope_readings
            ],
            "",
        ]
    )
    semantic_readings_check = check_semantic_readings(semantic_readings, coq_code)
    event_semantics = {
        "analysis": "parsons-perception-complement",
        "source": sentence,
        "event_style_reference": (
            "exists e p. seeing(e) and Experiencer(e, Mary) and "
            f"PropositionObject(p, {embedded_translation}) and Theme(e, p)"
        ),
        "typed_replacement": f"see(Mary, E({embedded_translation}))",
        "semantic_readings": semantic_readings,
        "semantic_readings_check": semantic_readings_check,
    }
    if matrix_time_attachment is not None:
        event_semantics["attachment_ambiguity_readings"] = [
            {
                "name": "complement_time_attachment",
                "dependent_type_translation": f"see(Mary, E({embedded_translation}))",
                "coq_definition": f"mary_saw_{definition_suffix}",
                "attachment_summary": semantic_readings[0]["attachment_summary"],
            },
            {
                "name": matrix_time_attachment["name"],
                "dependent_type_translation": matrix_time_attachment[
                    "dependent_type_translation"
                ],
                "coq_definition": matrix_time_attachment["coq_definition"],
                "attachment_summary": matrix_time_attachment["attachment_summary"],
            },
        ]
    if alternative_scope_readings:
        event_semantics["alternative_scope_readings"] = alternative_scope_readings
    ast = perception_nominalization_ast(
        perception_predicate,
        experiencer,
        embedded_proposition,
    )
    type_check = check_perception_nominalization_ast(ast)
    return {
        "kind": "perception_nominalization",
        "input_sentence": sentence,
        "event_semantics": event_semantics,
        "dependent_type_translation": event_semantics["typed_replacement"],
        "semantic_readings": semantic_readings,
        "semantic_readings_check": semantic_readings_check,
        **(
            {"attachment_ambiguity_readings": event_semantics["attachment_ambiguity_readings"]}
            if matrix_time_attachment is not None
            else {}
        ),
        **(
            {"alternative_scope_readings": alternative_scope_readings}
            if alternative_scope_readings
            else {}
        ),
        "ast": ast,
        "type_check": {
            **type_check,
            "note": "The perceived eventuality is embedded by E : Prop -> Entity, not by an Event argument.",
        },
        "coq_code": coq_code,
    }


def universal_timed_burning_ast() -> dict[str, Any]:
    return {
        "kind": "forall_time",
        "binders": [
            {"variable": "x", "type": "Entity"},
            {"variable": "t", "type": "Time"},
        ],
        "antecedent": {
            "predicate": "burn",
            "predicate_type": "Entity -> Time -> Prop",
            "arguments": ["x", "t"],
        },
        "consequent": {
            "predicate": "consume",
            "predicate_type": "Entity -> Time -> Prop",
            "arguments": ["oxygen", "t"],
            "theme": {
                "name": "oxygen",
                "type": "Entity",
            },
        },
    }


def check_universal_timed_ast(ast: dict[str, Any]) -> dict[str, Any]:
    errors: list[str] = []
    if ast.get("kind") != "forall_time":
        errors.append("ast.kind must be forall_time")

    binders = ast.get("binders")
    if not isinstance(binders, list) or len(binders) != 2:
        errors.append("forall_time.binders must contain Entity and Time binders")
    else:
        expected = [{"variable": "x", "type": "Entity"}, {"variable": "t", "type": "Time"}]
        if binders != expected:
            errors.append("forall_time.binders must bind x : Entity and t : Time")

    for field in ("antecedent", "consequent"):
        predicate = ast.get(field)
        if not isinstance(predicate, dict):
            errors.append(f"forall_time.{field} must be a predicate object")
            continue
        if predicate.get("predicate_type") != "Entity -> Time -> Prop":
            errors.append(f"forall_time.{field} must have type Entity -> Time -> Prop")
        args = predicate.get("arguments")
        if not isinstance(args, list) or len(args) != 2:
            errors.append(f"forall_time.{field}.arguments must contain entity and time")
        elif args[1] != "t":
            errors.append(f"forall_time.{field} must share the bound time variable t")

    consequent = ast.get("consequent")
    if isinstance(consequent, dict):
        theme = consequent.get("theme")
        if not isinstance(theme, dict) or theme.get("type") != "Entity":
            errors.append("forall_time.consequent.theme must have type Entity")
        elif theme.get("name") not in consequent.get("arguments", []):
            errors.append("forall_time.consequent.theme must occur in consequent arguments")

    return {
        "ok": not errors,
        "type": "Prop" if not errors else None,
        "errors": errors,
    }


def every_burning_pipeline(sentence: str) -> dict[str, Any] | None:
    tokens = tokenize(sentence)
    if tokens != ["in", "every", "burning", "oxygen", "is", "consumed"]:
        return None

    coq_code = "\n".join(
        [
            "(* Timed universal replacement for Parsons-style event inclusion. *)",
            "Parameter Entity : Type.",
            "Parameter Time : Type.",
            "",
            "Parameter oxygen : Entity.",
            "",
            "Parameter burn : Entity -> Time -> Prop.",
            "Parameter consume : Entity -> Time -> Prop.",
            "",
            "Definition every_burning_consumes_oxygen : Prop :=",
            "  forall x : Entity,",
            "  forall t : Time,",
            "    burn x t -> consume oxygen t.",
            "",
            "Check every_burning_consumes_oxygen.",
            "",
        ]
    )
    event_semantics = {
        "analysis": "parsons-event-inclusion",
        "source": sentence,
        "event_style_reference": (
            "forall e. burning(e) -> exists e'. consuming(e') and "
            "Theme(e', oxygen) and IN(e', e)"
        ),
        "typed_replacement": (
            "forall x : Entity. forall t : Time. "
            "burn(x, t) -> consume(oxygen, t)"
        ),
    }
    ast = universal_timed_burning_ast()
    type_check = check_universal_timed_ast(ast)
    return attach_single_semantic_reading(
        {
            "kind": "universal_timed_burning",
            "input_sentence": sentence,
            "event_semantics": event_semantics,
            "dependent_type_translation": event_semantics["typed_replacement"],
            "ast": ast,
            "type_check": {
                **type_check,
                "note": "Event inclusion is represented as universal quantification over entities and times.",
            },
            "coq_code": coq_code,
        },
        name="universal_timed_burning",
        coq_definition="every_burning_consumes_oxygen",
        source="universal_timed_burning",
        scope="forall_entity_time",
    )


def lexical_state_change_ast(
    verb: str,
    theme: str,
    target_state: str,
    surface_verb: str,
    causer: str | None = None,
    instrument: str | None = None,
) -> dict[str, Any]:
    transition = {
        "kind": "transition",
        "theme": {"name": theme, "type": "Entity"},
        "state_scale": STATE_SCALE_BY_STATE[target_state],
        "source_state": SOURCE_STATE_BY_TARGET_STATE[target_state],
        "target_state": {"name": target_state, "type": "State"},
    }
    ast: dict[str, Any] = {
        "kind": "lexical_state_change",
        "verb": verb,
        "surface_lexicon": surface_verb_audit(surface_verb),
        "frame": "inchoative",
        "transition": transition,
    }
    if causer is not None:
        ast["frame"] = "causative"
        ast["causer"] = {"name": causer, "type": "Entity", "source": "subject"}
    if instrument is not None:
        ast["frame"] = "instrumental"
        ast["instrument"] = {
            "name": instrument,
            "type": "Entity",
            "source": "with_phrase",
        }
    return ast


def check_lexical_state_change_ast(ast: dict[str, Any]) -> dict[str, Any]:
    errors: list[str] = []
    if ast.get("kind") != "lexical_state_change":
        errors.append("ast.kind must be lexical_state_change")
    verb = ast.get("verb")
    entry = STATE_CHANGE_VERB_REGISTRY.get(verb)
    if entry is None:
        errors.append("state-change verb must be registered in STATE_CHANGE_VERB_REGISTRY")
    surface_lexicon = ast.get("surface_lexicon")
    if not isinstance(surface_lexicon, dict):
        errors.append("state-change surface_lexicon must be an object")
    else:
        surface_verb = surface_lexicon.get("surface_verb")
        if not isinstance(surface_verb, str) or not surface_verb:
            errors.append("state-change surface_lexicon.surface_verb must be a non-empty string")
        if surface_lexicon.get("lemma") != verb:
            errors.append("state-change surface_lexicon.lemma must match verb")
        elif isinstance(surface_verb, str) and lemma_verb(surface_verb) != verb:
            errors.append("state-change surface_lexicon.lemma must match lemmatized surface verb")
        if surface_lexicon.get("source") != SURFACE_LEXICON_SOURCE:
            errors.append("state-change surface_lexicon.source must identify the surface lexicon")
    frame = ast.get("frame")
    if frame not in {"inchoative", "causative", "instrumental"}:
        errors.append("state-change frame must be inchoative, causative, or instrumental")

    transition = ast.get("transition")
    if not isinstance(transition, dict):
        errors.append("state-change transition must be an object")
    else:
        if transition.get("kind") != "transition":
            errors.append("state-change transition.kind must be transition")
        theme = transition.get("theme")
        if not isinstance(theme, dict):
            errors.append("state-change theme must be an object")
        else:
            if not isinstance(theme.get("name"), str) or not theme.get("name"):
                errors.append("state-change theme.name must be a non-empty string")
            if theme.get("type") != "Entity":
                errors.append("state-change theme must have type Entity")
            anaphora = theme.get("anaphora")
            if anaphora is not None:
                if not isinstance(anaphora, dict):
                    errors.append("state-change theme.anaphora must be an object")
                else:
                    if anaphora.get("pronoun") not in ANAPHORIC_ENTITY_PRONOUNS:
                        errors.append(
                            "state-change theme.anaphora.pronoun must be a registered entity pronoun"
                        )
                    if anaphora.get("resolved_to") != theme.get("name"):
                        errors.append(
                            "state-change theme.anaphora.resolved_to must match theme.name"
                        )
                    if anaphora.get("source_clause") not in {"cause", "effect"}:
                        errors.append(
                            "state-change theme.anaphora.source_clause must be cause or effect"
                        )
                    if anaphora.get("source_role") not in {"object", "theme", "subject"}:
                        errors.append(
                            "state-change theme.anaphora.source_role must be object, theme, or subject"
                        )
                    if anaphora.get("resolution_policy") != "single_compatible_patient":
                        errors.append(
                            "state-change theme.anaphora.resolution_policy must be single_compatible_patient"
                        )
        target = transition.get("target_state")
        if not isinstance(target, dict):
            errors.append("state-change target_state must be an object")
            target_name = None
        else:
            target_name = target.get("name")
            if not isinstance(target_name, str) or not target_name:
                errors.append("state-change target_state.name must be a non-empty string")
            elif target_name not in SOURCE_STATE_BY_TARGET_STATE:
                errors.append(f"state-change target has no lexical source state: {target_name}")
            elif entry is not None and target_name != entry.target_state:
                errors.append("state-change target_state must match the registered verb target")
            if target.get("type") != "State":
                errors.append("state-change target_state must have type State")
        if isinstance(target_name, str) and target_name in SOURCE_STATE_BY_TARGET_STATE:
            if transition.get("state_scale") != STATE_SCALE_BY_STATE[target_name]:
                errors.append("state-change state_scale must match the state lexicon")
            if transition.get("source_state") != SOURCE_STATE_BY_TARGET_STATE[target_name]:
                errors.append("state-change source_state must match the state lexicon")

    causer = ast.get("causer")
    instrument = ast.get("instrument")
    expected_frame = "instrumental" if instrument is not None else "causative" if causer is not None else "inchoative"
    if frame != expected_frame:
        errors.append("state-change frame must match its causer and instrument fields")

    if frame == "inchoative" and entry is not None and not entry.allow_inchoative:
        errors.append("state-change verb does not license the inchoative frame")
    if causer is not None:
        if frame == "causative" and entry is not None and not entry.allow_causative:
            errors.append("state-change verb does not license the causative frame")
        if not isinstance(causer, dict):
            errors.append("state-change causer must be an object")
        else:
            if not isinstance(causer.get("name"), str) or not causer.get("name"):
                errors.append("state-change causer.name must be a non-empty string")
            if causer.get("type") != "Entity":
                errors.append("state-change causer must have type Entity")
            if causer.get("source") != "subject":
                errors.append("state-change causer.source must be subject")

    if instrument is not None:
        if causer is None:
            errors.append("state-change instrument requires a causer")
        if frame == "instrumental" and entry is not None and not entry.allow_instrument:
            errors.append("state-change verb does not license the instrumental frame")
        if not isinstance(instrument, dict):
            errors.append("state-change instrument must be an object")
        else:
            if not isinstance(instrument.get("name"), str) or not instrument.get("name"):
                errors.append("state-change instrument.name must be a non-empty string")
            if instrument.get("type") != "Entity":
                errors.append("state-change instrument must have type Entity")
            if instrument.get("source") != "with_phrase":
                errors.append("state-change instrument.source must be with_phrase")

    return {
        "ok": not errors,
        "type": "Prop" if not errors else None,
        "errors": errors,
    }


def render_state_change_translation(ast: dict[str, Any]) -> str:
    transition = ast["transition"]
    theme = transition["theme"]["name"]
    state_scale = transition["state_scale"]
    source_state = transition["source_state"]
    target_state = transition["target_state"]["name"]
    transition_text = f"Transition({theme}, {state_scale}, {source_state}, {target_state})"
    instrument = ast.get("instrument")
    causer = ast.get("causer")
    if instrument is not None and causer is not None:
        return f"CauseWithInstrument({causer['name']}, {instrument['name']}, {transition_text})"
    if causer is not None:
        return f"Cause({causer['name']}, {transition_text})"
    return f"Change({transition_text})"


def lexical_state_change_failure(sentence: str, ast: dict[str, Any]) -> dict[str, Any]:
    type_check = check_lexical_state_change_ast(ast)
    return {
        "kind": "lexical_state_change",
        "input_sentence": sentence,
        "event_semantics": {
            "analysis": "lexical-state-change",
            "source": sentence,
            "event_style_reference": "blocked before event-style fallback",
            "typed_replacement": None,
        },
        "dependent_type_translation": "No licensed lexical state-change frame.",
        "result_state_lexicon": [
            state_lexicon_metadata(ast["transition"]["target_state"]["name"])
        ],
        "state_change_verb_entry": state_change_verb_metadata(ast["verb"]),
        "ast": ast,
        "type_check": {
            **type_check,
            "note": (
                "A registered state-change verb was recognized, but the surface "
                "frame is not licensed by its lexical registration."
            ),
        },
        "coq_code": "",
    }


def lexical_state_change_pipeline(sentence: str) -> dict[str, Any] | None:
    tokens = tokenize(sentence)
    if len(tokens) < 2:
        return None
    for verb_index, token in enumerate(tokens):
        verb = lemma_verb(token)
        entry = STATE_CHANGE_VERB_REGISTRY.get(verb)
        if entry is None:
            continue
        if any(auxiliary in tokens[:verb_index] for auxiliary in PASSIVE_AUXILIARIES):
            return None
        target_state = entry.target_state
        if target_state not in SOURCE_STATE_BY_TARGET_STATE:
            return None

        if verb_index == len(tokens) - 1 and verb_index > 0:
            theme = clean_phrase(tokens[:verb_index])
            ast = lexical_state_change_ast(verb, theme, target_state, token)
            if not entry.allow_inchoative:
                return lexical_state_change_failure(sentence, ast)
            break

        if verb_index == 0 or verb_index + 1 >= len(tokens):
            return None
        causer = clean_phrase(tokens[:verb_index])
        rest = tokens[verb_index + 1:]
        instrument = None
        if "with" in rest:
            with_index = rest.index("with")
            object_tokens = rest[:with_index]
            instrument_tokens = rest[with_index + 1:]
            if not object_tokens or not instrument_tokens:
                return None
            instrument = clean_phrase(instrument_tokens)
        else:
            object_tokens = rest
        if not object_tokens:
            return None
        theme = clean_phrase(object_tokens)
        ast = lexical_state_change_ast(
            verb,
            theme,
            target_state,
            token,
            causer,
            instrument,
        )
        if not entry.allow_causative or (instrument is not None and not entry.allow_instrument):
            return lexical_state_change_failure(sentence, ast)
        break
    else:
        return None

    type_check = check_lexical_state_change_ast(ast)
    transition = ast["transition"]
    theme = transition["theme"]["name"]
    state_scale = transition["state_scale"]
    source_state = transition["source_state"]
    target_state = transition["target_state"]["name"]
    typed_replacement = render_state_change_translation(ast)
    definition_name = f"lexical_{ast['verb']}_state_change"
    coq_parameters = [
        "(* Lexical state-change replacement without an event variable. *)",
        "Parameter Entity : Type.",
        "Parameter State : Type.",
        "Parameter StateScale : Type.",
        "Parameter TransitionT : Type.",
        "",
        f"Parameter {theme} : Entity.",
        f"Parameter {source_state} : State.",
        f"Parameter {target_state} : State.",
        f"Parameter {state_scale} : StateScale.",
    ]
    causer = ast.get("causer")
    instrument = ast.get("instrument")
    if causer is not None:
        coq_parameters.append(f"Parameter {causer['name']} : Entity.")
    if instrument is not None:
        coq_parameters.append(f"Parameter {instrument['name']} : Entity.")
    coq_parameters.extend(
        [
            "",
            "Parameter Transition : Entity -> StateScale -> State -> State -> TransitionT.",
            "Parameter Change : TransitionT -> Prop.",
            "Parameter Cause : Entity -> TransitionT -> Prop.",
            "Parameter CauseWithInstrument : Entity -> Entity -> TransitionT -> Prop.",
            "",
        ]
    )
    transition_coq = f"Transition {theme} {state_scale} {source_state} {target_state}"
    if instrument is not None and causer is not None:
        body = f"CauseWithInstrument {causer['name']} {instrument['name']} ({transition_coq})"
    elif causer is not None:
        body = f"Cause {causer['name']} ({transition_coq})"
    else:
        body = f"Change ({transition_coq})"
    coq_code = "\n".join(
        [
            *coq_parameters,
            f"Definition {definition_name} : Prop :=",
            f"  {body}.",
            "",
            f"Check {definition_name}.",
            "",
        ]
    )
    return {
        "kind": "lexical_state_change",
        "input_sentence": sentence,
        "event_semantics": {
            "analysis": "lexical-state-change",
            "source": sentence,
            "event_style_reference": (
                f"exists e. {ast['verb']}ing(e) and Theme(e, {theme}) "
                f"and ResultState(e, {target_state})"
            ),
            "typed_replacement": typed_replacement,
        },
        "dependent_type_translation": typed_replacement,
        "result_state_lexicon": [state_lexicon_metadata(target_state)],
        "state_change_verb_entry": state_change_verb_metadata(ast["verb"]),
        "ast": ast,
        "type_check": {
            **type_check,
            "note": (
                "A lexical change-of-state verb maps directly to a typed "
                "state transition; the changing object is not treated as an Agent."
            ),
        },
        "coq_code": coq_code,
    }


def stative_result_state_ast(
    subject: str,
    states: str | list[str],
    auxiliary: str,
    polarity: str = "positive",
) -> dict[str, Any]:
    state_names = [states] if isinstance(states, str) else states
    first_state = state_names[0]
    ast = {
        "kind": "stative_result_state",
        "subject": {"name": subject, "type": "Entity"},
        "state": {"name": first_state, "type": "State"},
        "state_scale": STATE_SCALE_BY_STATE[first_state],
        "predicate": "holds_state",
        "predicate_type": "Entity -> StateScale -> State -> Prop",
        "auxiliary": auxiliary,
    }
    if len(state_names) > 1:
        ast["states"] = [
            {
                "name": state_name,
                "type": "State",
                "state_scale": STATE_SCALE_BY_STATE[state_name],
            }
            for state_name in state_names
        ]
    if polarity != "positive":
        ast["polarity"] = polarity
    return ast


def check_stative_result_state_ast(ast: dict[str, Any]) -> dict[str, Any]:
    errors: list[str] = []
    incompatible_state_pairs: list[dict[str, str]] = []
    if ast.get("kind") != "stative_result_state":
        errors.append("ast.kind must be stative_result_state")
    subject = ast.get("subject")
    if not isinstance(subject, dict):
        errors.append("stative subject must be an object")
    else:
        if not isinstance(subject.get("name"), str) or not subject.get("name"):
            errors.append("stative subject.name must be a non-empty string")
        if subject.get("type") != "Entity":
            errors.append("stative subject must have type Entity")
        anaphora = subject.get("anaphora")
        if anaphora is not None:
            if not isinstance(anaphora, dict):
                errors.append("stative subject.anaphora must be an object")
            else:
                if anaphora.get("pronoun") not in ANAPHORIC_ENTITY_PRONOUNS:
                    errors.append(
                        "stative subject.anaphora.pronoun must be a registered entity pronoun"
                    )
                if anaphora.get("resolved_to") != subject.get("name"):
                    errors.append(
                        "stative subject.anaphora.resolved_to must match subject.name"
                    )
                if anaphora.get("source_clause") not in {"cause", "effect"}:
                    errors.append(
                        "stative subject.anaphora.source_clause must be cause or effect"
                    )
                if anaphora.get("source_role") not in {"object", "theme", "subject"}:
                    errors.append(
                        "stative subject.anaphora.source_role must be object, theme, or subject"
                    )
                if anaphora.get("resolution_policy") != "single_compatible_patient":
                    errors.append(
                        "stative subject.anaphora.resolution_policy must be single_compatible_patient"
                    )

    state = ast.get("state")
    if not isinstance(state, dict):
        errors.append("stative state must be an object")
    else:
        state_name = state.get("name")
        if not isinstance(state_name, str) or not state_name:
            errors.append("stative state.name must be a non-empty string")
        elif state_name not in STATE_SCALE_BY_STATE:
            errors.append(f"unknown stative result state: {state_name}")
        if state.get("type") != "State":
            errors.append("stative state must have type State")
        if (
            isinstance(state_name, str)
            and state_name in STATE_SCALE_BY_STATE
            and ast.get("state_scale") != STATE_SCALE_BY_STATE[state_name]
        ):
            errors.append("stative state_scale must match the state lexicon")

    states = ast.get("states")
    if states is not None:
        if not isinstance(states, list) or not states:
            errors.append("stative states must be a non-empty list")
        else:
            state_scale_by_name: dict[str, str] = {}
            for index, state_item in enumerate(states):
                if not isinstance(state_item, dict):
                    errors.append(f"stative states[{index}] must be an object")
                    continue
                item_name = state_item.get("name")
                if not isinstance(item_name, str) or not item_name:
                    errors.append(f"stative states[{index}].name must be a non-empty string")
                elif item_name not in STATE_SCALE_BY_STATE:
                    errors.append(f"unknown stative result state: {item_name}")
                if state_item.get("type") != "State":
                    errors.append(f"stative states[{index}] must have type State")
                if (
                    isinstance(item_name, str)
                    and item_name in STATE_SCALE_BY_STATE
                    and state_item.get("state_scale") != STATE_SCALE_BY_STATE[item_name]
                ):
                    errors.append(f"stative states[{index}].state_scale must match the state lexicon")
                item_scale = state_item.get("state_scale")
                if isinstance(item_name, str) and isinstance(item_scale, str):
                    state_scale_by_name[item_name] = item_scale
            sorted_state_names = sorted(state_scale_by_name)
            for left_index, left_name in enumerate(sorted_state_names):
                for right_name in sorted_state_names[left_index + 1 :]:
                    if frozenset((left_name, right_name)) not in INCOMPATIBLE_STATE_PAIRS:
                        continue
                    item_scale = state_scale_by_name[left_name]
                    joined_names = " and ".join(sorted((left_name, right_name)))
                    errors.append(
                        "stative states cannot contain incompatible states on the same "
                        f"scale: {item_scale} has {joined_names}"
                    )
                    incompatible_state_pairs.append(
                        {
                            "state_scale": item_scale,
                            "left_state": left_name,
                            "right_state": right_name,
                            "states": joined_names,
                            "source": "translator/dependent_type_event_translator.py",
                            "relation": "lexical_opposition",
                        }
                    )

    if ast.get("predicate") != "holds_state":
        errors.append("stative predicate must be holds_state")
    if ast.get("predicate_type") != "Entity -> StateScale -> State -> Prop":
        errors.append("stative predicate must have type Entity -> StateScale -> State -> Prop")
    if ast.get("auxiliary") not in PASSIVE_AUXILIARIES:
        errors.append("stative auxiliary must be is, was, are, or were")
    if ast.get("polarity", "positive") not in {"positive", "negative"}:
        errors.append("stative polarity must be positive or negative")

    result = {
        "ok": not errors,
        "type": "Prop" if not errors else None,
        "errors": errors,
    }
    if incompatible_state_pairs:
        result["incompatible_state_pairs"] = incompatible_state_pairs
    return result


def stative_result_state_pipeline(sentence: str) -> dict[str, Any] | None:
    tokens = tokenize(sentence)
    auxiliary_indices = [
        index for index, token in enumerate(tokens) if token in PASSIVE_AUXILIARIES
    ]
    if len(tokens) < 3 or not auxiliary_indices:
        return None
    auxiliary_index = auxiliary_indices[0]
    auxiliary = tokens[auxiliary_index]
    if auxiliary_index == 0 or auxiliary_index + 1 >= len(tokens):
        return None
    subject = clean_phrase(tokens[:auxiliary_index])
    state_index = auxiliary_index + 1
    polarity = "positive"
    if tokens[state_index] == "not":
        polarity = "negative"
        state_index += 1
        if state_index >= len(tokens):
            return None
    state_tokens = tokens[state_index:]
    state_groups = split_coordinate_tokens(state_tokens)
    if state_groups is None:
        return None
    state_names = [clean_phrase(group) for group in state_groups]
    if any(len(group) != 1 for group in state_groups):
        return None
    if any(state_name not in STATE_SCALE_BY_STATE for state_name in state_names):
        return None

    ast = stative_result_state_ast(subject, state_names, auxiliary, polarity)
    type_check = check_stative_result_state_ast(ast)
    state_label = "_and_".join(state_names)
    definition_name = (
        f"stative_not_{state_label}_state"
        if polarity == "negative"
        else f"stative_{state_label}_state"
    )
    state_assertions = [
        f"holds_state({subject}, {STATE_SCALE_BY_STATE[state_name]}, {state_name})"
        for state_name in state_names
    ]
    state_assertion = state_assertions[0]
    for next_assertion in state_assertions[1:]:
        state_assertion = f"and_T({state_assertion}, {next_assertion})"
    typed_replacement = (
        f"not_T({state_assertion})" if polarity == "negative" else state_assertion
    )
    coq_assertions = [
        f"holds_state {subject} {STATE_SCALE_BY_STATE[state_name]} {state_name}"
        for state_name in state_names
    ]
    coq_assertion = coq_assertions[0]
    for next_assertion in coq_assertions[1:]:
        coq_assertion = f"and_T ({coq_assertion}) ({next_assertion})"
    coq_body = f"not_T ({coq_assertion})" if polarity == "negative" else coq_assertion
    state_declarations: list[str] = []
    seen_state_declarations: set[str] = set()
    for state_name in state_names:
        for declaration in (
            f"Parameter {state_name} : State.",
            f"Parameter {STATE_SCALE_BY_STATE[state_name]} : StateScale.",
        ):
            if declaration not in seen_state_declarations:
                state_declarations.append(declaration)
                seen_state_declarations.add(declaration)
    coq_code = "\n".join(
        [
            "(* Stative result-state replacement without an event variable. *)",
            "Parameter Entity : Type.",
            "Parameter State : Type.",
            "Parameter StateScale : Type.",
            "",
            f"Parameter {subject} : Entity.",
            *state_declarations,
            "",
            "Parameter holds_state : Entity -> StateScale -> State -> Prop.",
            *(
                ["Parameter and_T : Prop -> Prop -> Prop."]
                if len(state_names) > 1
                else []
            ),
            *(
                ["Parameter not_T : Prop -> Prop."]
                if polarity == "negative"
                else []
            ),
            "",
            f"Definition {definition_name} : Prop :=",
            f"  {coq_body}.",
            "",
            f"Check {definition_name}.",
            "",
        ]
    )
    return {
        "kind": "stative_result_state",
        "input_sentence": sentence,
        "event_semantics": {
            "analysis": "stative-result-state",
            "source": sentence,
            "event_style_reference": (
                f"exists e. ResultState(e, {state_label}) and Theme(e, {subject})"
            ),
            "typed_replacement": typed_replacement,
        },
        "dependent_type_translation": typed_replacement,
        "ast": ast,
        "type_check": {
            **type_check,
            "note": (
                "A copular result state is represented as a typed state "
                "assertion, not as an omitted Agent event."
            ),
        },
        "coq_code": coq_code,
    }


def copular_property_ast(
    subject: str,
    property_conjuncts: list[dict[str, str | None]],
    auxiliary: str,
    time_modifiers: list[dict[str, str]],
    negated: bool = False,
) -> dict[str, Any]:
    first = property_conjuncts[0]
    ast = {
        "kind": "copular_property",
        "subject": {"name": subject, "type": "Entity"},
        "property": {"name": first["property"], "type": "Property"},
        "predicate": "holds_property",
        "predicate_type": "Entity -> Property -> Prop",
        "auxiliary": auxiliary,
        "negated": negated,
        "time_modifiers": time_modifiers,
    }
    if first.get("degree") is not None:
        ast["degree"] = {"name": first["degree"], "type": "Degree"}
    if len(property_conjuncts) > 1:
        ast["property_conjuncts"] = [
            {
                "property": {"name": conjunct["property"], "type": "Property"},
                **(
                    {"degree": {"name": conjunct["degree"], "type": "Degree"}}
                    if conjunct.get("degree") is not None
                    else {}
                ),
            }
            for conjunct in property_conjuncts
        ]
    return ast


def check_copular_property_ast(ast: dict[str, Any]) -> dict[str, Any]:
    errors: list[str] = []
    if ast.get("kind") != "copular_property":
        errors.append("ast.kind must be copular_property")

    subject = ast.get("subject")
    if not isinstance(subject, dict):
        errors.append("copular property subject must be an object")
    else:
        if not isinstance(subject.get("name"), str) or not subject.get("name"):
            errors.append("copular property subject.name must be a non-empty string")
        if subject.get("type") != "Entity":
            errors.append("copular property subject must have type Entity")

    property_info = ast.get("property")
    if not isinstance(property_info, dict):
        errors.append("copular property must be an object")
    else:
        property_name = property_info.get("name")
        if not isinstance(property_name, str) or not property_name:
            errors.append("copular property.name must be a non-empty string")
        elif property_name in STATE_SCALE_BY_STATE:
            errors.append("copular property must not duplicate a registered State")
        if property_info.get("type") != "Property":
            errors.append("copular property must have type Property")

    if ast.get("predicate") != "holds_property":
        errors.append("copular property predicate must be holds_property")
    if ast.get("predicate_type") != "Entity -> Property -> Prop":
        errors.append("copular property predicate must have type Entity -> Property -> Prop")
    if ast.get("auxiliary") not in PASSIVE_AUXILIARIES:
        errors.append("copular property auxiliary must be is, was, are, or were")
    if not isinstance(ast.get("negated"), bool):
        errors.append("copular property negated must be a boolean")

    degree = ast.get("degree")
    if degree is not None:
        if not isinstance(degree, dict):
            errors.append("copular property degree must be an object")
        else:
            degree_name = degree.get("name")
            if degree_name not in PROPERTY_DEGREES:
                errors.append("copular property degree.name must be a registered Degree")
            if degree.get("type") != "Degree":
                errors.append("copular property degree must have type Degree")

    property_conjuncts = ast.get("property_conjuncts")
    if property_conjuncts is not None:
        if not isinstance(property_conjuncts, list) or len(property_conjuncts) < 2:
            errors.append("copular property_conjuncts must be a list with at least two items")
        else:
            for index, conjunct in enumerate(property_conjuncts):
                if not isinstance(conjunct, dict):
                    errors.append(f"copular property_conjuncts[{index}] must be an object")
                    continue
                conjunct_property = conjunct.get("property")
                if not isinstance(conjunct_property, dict):
                    errors.append(f"copular property_conjuncts[{index}].property must be an object")
                else:
                    conjunct_name = conjunct_property.get("name")
                    if not isinstance(conjunct_name, str) or not conjunct_name:
                        errors.append(
                            f"copular property_conjuncts[{index}].property.name must be a non-empty string"
                        )
                    elif conjunct_name in STATE_SCALE_BY_STATE:
                        errors.append(
                            f"copular property_conjuncts[{index}] must not duplicate a registered State"
                        )
                    if conjunct_property.get("type") != "Property":
                        errors.append(
                            f"copular property_conjuncts[{index}].property must have type Property"
                        )
                conjunct_degree = conjunct.get("degree")
                if conjunct_degree is not None:
                    if not isinstance(conjunct_degree, dict):
                        errors.append(f"copular property_conjuncts[{index}].degree must be an object")
                    else:
                        degree_name = conjunct_degree.get("name")
                        if degree_name not in PROPERTY_DEGREES:
                            errors.append(
                                f"copular property_conjuncts[{index}].degree.name must be a registered Degree"
                            )
                        if conjunct_degree.get("type") != "Degree":
                            errors.append(
                                f"copular property_conjuncts[{index}].degree must have type Degree"
                            )

    time_modifiers = ast.get("time_modifiers")
    if not isinstance(time_modifiers, list):
        errors.append("copular property time_modifiers must be a list")
    else:
        for index, modifier in enumerate(time_modifiers):
            if not isinstance(modifier, dict):
                errors.append(f"copular property time_modifiers[{index}] must be an object")
                continue
            if modifier.get("operator") not in {"at", "during"}:
                errors.append(
                    f"copular property time_modifiers[{index}].operator must be at or during"
                )
            if not isinstance(modifier.get("argument"), str) or not modifier.get("argument"):
                errors.append(
                    f"copular property time_modifiers[{index}].argument must be a non-empty string"
                )

    return {
        "ok": not errors,
        "type": "Prop" if not errors else None,
        "errors": errors,
    }


def copular_property_time_modifiers(tokens: list[str]) -> list[dict[str, str]] | None:
    modifiers: list[dict[str, str]] = []
    idx = 0
    while idx < len(tokens):
        token = tokens[idx]
        if token in TEMPORAL_ADVERBS:
            modifiers.append({"operator": "at", "argument": token})
            idx += 1
            continue
        temporal_phrase = temporal_phrase_value(tokens, idx)
        if temporal_phrase is not None:
            normalized_time, consumed = temporal_phrase
            modifiers.append({"operator": "at", "argument": normalized_time})
            idx += consumed
            continue
        temporal_prep_phrase = temporal_prepositional_phrase_value(tokens, idx)
        if temporal_prep_phrase is not None:
            operator, normalized_time, consumed = temporal_prep_phrase
            modifiers.append({"operator": operator, "argument": normalized_time})
            idx += consumed
            continue
        return None
    return modifiers


def split_fronted_time_modifiers(
    tokens: list[str],
) -> tuple[list[str], list[dict[str, str]]]:
    modifiers: list[dict[str, str]] = []
    idx = 0
    while idx < len(tokens):
        token = tokens[idx]
        if token in TEMPORAL_ADVERBS:
            modifiers.append({"operator": "at", "argument": token})
            idx += 1
            continue
        temporal_phrase = temporal_phrase_value(tokens, idx)
        if temporal_phrase is not None:
            normalized_time, consumed = temporal_phrase
            modifiers.append({"operator": "at", "argument": normalized_time})
            idx += consumed
            continue
        temporal_prep_phrase = temporal_prepositional_phrase_value(tokens, idx)
        if temporal_prep_phrase is not None:
            operator, normalized_time, consumed = temporal_prep_phrase
            modifiers.append({"operator": operator, "argument": normalized_time})
            idx += consumed
            continue
        break
    return tokens[idx:], modifiers


def starts_surface_subject_boundary(tokens: list[str], position: int) -> bool:
    subject_start = position
    starts_with_article = False
    if subject_start < len(tokens) and tokens[subject_start] in ARTICLES:
        starts_with_article = True
        subject_start += 1
    elif subject_start < len(tokens) and tokens[subject_start] in QUANTIFIER_SUBJECT_DETERMINERS:
        starts_with_article = True
        subject_start += 1
    if subject_start >= len(tokens):
        return False

    def is_boundary_predicate(token: str) -> bool:
        return (
            token in PASSIVE_AUXILIARIES
            or token in DO_SUPPORT_AUXILIARIES
            or is_likely_surface_verb(token)
            or (token.endswith("ed") and len(token) > 3)
        )

    subject_widths = (1, 2) if starts_with_article else (1,)
    for subject_width in subject_widths:
        predicate_position = subject_start + subject_width
        if (
            predicate_position < len(tokens)
            and is_boundary_predicate(tokens[predicate_position])
        ):
            return True
    return False


def modifier_expression(preposition: str, phrase_tokens: list[str]) -> str:
    return f"{preposition}({clean_phrase(phrase_tokens)})"


def modifier_record(expression: str) -> dict[str, Any]:
    semantic_role = modifier_semantic_role(expression)
    return {
        "expression": expression,
        "name": normalize_surface_name(expression),
        "type": "Adv",
        "semantic_role": semantic_role,
        "surface_lexicon": modifier_surface_audit(expression, "Adv", semantic_role),
    }


def split_fronted_adv_modifiers(
    tokens: list[str],
) -> tuple[list[str], list[dict[str, Any]]]:
    modifiers: list[dict[str, Any]] = []
    idx = 0
    while idx < len(tokens):
        if tokens[idx] in COMMON_ADVERBS:
            modifiers.append(modifier_record(tokens[idx]))
            idx += 1
            continue
        preposition = tokens[idx]
        if preposition not in FRONTED_MODIFIER_PREPOSITIONS:
            break
        if temporal_prepositional_phrase_value(tokens, idx) is not None:
            break
        phrase_start = idx + 1
        phrase: list[str] = []
        cursor = phrase_start
        while cursor < len(tokens):
            if any(token not in ARTICLES for token in phrase):
                if tokens[cursor] in FRONTED_MODIFIER_PREPOSITIONS:
                    break
                if tokens[cursor] in COMMON_ADVERBS:
                    break
                if tokens[cursor] in TEMPORAL_ADVERBS:
                    break
                if temporal_phrase_value(tokens, cursor) is not None:
                    break
                if temporal_prepositional_phrase_value(tokens, cursor) is not None:
                    break
                if starts_surface_subject_boundary(tokens, cursor):
                    break
            phrase.append(tokens[cursor])
            cursor += 1
        if not any(token not in ARTICLES for token in phrase):
            break
        modifiers.append(modifier_record(modifier_expression(preposition, phrase)))
        idx = cursor
    return tokens[idx:], modifiers


def split_shared_adv_and_time_modifiers(
    tokens: list[str],
) -> tuple[list[dict[str, Any]], list[dict[str, str]]] | None:
    if not tokens:
        return [], []
    remaining_tokens, adv_modifiers = split_fronted_adv_modifiers(tokens)
    time_modifiers = copular_property_time_modifiers(remaining_tokens)
    if time_modifiers is None:
        return None
    return adv_modifiers, time_modifiers


def split_common_adv_and_time_modifiers(
    tokens: list[str],
) -> tuple[list[dict[str, Any]], list[dict[str, str]]] | None:
    modifiers: list[dict[str, Any]] = []
    idx = 0
    while idx < len(tokens) and tokens[idx] in COMMON_ADVERBS:
        modifiers.append(modifier_record(tokens[idx]))
        idx += 1
    time_modifiers = copular_property_time_modifiers(tokens[idx:])
    if time_modifiers is None:
        return None
    return modifiers, time_modifiers


def check_coordination_modifiers(
    errors: list[str],
    modifiers: Any,
    context: str,
) -> None:
    if not isinstance(modifiers, list):
        errors.append(f"{context} modifiers must be a list")
        return
    for index, modifier in enumerate(modifiers):
        if not isinstance(modifier, dict):
            errors.append(f"{context} modifiers[{index}] must be an object")
            continue
        expression = modifier.get("expression")
        if not isinstance(expression, str) or not expression:
            errors.append(f"{context} modifiers[{index}].expression must be a non-empty string")
            continue
        expected_name = normalize_surface_name(expression)
        if modifier.get("name") != expected_name:
            errors.append(f"{context} modifiers[{index}].name must match normalized expression")
        if modifier.get("type") != "Adv":
            errors.append(f"{context} modifiers[{index}] must have type Adv")
        expected_role = modifier_semantic_role(expression)
        if modifier.get("semantic_role") != expected_role:
            errors.append(f"{context} modifiers[{index}].semantic_role must match expression")
        expected_audit = modifier_surface_audit(expression, "Adv", expected_role)
        if modifier.get("surface_lexicon") != expected_audit:
            errors.append(f"{context} modifiers[{index}].surface_lexicon must match modifier")


def check_time_modifiers(
    errors: list[str],
    modifiers: Any,
    context: str,
) -> None:
    if not isinstance(modifiers, list):
        errors.append(f"{context} time_modifiers must be a list")
        return
    for index, modifier in enumerate(modifiers):
        if not isinstance(modifier, dict):
            errors.append(f"{context} time_modifiers[{index}] must be an object")
            continue
        if modifier.get("operator") not in {"at", "during"}:
            errors.append(
                f"{context} time_modifiers[{index}].operator must be at or during"
            )
        if not isinstance(modifier.get("argument"), str) or not modifier.get("argument"):
            errors.append(
                f"{context} time_modifiers[{index}].argument must be non-empty"
            )


def readable_modifier_arguments(modifiers: list[dict[str, Any]]) -> str:
    return ", ".join(str(modifier["expression"]) for modifier in modifiers)


def coq_modifier_sequence(modifiers: list[dict[str, Any]]) -> str:
    sequence = "mods_nil"
    length = len(modifiers)
    for index, modifier in reversed(list(enumerate(modifiers))):
        sequence = (
            f"(mods_cons {length - index - 1} "
            f"{modifier['name']} {sequence})"
        )
    return sequence


def unique_names(names: list[str]) -> list[str]:
    return list(dict.fromkeys(names))


def unique_typed_declarations(declarations: list[tuple[str, str]]) -> list[tuple[str, str]]:
    unique: list[tuple[str, str]] = []
    seen: dict[str, str] = {}
    for name, type_name in declarations:
        if name in seen:
            continue
        seen[name] = type_name
        unique.append((name, type_name))
    return unique


def check_declaration_type_conflicts(
    errors: list[str],
    declarations: list[tuple[str, str]],
    context: str,
) -> None:
    seen: dict[str, str] = {}
    for name, type_name in declarations:
        previous_type = seen.get(name)
        if previous_type is None:
            seen[name] = type_name
        elif previous_type != type_name:
            errors.append(
                f"{context} {name} has conflicting lexical types: "
                f"{previous_type} vs {type_name}"
            )


def render_copular_property_translation(
    subject: str,
    property_conjuncts: list[dict[str, str | None]],
    time_modifiers: list[dict[str, str]],
    negated: bool = False,
) -> str:
    assertions: list[str] = []
    for conjunct in property_conjuncts:
        property_name = str(conjunct["property"])
        degree = conjunct.get("degree")
        property_expr = (
            f"degree_property({degree}, {property_name})"
            if degree is not None
            else property_name
        )
        assertions.append(f"holds_property({subject}, {property_expr})")
    proposition = assertions[0]
    for next_assertion in assertions[1:]:
        proposition = f"and_T({proposition}, {next_assertion})"
    if negated:
        proposition = f"not_T({proposition})"
    for modifier in time_modifiers:
        proposition = f"{modifier['operator']}_T({modifier['argument']}, {proposition})"
    return proposition


def render_copular_property_coq(
    definition_name: str,
    subject: str,
    property_conjuncts: list[dict[str, str | None]],
    time_modifiers: list[dict[str, str]],
    negated: bool = False,
) -> str:
    assertions: list[str] = []
    for conjunct in property_conjuncts:
        property_name = str(conjunct["property"])
        degree = conjunct.get("degree")
        property_expr = (
            f"(degree_property {degree} {property_name})"
            if degree is not None
            else property_name
        )
        assertions.append(f"holds_property {subject} {property_expr}")
    proposition = assertions[0]
    for next_assertion in assertions[1:]:
        proposition = f"and_T ({proposition}) ({next_assertion})"
    if negated:
        proposition = f"not_T ({proposition})"
    for modifier in time_modifiers:
        proposition = f"{modifier['operator']}_T {modifier['argument']} ({proposition})"
    property_names = list(dict.fromkeys(str(item["property"]) for item in property_conjuncts))
    degree_names = list(
        dict.fromkeys(str(item["degree"]) for item in property_conjuncts if item.get("degree") is not None)
    )
    lines = [
        "(* Copular property replacement without an event variable. *)",
        "Parameter Entity : Type.",
        "Parameter Property : Type.",
        "",
        f"Parameter {subject} : Entity.",
    ]
    lines.extend(f"Parameter {property_name} : Property." for property_name in property_names)
    if degree_names:
        lines.extend(
            [
                "Parameter Degree : Type.",
                *(f"Parameter {degree} : Degree." for degree in degree_names),
                "Parameter degree_property : Degree -> Property -> Property.",
            ]
        )
    if len(property_conjuncts) > 1:
        lines.append("Parameter and_T : Prop -> Prop -> Prop.")
    if negated:
        lines.append("Parameter not_T : Prop -> Prop.")
    if time_modifiers:
        lines.extend(
            f"Parameter {modifier['argument']} : Entity."
            for modifier in time_modifiers
        )
        lines.extend(
            [
                "",
                "Parameter at_T : Entity -> Prop -> Prop.",
                "Parameter during_T : Entity -> Prop -> Prop.",
            ]
        )
    lines.extend(
        [
            "",
            "Parameter holds_property : Entity -> Property -> Prop.",
            "",
            f"Definition {definition_name} : Prop :=",
            f"  {proposition}.",
            "",
            f"Check {definition_name}.",
            "",
        ]
    )
    return "\n".join(lines)


def copular_property_pipeline(sentence: str) -> dict[str, Any] | None:
    tokens = tokenize(sentence)
    auxiliary_indices = [
        index for index, token in enumerate(tokens) if token in PASSIVE_AUXILIARIES
    ]
    if len(tokens) < 3 or not auxiliary_indices:
        return None
    auxiliary_index = auxiliary_indices[0]
    auxiliary = tokens[auxiliary_index]
    if auxiliary_index == 0 or auxiliary_index + 1 >= len(tokens):
        return None
    if tokens[auxiliary_index + 1] in PREPOSITIONS:
        return None

    subject = clean_phrase(tokens[:auxiliary_index])
    property_tokens: list[str] = []
    idx = auxiliary_index + 1
    while idx < len(tokens):
        if (
            tokens[idx] in TEMPORAL_ADVERBS
            or temporal_phrase_value(tokens, idx) is not None
            or temporal_prepositional_phrase_value(tokens, idx) is not None
        ):
            break
        property_tokens.append(tokens[idx])
        idx += 1
    if not property_tokens:
        return None

    negated = False
    if property_tokens and property_tokens[0] == "not":
        negated = True
        property_tokens = property_tokens[1:]
    if not property_tokens:
        return None
    property_groups = split_coordinate_tokens(property_tokens)
    if property_groups is None:
        return None
    property_conjuncts: list[dict[str, str | None]] = []
    for group in property_groups:
        degree = None
        if group and group[0] in PROPERTY_DEGREES:
            degree = group[0]
            group = group[1:]
        if not group:
            return None
        if len(group) == 1 and is_passive_participle(group[0]):
            return None
        property_name = clean_phrase(group)
        if property_name in STATE_SCALE_BY_STATE:
            return None
        property_conjuncts.append({"property": property_name, "degree": degree})
    time_modifiers = copular_property_time_modifiers(tokens[idx:])
    if time_modifiers is None:
        return None

    ast = copular_property_ast(
        subject,
        property_conjuncts,
        auxiliary,
        time_modifiers,
        negated=negated,
    )
    type_check = check_copular_property_ast(ast)
    definition_name = f"property_{property_conjuncts[0]['property']}_assertion"
    typed_replacement = render_copular_property_translation(
        subject,
        property_conjuncts,
        time_modifiers,
        negated=negated,
    )
    coq_code = render_copular_property_coq(
        definition_name,
        subject,
        property_conjuncts,
        time_modifiers,
        negated=negated,
    )
    return {
        "kind": "copular_property",
        "input_sentence": sentence,
        "event_semantics": {
            "analysis": "copular-property",
            "source": sentence,
            "event_style_reference": (
                f"Property({subject}, {property_name}) without Agent(e, {subject})"
            ),
            "typed_replacement": typed_replacement,
        },
        "dependent_type_translation": typed_replacement,
        "ast": ast,
        "type_check": {
            **type_check,
            "note": (
                "A copular property is represented as Entity -> Property -> Prop; "
                "registered states and passive participles are handled by more "
                "specific construction rules."
            ),
        },
        "coq_code": coq_code,
    }


def predicate_coordination_ast(
    subject: str,
    predicates: list[dict[str, str]],
    modifiers: list[dict[str, Any]],
    time_modifiers: list[dict[str, str]],
    connective: str = "and_T",
) -> dict[str, Any]:
    return {
        "kind": "predicate_coordination",
        "subject": {"name": subject, "type": "Entity"},
        "predicates": predicates,
        "modifiers": modifiers,
        "connective": connective,
        "connective_type": (
            "PropT -> PropT -> PropT" if modifiers else "Prop -> Prop -> Prop"
        ),
        "time_modifiers": time_modifiers,
    }


def check_predicate_coordination_ast(ast: dict[str, Any]) -> dict[str, Any]:
    errors: list[str] = []
    if ast.get("kind") != "predicate_coordination":
        errors.append("ast.kind must be predicate_coordination")
    modifiers = ast.get("modifiers")
    has_modifiers = isinstance(modifiers, list) and bool(modifiers)
    expected_predicate_type = (
        "forall n : nat, ModifierSeq n -> Entity -> PropT"
        if has_modifiers
        else "Entity -> Prop"
    )

    subject = ast.get("subject")
    if not isinstance(subject, dict):
        errors.append("predicate coordination subject must be an object")
    else:
        if not isinstance(subject.get("name"), str) or not subject.get("name"):
            errors.append("predicate coordination subject.name must be a non-empty string")
        if subject.get("type") != "Entity":
            errors.append("predicate coordination subject must have type Entity")

    predicates = ast.get("predicates")
    if not isinstance(predicates, list) or len(predicates) != 2:
        errors.append("predicate coordination predicates must contain exactly two items")
    else:
        for index, predicate in enumerate(predicates):
            if not isinstance(predicate, dict):
                errors.append(f"predicate coordination predicates[{index}] must be an object")
                continue
            surface = predicate.get("surface")
            if not isinstance(surface, str) or not surface:
                errors.append(
                    f"predicate coordination predicates[{index}].surface must be a non-empty string"
                )
            name = predicate.get("name")
            if not isinstance(name, str) or not name:
                errors.append(
                    f"predicate coordination predicates[{index}].name must be a non-empty string"
                )
            elif surface and lemma_verb(str(surface)) != name:
                errors.append(
                    f"predicate coordination predicates[{index}].name must match its surface lemma"
                )
            if "negated" in predicate and not isinstance(predicate["negated"], bool):
                errors.append(
                    f"predicate coordination predicates[{index}].negated must be boolean"
                )
            if predicate.get("predicate_type") != expected_predicate_type:
                errors.append(
                    "predicate coordination "
                    f"predicates[{index}] must have type {expected_predicate_type}"
                )

    if ast.get("connective") not in {"and_T", "or_T"}:
        errors.append("predicate coordination connective must be and_T or or_T")
    expected_connective_type = (
        "PropT -> PropT -> PropT" if has_modifiers else "Prop -> Prop -> Prop"
    )
    if ast.get("connective_type") != expected_connective_type:
        errors.append(
            "predicate coordination connective must have type "
            f"{expected_connective_type}"
        )

    check_coordination_modifiers(
        errors,
        modifiers,
        "predicate coordination",
    )

    time_modifiers = ast.get("time_modifiers")
    if not isinstance(time_modifiers, list):
        errors.append("predicate coordination time_modifiers must be a list")
    else:
        for index, modifier in enumerate(time_modifiers):
            if not isinstance(modifier, dict):
                errors.append(f"predicate coordination time_modifiers[{index}] must be an object")
                continue
            if modifier.get("operator") not in {"at", "during"}:
                errors.append(
                    f"predicate coordination time_modifiers[{index}].operator must be at or during"
                )
            if not isinstance(modifier.get("argument"), str) or not modifier.get("argument"):
                errors.append(
                    f"predicate coordination time_modifiers[{index}].argument must be a non-empty string"
                )

    return {
        "ok": not errors,
        "type": "Prop" if not errors else None,
        "errors": errors,
    }


def render_predicate_coordination_translation(ast: dict[str, Any]) -> str:
    subject = ast["subject"]["name"]
    predicates = ast["predicates"]
    modifiers = ast.get("modifiers", [])
    if modifiers:
        modifier_args = readable_modifier_arguments(modifiers)
        modifier_count = len(modifiers)
        left = f"{predicates[0]['name']}({modifier_count})({modifier_args}, {subject})"
        right = f"{predicates[1]['name']}({modifier_count})({modifier_args}, {subject})"
    else:
        left = f"{predicates[0]['name']}({subject})"
        right = f"{predicates[1]['name']}({subject})"
    left = wrap_negated_translation(left, bool(predicates[0].get("negated")))
    right = wrap_negated_translation(right, bool(predicates[1].get("negated")))
    proposition = f"{ast['connective']}({left}, {right})"
    for modifier in ast["time_modifiers"]:
        proposition = f"{modifier['operator']}_T({modifier['argument']}, {proposition})"
    return proposition


def render_predicate_coordination_coq(
    definition_name: str,
    ast: dict[str, Any],
) -> str:
    subject = ast["subject"]["name"]
    predicates = ast["predicates"]
    modifiers = ast.get("modifiers", [])
    if modifiers:
        modifier_count = len(modifiers)
        modifier_sequence = coq_modifier_sequence(modifiers)
        left = f"{predicates[0]['name']} {modifier_count} {modifier_sequence} {subject}"
        right = f"{predicates[1]['name']} {modifier_count} {modifier_sequence} {subject}"
    else:
        left = f"{predicates[0]['name']} {subject}"
        right = f"{predicates[1]['name']} {subject}"
    left = wrap_negated_coq(left, bool(predicates[0].get("negated")))
    right = wrap_negated_coq(right, bool(predicates[1].get("negated")))
    proposition = f"{ast['connective']} ({left}) ({right})"
    for modifier in ast["time_modifiers"]:
        proposition = f"{modifier['operator']}_T {modifier['argument']} ({proposition})"
    predicate_names = list(dict.fromkeys(predicate["name"] for predicate in predicates))
    lines = [
        "(* Same-subject predicate coordination without event variables. *)",
        "Parameter Entity : Type.",
    ]
    if modifiers:
        lines.extend(
            [
                "Definition PropT : Type := Prop.",
                "Definition Adv : Type := (Entity -> PropT) -> Entity -> PropT.",
                "Parameter ModifierSeq : nat -> Type.",
                "Parameter mods_nil : ModifierSeq 0.",
                "Parameter mods_cons : forall n : nat, Adv -> ModifierSeq n -> ModifierSeq (S n).",
            ]
        )
        lines.extend(f"Parameter {name} : Adv." for name in unique_names([
            modifier["name"] for modifier in modifiers
        ]))
    lines.extend(["", f"Parameter {subject} : Entity."])
    if modifiers:
        lines.extend(
            f"Parameter {predicate} : forall n : nat, ModifierSeq n -> Entity -> PropT."
            for predicate in predicate_names
        )
        if any(predicate.get("negated") for predicate in predicates):
            lines.append("Parameter not_T : PropT -> PropT.")
        lines.append(f"Parameter {ast['connective']} : PropT -> PropT -> PropT.")
    else:
        lines.extend(f"Parameter {predicate} : Entity -> Prop." for predicate in predicate_names)
        if any(predicate.get("negated") for predicate in predicates):
            lines.append("Parameter not_T : Prop -> Prop.")
        lines.append(f"Parameter {ast['connective']} : Prop -> Prop -> Prop.")
    if ast["time_modifiers"]:
        lines.extend(
            f"Parameter {name} : Entity."
            for name in unique_names([
                modifier["argument"] for modifier in ast["time_modifiers"]
            ])
        )
        lines.extend(
            [
                "",
                "Parameter at_T : Entity -> Prop -> Prop.",
                "Parameter during_T : Entity -> Prop -> Prop.",
            ]
        )
    lines.extend(
        [
            "",
            f"Definition {definition_name} : Prop :=",
            f"  {proposition}.",
            "",
            f"Check {definition_name}.",
            "",
        ]
    )
    return "\n".join(lines)


def subject_coordination_ast(
    subjects: list[str],
    predicate: dict[str, str],
    modifiers: list[dict[str, Any]],
    time_modifiers: list[dict[str, str]],
    connective: str = "and_T",
) -> dict[str, Any]:
    return {
        "kind": "subject_coordination",
        "subjects": [{"name": subject, "type": "Entity"} for subject in subjects],
        "predicate": predicate,
        "modifiers": modifiers,
        "connective": connective,
        "connective_type": (
            "PropT -> PropT -> PropT" if modifiers else "Prop -> Prop -> Prop"
        ),
        "time_modifiers": time_modifiers,
    }


def check_subject_coordination_ast(ast: dict[str, Any]) -> dict[str, Any]:
    errors: list[str] = []
    if ast.get("kind") != "subject_coordination":
        errors.append("ast.kind must be subject_coordination")
    modifiers = ast.get("modifiers")
    has_modifiers = isinstance(modifiers, list) and bool(modifiers)
    expected_predicate_type = (
        "forall n : nat, ModifierSeq n -> Entity -> PropT"
        if has_modifiers
        else "Entity -> Prop"
    )

    subjects = ast.get("subjects")
    if not isinstance(subjects, list) or len(subjects) != 2:
        errors.append("subject coordination subjects must contain exactly two items")
    else:
        for index, subject in enumerate(subjects):
            if not isinstance(subject, dict):
                errors.append(f"subject coordination subjects[{index}] must be an object")
                continue
            if not isinstance(subject.get("name"), str) or not subject.get("name"):
                errors.append(
                    f"subject coordination subjects[{index}].name must be a non-empty string"
                )
            if subject.get("type") != "Entity":
                errors.append(f"subject coordination subjects[{index}] must have type Entity")

    predicate = ast.get("predicate")
    if not isinstance(predicate, dict):
        errors.append("subject coordination predicate must be an object")
    else:
        surface = predicate.get("surface")
        name = predicate.get("name")
        if not isinstance(surface, str) or not surface:
            errors.append("subject coordination predicate.surface must be a non-empty string")
        if not isinstance(name, str) or not name:
            errors.append("subject coordination predicate.name must be a non-empty string")
        elif surface and lemma_verb(str(surface)) != name:
            errors.append("subject coordination predicate.name must match its surface lemma")
        if predicate.get("predicate_type") != expected_predicate_type:
            errors.append(
                f"subject coordination predicate must have type {expected_predicate_type}"
            )

    if ast.get("connective") not in {"and_T", "or_T"}:
        errors.append("subject coordination connective must be and_T or or_T")
    expected_connective_type = (
        "PropT -> PropT -> PropT" if has_modifiers else "Prop -> Prop -> Prop"
    )
    if ast.get("connective_type") != expected_connective_type:
        errors.append(
            "subject coordination connective must have type "
            f"{expected_connective_type}"
        )

    check_coordination_modifiers(errors, modifiers, "subject coordination")
    check_time_modifiers(errors, ast.get("time_modifiers"), "subject coordination")

    return {
        "ok": not errors,
        "type": "Prop" if not errors else None,
        "errors": errors,
    }


def render_subject_coordination_translation(ast: dict[str, Any]) -> str:
    predicate = ast["predicate"]["name"]
    subjects = [subject["name"] for subject in ast["subjects"]]
    modifiers = ast.get("modifiers", [])
    if modifiers:
        modifier_args = readable_modifier_arguments(modifiers)
        modifier_count = len(modifiers)
        left = f"{predicate}({modifier_count})({modifier_args}, {subjects[0]})"
        right = f"{predicate}({modifier_count})({modifier_args}, {subjects[1]})"
    else:
        left = f"{predicate}({subjects[0]})"
        right = f"{predicate}({subjects[1]})"
    proposition = f"{ast['connective']}({left}, {right})"
    for modifier in ast["time_modifiers"]:
        proposition = f"{modifier['operator']}_T({modifier['argument']}, {proposition})"
    return proposition


def render_subject_coordination_coq(
    definition_name: str,
    ast: dict[str, Any],
) -> str:
    predicate = ast["predicate"]["name"]
    subjects = [subject["name"] for subject in ast["subjects"]]
    modifiers = ast.get("modifiers", [])
    if modifiers:
        modifier_count = len(modifiers)
        modifier_sequence = coq_modifier_sequence(modifiers)
        left = f"{predicate} {modifier_count} {modifier_sequence} {subjects[0]}"
        right = f"{predicate} {modifier_count} {modifier_sequence} {subjects[1]}"
    else:
        left = f"{predicate} {subjects[0]}"
        right = f"{predicate} {subjects[1]}"
    proposition = f"{ast['connective']} ({left}) ({right})"
    for modifier in ast["time_modifiers"]:
        proposition = f"{modifier['operator']}_T {modifier['argument']} ({proposition})"
    lines = [
        "(* Subject coordination without event variables. *)",
        "Parameter Entity : Type.",
    ]
    if modifiers:
        lines.extend(
            [
                "Definition PropT : Type := Prop.",
                "Definition Adv : Type := (Entity -> PropT) -> Entity -> PropT.",
                "Parameter ModifierSeq : nat -> Type.",
                "Parameter mods_nil : ModifierSeq 0.",
                "Parameter mods_cons : forall n : nat, Adv -> ModifierSeq n -> ModifierSeq (S n).",
            ]
        )
        lines.extend(f"Parameter {name} : Adv." for name in unique_names([
            modifier["name"] for modifier in modifiers
        ]))
    lines.append("")
    lines.extend(f"Parameter {subject} : Entity." for subject in unique_names(subjects))
    if modifiers:
        lines.append(f"Parameter {predicate} : forall n : nat, ModifierSeq n -> Entity -> PropT.")
        lines.append(f"Parameter {ast['connective']} : PropT -> PropT -> PropT.")
    else:
        lines.append(f"Parameter {predicate} : Entity -> Prop.")
        lines.append(f"Parameter {ast['connective']} : Prop -> Prop -> Prop.")
    if ast["time_modifiers"]:
        lines.extend(
            f"Parameter {name} : Entity."
            for name in unique_names([
                modifier["argument"] for modifier in ast["time_modifiers"]
            ])
        )
        lines.extend(
            [
                "",
                "Parameter at_T : Entity -> Prop -> Prop.",
                "Parameter during_T : Entity -> Prop -> Prop.",
            ]
        )
    lines.extend(
        [
            "",
            f"Definition {definition_name} : Prop :=",
            f"  {proposition}.",
            "",
            f"Check {definition_name}.",
            "",
        ]
    )
    return "\n".join(lines)


def subject_coordination_pipeline(sentence: str) -> dict[str, Any] | None:
    tokens, fronted_time_modifiers = split_fronted_time_modifiers(tokenize(sentence))
    tokens, fronted_adv_modifiers = split_fronted_adv_modifiers(tokens)
    leading_both = bool(tokens and tokens[0] == "both")
    if leading_both:
        if "and" not in tokens:
            return None
        tokens = tokens[1:]

    coordination = single_boolean_coordinator(tokens)
    if coordination is None:
        return None
    coordinator, coordinator_index = coordination
    if leading_both and coordinator != "and":
        return None
    left_subject_tokens = tokens[:coordinator_index]
    right_side_tokens = tokens[coordinator_index + 1 :]
    if not left_subject_tokens or len(right_side_tokens) < 2:
        return None

    predicate_offsets = [
        index
        for index, token in enumerate(right_side_tokens)
        if is_likely_surface_verb(token)
    ]
    if len(predicate_offsets) != 1:
        return None
    predicate_offset = predicate_offsets[0]
    if predicate_offset == 0:
        return None
    right_subject_tokens = right_side_tokens[:predicate_offset]
    predicate_surface = right_side_tokens[predicate_offset]

    trailing_modifiers = split_shared_adv_and_time_modifiers(
        right_side_tokens[predicate_offset + 1 :]
    )
    if trailing_modifiers is None:
        return None
    trailing_adv_modifiers, trailing_time_modifiers = trailing_modifiers
    shared_adv_modifiers = [*fronted_adv_modifiers, *trailing_adv_modifiers]
    time_modifiers = [*fronted_time_modifiers, *trailing_time_modifiers]

    subjects = [clean_phrase(left_subject_tokens), clean_phrase(right_subject_tokens)]
    if any(subject == "entity" for subject in subjects):
        return None
    predicate_name = lemma_verb(predicate_surface)
    predicate = {
        "surface": predicate_surface,
        "name": predicate_name,
        "predicate_type": (
            "forall n : nat, ModifierSeq n -> Entity -> PropT"
            if shared_adv_modifiers
            else "Entity -> Prop"
        ),
    }
    ast = subject_coordination_ast(
        subjects,
        predicate,
        shared_adv_modifiers,
        time_modifiers,
        connective_for_coordinator(coordinator),
    )
    type_check = check_subject_coordination_ast(ast)
    typed_replacement = render_subject_coordination_translation(ast)
    coq_code = render_subject_coordination_coq(
        f"subject_coordination_{predicate_name}",
        ast,
    )
    return {
        "kind": "subject_coordination",
        "input_sentence": sentence,
        "event_semantics": {
            "analysis": "subject-coordination",
            "source": sentence,
            "event_style_reference": (
                f"{predicate_name}(e1) with Agent(e1, {subjects[0]}) and "
                f"{predicate_name}(e2) with Agent(e2, {subjects[1]})"
            ),
            "typed_replacement": typed_replacement,
        },
        "dependent_type_translation": typed_replacement,
        "ast": ast,
        "type_check": type_check,
        "coq_code": coq_code,
        "construction_summary": (
            f"Subject coordination shares {predicate_name} across "
            f"{subjects[0]} and {subjects[1]} without introducing event variables."
        ),
    }


def transitive_subject_coordination_ast(
    subjects: list[str],
    predicate: dict[str, str],
    obj: dict[str, str],
    modifiers: list[dict[str, Any]],
    time_modifiers: list[dict[str, str]],
    connective: str = "and_T",
) -> dict[str, Any]:
    return {
        "kind": "transitive_subject_coordination",
        "subjects": [{"name": subject, "type": "Entity"} for subject in subjects],
        "predicate": predicate,
        "object": obj,
        "modifiers": modifiers,
        "connective": connective,
        "connective_type": (
            "PropT -> PropT -> PropT" if modifiers else "Prop -> Prop -> Prop"
        ),
        "time_modifiers": time_modifiers,
    }


def check_transitive_subject_coordination_ast(ast: dict[str, Any]) -> dict[str, Any]:
    errors: list[str] = []
    if ast.get("kind") != "transitive_subject_coordination":
        errors.append("ast.kind must be transitive_subject_coordination")
    modifiers = ast.get("modifiers")
    has_modifiers = isinstance(modifiers, list) and bool(modifiers)

    subjects = ast.get("subjects")
    if not isinstance(subjects, list) or len(subjects) != 2:
        errors.append("transitive subject coordination subjects must contain exactly two items")
    else:
        for index, subject in enumerate(subjects):
            if not isinstance(subject, dict):
                errors.append(
                    f"transitive subject coordination subjects[{index}] must be an object"
                )
                continue
            if not isinstance(subject.get("name"), str) or not subject.get("name"):
                errors.append(
                    "transitive subject coordination "
                    f"subjects[{index}].name must be a non-empty string"
                )
            if subject.get("type") != "Entity":
                errors.append(
                    f"transitive subject coordination subjects[{index}] must have type Entity"
                )

    obj = ast.get("object")
    object_type = None
    if not isinstance(obj, dict):
        errors.append("transitive subject coordination object must be an object")
    else:
        if not isinstance(obj.get("name"), str) or not obj.get("name"):
            errors.append("transitive subject coordination object.name must be non-empty")
        if not isinstance(obj.get("type"), str) or not obj.get("type"):
            errors.append("transitive subject coordination object.type must be non-empty")
        else:
            object_type = str(obj["type"])

    expected_predicate_type = None
    if object_type is not None:
        expected_predicate_type = (
            f"forall n : nat, ModifierSeq n -> Entity -> {object_type} -> PropT"
            if has_modifiers
            else f"Entity -> {object_type} -> Prop"
        )
    predicate = ast.get("predicate")
    if not isinstance(predicate, dict):
        errors.append("transitive subject coordination predicate must be an object")
    else:
        surface = predicate.get("surface")
        name = predicate.get("name")
        if not isinstance(surface, str) or not surface:
            errors.append(
                "transitive subject coordination predicate.surface must be a non-empty string"
            )
        if not isinstance(name, str) or not name:
            errors.append(
                "transitive subject coordination predicate.name must be a non-empty string"
            )
        elif surface and lemma_verb(str(surface)) != name:
            errors.append(
                "transitive subject coordination predicate.name must match its surface lemma"
            )
        if expected_predicate_type is not None and predicate.get("predicate_type") != expected_predicate_type:
            errors.append(
                "transitive subject coordination predicate must have type "
                f"{expected_predicate_type}"
            )

    if ast.get("connective") not in {"and_T", "or_T"}:
        errors.append("transitive subject coordination connective must be and_T or or_T")
    expected_connective_type = (
        "PropT -> PropT -> PropT" if has_modifiers else "Prop -> Prop -> Prop"
    )
    if ast.get("connective_type") != expected_connective_type:
        errors.append(
            "transitive subject coordination connective must have type "
            f"{expected_connective_type}"
        )

    check_coordination_modifiers(errors, modifiers, "transitive subject coordination")
    check_time_modifiers(errors, ast.get("time_modifiers"), "transitive subject coordination")

    return {
        "ok": not errors,
        "type": "Prop" if not errors else None,
        "errors": errors,
    }


def render_transitive_subject_coordination_translation(ast: dict[str, Any]) -> str:
    predicate = ast["predicate"]["name"]
    subjects = [subject["name"] for subject in ast["subjects"]]
    obj = ast["object"]["name"]
    modifiers = ast.get("modifiers", [])
    if modifiers:
        modifier_args = readable_modifier_arguments(modifiers)
        modifier_count = len(modifiers)
        left = f"{predicate}({modifier_count})({modifier_args}, {subjects[0]}, {obj})"
        right = f"{predicate}({modifier_count})({modifier_args}, {subjects[1]}, {obj})"
    else:
        left = f"{predicate}({subjects[0]}, {obj})"
        right = f"{predicate}({subjects[1]}, {obj})"
    proposition = f"{ast['connective']}({left}, {right})"
    for modifier in ast["time_modifiers"]:
        proposition = f"{modifier['operator']}_T({modifier['argument']}, {proposition})"
    return proposition


def render_transitive_subject_coordination_coq(
    definition_name: str,
    ast: dict[str, Any],
) -> str:
    predicate = ast["predicate"]["name"]
    subjects = [subject["name"] for subject in ast["subjects"]]
    obj = ast["object"]["name"]
    object_type = ast["object"]["type"]
    modifiers = ast.get("modifiers", [])
    if modifiers:
        modifier_count = len(modifiers)
        modifier_sequence = coq_modifier_sequence(modifiers)
        left = f"{predicate} {modifier_count} {modifier_sequence} {subjects[0]} {obj}"
        right = f"{predicate} {modifier_count} {modifier_sequence} {subjects[1]} {obj}"
    else:
        left = f"{predicate} {subjects[0]} {obj}"
        right = f"{predicate} {subjects[1]} {obj}"
    proposition = f"{ast['connective']} ({left}) ({right})"
    for modifier in ast["time_modifiers"]:
        proposition = f"{modifier['operator']}_T {modifier['argument']} ({proposition})"
    lines = [
        "(* Transitive subject coordination without event variables. *)",
        "Parameter Entity : Type.",
        f"Parameter {object_type} : Type.",
    ]
    if modifiers:
        lines.extend(
            [
                "Definition PropT : Type := Prop.",
                "Definition Adv : Type := (Entity -> PropT) -> Entity -> PropT.",
                "Parameter ModifierSeq : nat -> Type.",
                "Parameter mods_nil : ModifierSeq 0.",
                "Parameter mods_cons : forall n : nat, Adv -> ModifierSeq n -> ModifierSeq (S n).",
            ]
        )
        lines.extend(f"Parameter {name} : Adv." for name in unique_names([
            modifier["name"] for modifier in modifiers
        ]))
    lines.append("")
    lines.extend(f"Parameter {subject} : Entity." for subject in unique_names(subjects))
    lines.append(f"Parameter {obj} : {object_type}.")
    if modifiers:
        lines.append(
            f"Parameter {predicate} : forall n : nat, "
            f"ModifierSeq n -> Entity -> {object_type} -> PropT."
        )
        lines.append(f"Parameter {ast['connective']} : PropT -> PropT -> PropT.")
    else:
        lines.append(f"Parameter {predicate} : Entity -> {object_type} -> Prop.")
        lines.append(f"Parameter {ast['connective']} : Prop -> Prop -> Prop.")
    if ast["time_modifiers"]:
        lines.extend(
            f"Parameter {name} : Entity."
            for name in unique_names([
                modifier["argument"] for modifier in ast["time_modifiers"]
            ])
        )
        lines.extend(
            [
                "",
                "Parameter at_T : Entity -> Prop -> Prop.",
                "Parameter during_T : Entity -> Prop -> Prop.",
            ]
        )
    lines.extend(
        [
            "",
            f"Definition {definition_name} : Prop :=",
            f"  {proposition}.",
            "",
            f"Check {definition_name}.",
            "",
        ]
    )
    return "\n".join(lines)


def transitive_subject_coordination_pipeline(sentence: str) -> dict[str, Any] | None:
    tokens, fronted_time_modifiers = split_fronted_time_modifiers(tokenize(sentence))
    tokens, fronted_adv_modifiers = split_fronted_adv_modifiers(tokens)
    leading_both = bool(tokens and tokens[0] == "both")
    if leading_both:
        if "and" not in tokens:
            return None
        tokens = tokens[1:]

    coordination = single_boolean_coordinator(tokens)
    if coordination is None:
        return None
    coordinator, coordinator_index = coordination
    if leading_both and coordinator != "and":
        return None
    left_subject_tokens = tokens[:coordinator_index]
    right_side_tokens = tokens[coordinator_index + 1 :]
    if not left_subject_tokens or len(right_side_tokens) < 3:
        return None

    predicate_offsets = [
        index
        for index, token in enumerate(right_side_tokens)
        if is_likely_transitive_verb(token)
    ]
    if len(predicate_offsets) != 1:
        return None
    predicate_offset = predicate_offsets[0]
    if predicate_offset == 0:
        return None
    right_subject_tokens = right_side_tokens[:predicate_offset]
    predicate_surface = right_side_tokens[predicate_offset]
    predicate_name = lemma_verb(predicate_surface)

    object_tail = split_object_tokens_and_modifiers(right_side_tokens[predicate_offset + 1 :])
    if object_tail is None:
        return None
    object_tokens, trailing_adv_modifiers, trailing_time_modifiers = object_tail
    obj = clean_phrase(object_tokens)
    if obj == "entity":
        return None
    object_type = object_type_for_transitive_predicate(predicate_name)

    shared_adv_modifiers = [*fronted_adv_modifiers, *trailing_adv_modifiers]
    time_modifiers = [*fronted_time_modifiers, *trailing_time_modifiers]
    subjects = [clean_phrase(left_subject_tokens), clean_phrase(right_subject_tokens)]
    if any(subject == "entity" for subject in subjects):
        return None
    predicate = {
        "surface": predicate_surface,
        "name": predicate_name,
        "predicate_type": (
            f"forall n : nat, ModifierSeq n -> Entity -> {object_type} -> PropT"
            if shared_adv_modifiers
            else f"Entity -> {object_type} -> Prop"
        ),
    }
    ast = transitive_subject_coordination_ast(
        subjects,
        predicate,
        {"name": obj, "type": object_type},
        shared_adv_modifiers,
        time_modifiers,
        connective_for_coordinator(coordinator),
    )
    type_check = check_transitive_subject_coordination_ast(ast)
    typed_replacement = render_transitive_subject_coordination_translation(ast)
    coq_code = render_transitive_subject_coordination_coq(
        f"transitive_subject_coordination_{predicate_name}",
        ast,
    )
    return {
        "kind": "transitive_subject_coordination",
        "input_sentence": sentence,
        "event_semantics": {
            "analysis": "transitive-subject-coordination",
            "source": sentence,
            "event_style_reference": (
                f"{predicate_name}(e1) with Agent(e1, {subjects[0]}) and "
                f"Theme(e1, {obj}); {predicate_name}(e2) with "
                f"Agent(e2, {subjects[1]}) and Theme(e2, {obj})"
            ),
            "typed_replacement": typed_replacement,
        },
        "dependent_type_translation": typed_replacement,
        "ast": ast,
        "type_check": type_check,
        "coq_code": coq_code,
        "construction_summary": (
            f"Transitive subject coordination shares {predicate_name}"
            f"({obj} : {object_type}) across {subjects[0]} and {subjects[1]}."
        ),
    }


def object_coordination_ast(
    subject: str,
    predicate: dict[str, str],
    objects: list[dict[str, str]],
    modifiers: list[dict[str, Any]],
    time_modifiers: list[dict[str, str]],
    connective: str = "and_T",
) -> dict[str, Any]:
    return {
        "kind": "object_coordination",
        "subject": {"name": subject, "type": "Entity"},
        "predicate": predicate,
        "objects": objects,
        "modifiers": modifiers,
        "connective": connective,
        "connective_type": (
            "PropT -> PropT -> PropT" if modifiers else "Prop -> Prop -> Prop"
        ),
        "time_modifiers": time_modifiers,
    }


def check_object_coordination_ast(ast: dict[str, Any]) -> dict[str, Any]:
    errors: list[str] = []
    if ast.get("kind") != "object_coordination":
        errors.append("ast.kind must be object_coordination")
    modifiers = ast.get("modifiers")
    has_modifiers = isinstance(modifiers, list) and bool(modifiers)

    subject = ast.get("subject")
    if not isinstance(subject, dict):
        errors.append("object coordination subject must be an object")
    else:
        if not isinstance(subject.get("name"), str) or not subject.get("name"):
            errors.append("object coordination subject.name must be a non-empty string")
        if subject.get("type") != "Entity":
            errors.append("object coordination subject must have type Entity")

    objects = ast.get("objects")
    object_type = None
    if not isinstance(objects, list) or len(objects) != 2:
        errors.append("object coordination objects must contain exactly two items")
    else:
        object_declarations: list[tuple[str, str]] = []
        for index, obj in enumerate(objects):
            if not isinstance(obj, dict):
                errors.append(f"object coordination objects[{index}] must be an object")
                continue
            object_name = obj.get("name")
            current_type = obj.get("type")
            if not isinstance(object_name, str) or not object_name:
                errors.append(f"object coordination objects[{index}].name must be non-empty")
            if not isinstance(current_type, str) or not current_type:
                errors.append(f"object coordination objects[{index}].type must be non-empty")
                continue
            object_declarations.append((str(object_name), current_type))
            if object_type is None:
                object_type = current_type
            elif object_type != current_type:
                errors.append(
                    "object coordination objects must share one lexical type: "
                    f"{object_type} vs {current_type}"
                )
        check_declaration_type_conflicts(
            errors,
            object_declarations,
            "object coordination object",
        )

    expected_predicate_type = None
    if object_type is not None:
        expected_predicate_type = (
            f"forall n : nat, ModifierSeq n -> Entity -> {object_type} -> PropT"
            if has_modifiers
            else f"Entity -> {object_type} -> Prop"
        )
    predicate = ast.get("predicate")
    if not isinstance(predicate, dict):
        errors.append("object coordination predicate must be an object")
    else:
        surface = predicate.get("surface")
        name = predicate.get("name")
        if not isinstance(surface, str) or not surface:
            errors.append("object coordination predicate.surface must be a non-empty string")
        if not isinstance(name, str) or not name:
            errors.append("object coordination predicate.name must be a non-empty string")
        elif surface and lemma_verb(str(surface)) != name:
            errors.append("object coordination predicate.name must match its surface lemma")
        if expected_predicate_type is not None and predicate.get("predicate_type") != expected_predicate_type:
            errors.append(
                f"object coordination predicate must have type {expected_predicate_type}"
            )

    if ast.get("connective") not in {"and_T", "or_T"}:
        errors.append("object coordination connective must be and_T or or_T")
    expected_connective_type = (
        "PropT -> PropT -> PropT" if has_modifiers else "Prop -> Prop -> Prop"
    )
    if ast.get("connective_type") != expected_connective_type:
        errors.append(
            "object coordination connective must have type "
            f"{expected_connective_type}"
        )

    check_coordination_modifiers(errors, modifiers, "object coordination")
    check_time_modifiers(errors, ast.get("time_modifiers"), "object coordination")

    return {
        "ok": not errors,
        "type": "Prop" if not errors else None,
        "errors": errors,
    }


def render_object_coordination_translation(ast: dict[str, Any]) -> str:
    subject = ast["subject"]["name"]
    predicate = ast["predicate"]["name"]
    objects = [obj["name"] for obj in ast["objects"]]
    modifiers = ast.get("modifiers", [])
    if modifiers:
        modifier_args = readable_modifier_arguments(modifiers)
        modifier_count = len(modifiers)
        left = f"{predicate}({modifier_count})({modifier_args}, {subject}, {objects[0]})"
        right = f"{predicate}({modifier_count})({modifier_args}, {subject}, {objects[1]})"
    else:
        left = f"{predicate}({subject}, {objects[0]})"
        right = f"{predicate}({subject}, {objects[1]})"
    proposition = f"{ast['connective']}({left}, {right})"
    for modifier in ast["time_modifiers"]:
        proposition = f"{modifier['operator']}_T({modifier['argument']}, {proposition})"
    return proposition


