def manner_mixed_directional_instrument_intransitive_application_details(
    ast: dict[str, Any],
) -> dict[str, Any] | None:
    if ast.get("kind") != "application":
        return None
    modifiers = ast.get("modifiers")
    modifier_vector = ast.get("modifier_vector")
    modifier_roles = ast.get("modifier_roles", {}).get("roles")
    if (
        not isinstance(modifiers, list)
        or len(modifiers) < 4
        or ast.get("adverb_count") != len(modifiers)
        or not isinstance(modifier_vector, dict)
        or modifier_vector.get("length") != len(modifiers)
        or not isinstance(modifier_vector.get("items"), list)
        or len(modifier_vector["items"]) != len(modifiers)
        or not isinstance(modifier_roles, list)
        or len(modifier_roles) != len(modifiers)
    ):
        return None
    semantic_roles = [
        role.get("semantic_role") if isinstance(role, dict) else None
        for role in modifier_roles
    ]
    if semantic_roles[0] != "Manner":
        return None
    tail_roles = semantic_roles[1:]
    directional_roles = {"Source", "Goal"}
    allowed_tail_roles = {"Location", "Instrument", *directional_roles}
    if (
        not tail_roles
        or tail_roles[0] != "Location"
        or "Instrument" not in tail_roles
        or not any(role in directional_roles for role in tail_roles)
        or any(role not in allowed_tail_roles for role in tail_roles)
    ):
        return None

    seen_instrument = False
    seen_directional_after_instrument = False
    directional_after_instrument_count = 0
    directional_to_instrument_count = 0
    previous_tail_role = None
    for role in tail_roles:
        if role in directional_roles and seen_instrument:
            seen_directional_after_instrument = True
            directional_after_instrument_count += 1
        if previous_tail_role in directional_roles and role == "Instrument":
            directional_to_instrument_count += 1
        if role == "Instrument":
            seen_instrument = True
        previous_tail_role = role
    if not seen_directional_after_instrument or directional_to_instrument_count == 0:
        return None

    for index, (modifier, vector_item, role_item, expected_role) in enumerate(
        zip(modifiers, modifier_vector["items"], modifier_roles, semantic_roles)
    ):
        if (
            vector_item.get("modifier") != modifier
            or vector_item.get("tail_length") != len(modifiers) - index - 1
            or role_item.get("modifier") != modifier
            or role_item.get("type") != "Adv"
            or role_item.get("semantic_role") != expected_role
            or role_item.get("source") != "modifier"
        ):
            return None
        surface_lexicon = role_item.get("surface_lexicon")
        if (
            not isinstance(surface_lexicon, dict)
            or surface_lexicon.get("type") != "Adv"
            or surface_lexicon.get("semantic_role") != expected_role
        ):
            return None
    role_details = plain_intransitive_application_details(
        {
            **ast,
            "adverb_count": 0,
            "modifiers": [],
            "modifier_vector": {"kind": "modifier_vector", "length": 0, "items": []},
            "modifier_roles": {"kind": "modifier_roles", "roles": []},
        }
    )
    if role_details is None:
        return None
    return {
        **role_details,
        "modifiers": [str(modifier) for modifier in modifiers],
        "modifier_roles": copy.deepcopy(modifier_roles),
        "semantic_roles": [str(role) for role in semantic_roles],
        "directional_after_instrument_count": directional_after_instrument_count,
        "directional_to_instrument_count": directional_to_instrument_count,
    }


def manner_mixed_directional_instrument_intransitive_predication_pipeline(
    sentence: str,
) -> dict[str, Any] | None:
    try:
        event_semantics = sentence_to_event_semantics(sentence)
        translation = translate(event_semantics)
    except ValueError:
        return None
    ast = translation.get("ast", {})
    if not isinstance(ast, dict) or translation.get("omitted_arguments"):
        return None

    time_modifier = None
    application_ast = ast
    if ast.get("kind") == "time":
        time_arguments = ast.get("arguments")
        body = ast.get("body")
        operator = ast.get("operator")
        if (
            not isinstance(time_arguments, list)
            or len(time_arguments) != 1
            or not isinstance(time_arguments[0], str)
            or not isinstance(operator, str)
            or not isinstance(body, dict)
        ):
            return None
        time_modifier = {
            "operator": operator,
            "argument": time_arguments[0],
        }
        application_ast = body
    elif ast.get("kind") != "application":
        return None

    details = manner_mixed_directional_instrument_intransitive_application_details(
        application_ast
    )
    if details is None:
        return None

    predicate = str(details["predicate"])
    arguments = list(details["arguments"])
    modifiers = [str(modifier) for modifier in details["modifiers"]]
    modifier_roles = copy.deepcopy(details["modifier_roles"])
    semantic_roles = [str(role) for role in details["semantic_roles"]]
    location_modifiers = [
        modifier
        for modifier, role in zip(modifiers, semantic_roles)
        if role == "Location"
    ]
    instrument_modifiers = [
        modifier
        for modifier, role in zip(modifiers, semantic_roles)
        if role == "Instrument"
    ]
    source_modifiers = [
        modifier for modifier, role in zip(modifiers, semantic_roles) if role == "Source"
    ]
    goal_modifiers = [
        modifier for modifier, role in zip(modifiers, semantic_roles) if role == "Goal"
    ]
    directional_modifiers = source_modifiers + goal_modifiers
    scope = (
        "explicit_agent_with_manner_mixed_directional_instrument_adv_sequence_at_time"
        if time_modifier
        else "explicit_agent_with_manner_mixed_directional_instrument_adv_sequence"
    )
    time_summary = (
        f" under {time_modifier['operator']}_T({time_modifier['argument']}, ...)"
        if time_modifier
        else ""
    )
    predication_record = {
        "predicate": predicate,
        "agent": arguments[0],
        "agent_type": "Entity",
        "modifiers": modifiers,
        "modifier_roles": modifier_roles,
        "modifier_role_pattern": semantic_roles,
        "location_modifier_count": len(location_modifiers),
        "location_modifiers": location_modifiers,
        "instrument_modifier_count": len(instrument_modifiers),
        "instrument_modifiers": instrument_modifiers,
        "directional_modifier_count": len(directional_modifiers),
        "directional_modifiers": directional_modifiers,
        "source_modifier_count": len(source_modifiers),
        "source_modifiers": source_modifiers,
        "goal_modifier_count": len(goal_modifiers),
        "goal_modifiers": goal_modifiers,
        "directional_after_instrument_count": int(
            details["directional_after_instrument_count"]
        ),
        "directional_to_instrument_count": int(
            details["directional_to_instrument_count"]
        ),
        "representation": (
            "ModifierSeq-indexed typed unary predicate over one explicit Agent, "
            "one Manner Adv, and a surface-ordered mixed sequence of Location, "
            "Instrument, Source, and Goal Advs"
        ),
    }
    if time_modifier is not None:
        predication_record["time_modifier"] = time_modifier
    coq_code = export_module([translation], "coq")
    return attach_single_semantic_reading(
        {
            "kind": "manner_mixed_directional_instrument_intransitive_predication",
            "input_sentence": sentence,
            "event_semantics": {
                **event_semantics,
                "analysis": (
                    "manner-mixed-directional-instrument-intransitive-predication"
                ),
                "manner_mixed_directional_instrument_intransitive_predication": (
                    predication_record
                ),
            },
            "dependent_type_translation": translation["translation"],
            "result_state_lexicon": translation["result_state_lexicon"],
            "ast": translation["ast"],
            "type_check": translation["type_check"],
            "construction_summary": (
                f"Manner mixed directional-instrument intransitive predication: "
                f"{predicate} is applied to typed Adv modifiers in surface "
                f"order {', '.join(modifiers)}, including "
                f"{len(location_modifiers)} Location Adv modifier(s), "
                f"{len(instrument_modifiers)} Instrument Adv modifier(s), "
                f"{len(source_modifiers)} Source Adv modifier(s), and "
                f"{len(goal_modifiers)} Goal Adv modifier(s), then to explicit "
                f"Entity Agent {arguments[0]} as a ModifierSeq-indexed unary "
                f"predicate{time_summary}, without exporting Event, Agent, or "
                "Theme predicates."
            ),
            "coq_code": coq_code,
        },
        name="manner_mixed_directional_instrument_intransitive_predication_single_reading",
        coq_definition="example_1",
        source="manner_mixed_directional_instrument_intransitive_predication",
        scope=scope,
    )


def plain_transitive_application_details(ast: dict[str, Any]) -> dict[str, Any] | None:
    if ast.get("kind") != "application":
        return None
    if ast.get("adverb_count") != 0 or ast.get("modifiers") != []:
        return None
    if ast.get("modifier_vector", {}).get("length") != 0:
        return None
    if ast.get("modifier_roles", {}).get("roles") != []:
        return None
    arguments = ast.get("arguments")
    role_frame = ast.get("role_frame", {}).get("roles")
    if (
        not isinstance(arguments, list)
        or len(arguments) != 2
        or not isinstance(role_frame, list)
        or len(role_frame) != 2
    ):
        return None
    agent_role = role_frame[0]
    theme_role = role_frame[1]
    if (
        not isinstance(agent_role, dict)
        or agent_role.get("role") != "Agent"
        or agent_role.get("value") != arguments[0]
        or agent_role.get("type") != "Entity"
        or agent_role.get("source") != "explicit"
        or not isinstance(theme_role, dict)
        or theme_role.get("role") != "Theme"
        or theme_role.get("value") != arguments[1]
        or not isinstance(theme_role.get("type"), str)
        or not theme_role.get("type")
        or theme_role.get("source") != "explicit"
    ):
        return None
    return {
        "predicate": str(ast.get("function", "predicate")),
        "arguments": arguments,
        "agent": arguments[0],
        "theme": arguments[1],
        "theme_type": str(theme_role["type"]),
    }


