def surface_parser_coverage_payload() -> dict[str, Any]:
    witness_generation_spec = modified_transitive_surface_witness_generation_spec()
    slot_probe_payload = modified_transitive_surface_slot_probe_payload()
    intransitive_witness_generation_spec = (
        manner_location_intransitive_surface_witness_generation_spec()
    )
    intransitive_slot_probe_payload = (
        manner_location_intransitive_surface_slot_probe_payload()
    )
    mixed_role_witness_generation_spec = (
        mixed_role_intransitive_surface_witness_generation_spec()
    )
    mixed_role_slot_probe_payload = (
        mixed_role_intransitive_surface_slot_probe_payload()
    )
    snapshot_by_rule = {
        str(snapshot.get("rule_id", "")): snapshot
        for snapshot in CERTIFIED_FRAGMENT_SEMANTIC_SNAPSHOTS
        if isinstance(snapshot, dict)
    }
    primary_snapshot = snapshot_by_rule.get("modified_transitive_predication", {})
    primary_ast_summary = CERTIFIED_FRAGMENT_AST_SUMMARY_SNAPSHOTS.get(
        "modified_transitive_predication",
        {},
    )
    modified_transitive_variants = [
        variant
        for variant in REGISTERED_VARIANT_COVERAGE_EXAMPLES
        if variant.get("surface_parser_family") == "modified_transitive_adv_sequence"
        and isinstance(variant.get("modifier_count"), int)
    ]
    verified_examples = [
        {
            "rule_id": "modified_transitive_predication",
            "variant_id": "primary_modified_transitive_predication",
            "sentence": CONSTRUCTION_RULE_EXAMPLES["modified_transitive_predication"],
            "modifier_count": MODIFIED_TRANSITIVE_PRIMARY_MODIFIER_COUNT,
            "time_wrapped": False,
            "source": "registered_primary_example",
            "boundary_status": "registered_construction_example",
            "expected_event_analysis": str(
                primary_snapshot.get("expected_event_analysis", ""),
            ),
            "expected_ast_kind": str(primary_ast_summary.get("kind", "")),
            "expected_dependent_type_fragments": [
                str(fragment)
                for fragment in primary_snapshot.get(
                    "expected_dependent_type_fragments",
                    [],
                )
            ],
        },
    ]
    verified_examples.extend(
        {
            "rule_id": str(variant.get("rule_id", "")),
            "variant_id": str(variant.get("variant_id", "")),
            "sentence": str(variant.get("sentence", "")),
            "modifier_count": int(variant["modifier_count"]),
            "time_wrapped": variant.get("time_wrapped") is True,
            "source": "registered_variant_example",
            "boundary_status": str(variant.get("boundary_status", "")),
            "expected_event_analysis": str(
                variant.get("expected_event_analysis", ""),
            ),
            "expected_ast_kind": str(variant.get("expected_ast_kind", "")),
            "expected_dependent_type_fragments": [
                str(fragment)
                for fragment in variant.get(
                    "expected_dependent_type_fragments",
                    [],
                )
            ],
        }
        for variant in modified_transitive_variants
    )
    timed_counts = sorted(
        {
            int(variant["modifier_count"])
            for variant in modified_transitive_variants
            if variant.get("time_wrapped") is True
        },
    )
    untimed_counts = sorted(
        {MODIFIED_TRANSITIVE_PRIMARY_MODIFIER_COUNT}
        | {
            int(variant["modifier_count"])
            for variant in modified_transitive_variants
            if variant.get("time_wrapped") is False
        },
    )
    verified_counts = sorted(
        {MODIFIED_TRANSITIVE_PRIMARY_MODIFIER_COUNT}
        | set(timed_counts)
        | set(untimed_counts),
    )
    intransitive_verified_examples = (
        manner_location_intransitive_surface_witnesses_from_spec(
            intransitive_witness_generation_spec,
        )
    )
    intransitive_timed_counts = sorted(
        {
            int(example["modifier_count"])
            for example in intransitive_verified_examples
            if example.get("time_wrapped") is True
        },
    )
    intransitive_untimed_counts = sorted(
        {
            int(example["modifier_count"])
            for example in intransitive_verified_examples
            if example.get("time_wrapped") is False
        },
    )
    intransitive_verified_counts = sorted(
        set(intransitive_timed_counts) | set(intransitive_untimed_counts),
    )
    mixed_role_verified_examples = mixed_role_intransitive_surface_witnesses_from_spec(
        mixed_role_witness_generation_spec,
    )
    mixed_role_timed_counts = sorted(
        {
            int(example["modifier_count"])
            for example in mixed_role_verified_examples
            if example.get("time_wrapped") is True
        },
    )
    mixed_role_untimed_counts = sorted(
        {
            int(example["modifier_count"])
            for example in mixed_role_verified_examples
            if example.get("time_wrapped") is False
        },
    )
    mixed_role_verified_counts = sorted(
        set(mixed_role_timed_counts) | set(mixed_role_untimed_counts),
    )
    return {
        "modified_transitive_adv_sequence": {
            "rule_id": "modified_transitive_predication",
            "type_principle": "non_empty_modifier_sequence",
            "type_family": "forall n : nat, ModifierSeq n -> Entity -> Entity -> PropT",
            "type_level_open_ended": True,
            "surface_parser_claim": "registered_examples_only",
            "full_surface_parser_certification": False,
            "primary_modifier_count": MODIFIED_TRANSITIVE_PRIMARY_MODIFIER_COUNT,
            "verified_modifier_counts": verified_counts,
            "verified_timed_modifier_counts": timed_counts,
            "verified_untimed_modifier_counts": untimed_counts,
            "max_verified_modifier_count": max(verified_counts) if verified_counts else 0,
            "verified_example_count": len(verified_examples),
            "verified_examples": verified_examples,
            "witness_generation_spec": witness_generation_spec,
            "slot_probe_examples": slot_probe_payload,
            "boundary_note": (
                "The dependent type family is open-ended in n, but the current "
                "surface parser advertises only the registered and smoke-tested "
                "modifier-count examples listed here."
            ),
        },
        "manner_location_intransitive_adv_sequence": {
            "rule_id": "manner_location_intransitive_family",
            "type_principle": "manner_plus_location_modifier_sequence",
            "type_family": "forall n : nat, ModifierSeq n -> Entity -> PropT",
            "type_level_open_ended": True,
            "surface_parser_claim": "registered_examples_only",
            "full_surface_parser_certification": False,
            "primary_modifier_count": 1,
            "verified_modifier_counts": intransitive_verified_counts,
            "verified_timed_modifier_counts": intransitive_timed_counts,
            "verified_untimed_modifier_counts": intransitive_untimed_counts,
            "max_verified_modifier_count": (
                max(intransitive_verified_counts)
                if intransitive_verified_counts
                else 0
            ),
            "verified_example_count": len(intransitive_verified_examples),
            "verified_examples": intransitive_verified_examples,
            "witness_generation_spec": intransitive_witness_generation_spec,
            "slot_probe_examples": intransitive_slot_probe_payload,
            "boundary_note": (
                "This family audits the intransitive manner/location Adv "
                "front end separately from the transitive admire family: the "
                "registered witness sequence and controlled sleep/quietly slot "
                "probes are finite parser witnesses, not arbitrary English "
                "coverage."
            ),
        },
        "mixed_role_intransitive_adv_sequence": {
            "rule_id": "mixed_role_intransitive_family",
            "type_principle": "source_goal_instrument_location_manner_modifier_sequence",
            "type_family": "forall n : nat, ModifierSeq n -> Entity -> PropT",
            "type_level_open_ended": True,
            "surface_parser_claim": "registered_examples_only",
            "full_surface_parser_certification": False,
            "primary_modifier_count": 1,
            "verified_modifier_counts": mixed_role_verified_counts,
            "verified_timed_modifier_counts": mixed_role_timed_counts,
            "verified_untimed_modifier_counts": mixed_role_untimed_counts,
            "max_verified_modifier_count": (
                max(mixed_role_verified_counts)
                if mixed_role_verified_counts
                else 0
            ),
            "verified_example_count": len(mixed_role_verified_examples),
            "verified_examples": mixed_role_verified_examples,
            "witness_generation_spec": mixed_role_witness_generation_spec,
            "slot_probe_examples": mixed_role_slot_probe_payload,
            "boundary_note": (
                "This family audits mixed Source/Goal/Instrument/Location/"
                "Manner Adv sequences for intransitives. It is a finite "
                "registered-surface witness family, not a claim of arbitrary "
                "prepositional-phrase attachment coverage."
            ),
        },
    }


APPLICATION_MODIFIER_COUNT_PATTERN = re.compile(
    r"\b[A-Za-z_][A-Za-z0-9_]*\((\d+)\)\("
)

def registered_modifier_role_source_contract() -> dict[str, Any]:
    preposition_roles = sorted(set(MODIFIER_ROLE_BY_PREDICATE.values()))
    derived_roles = sorted({*preposition_roles, "Manner"})
    return {
        "schema_version": "modifier_role_source_contract.v1",
        "source_module": SURFACE_LEXICON_SOURCE,
        "preposition_role_table": "MODIFIER_ROLE_BY_PREDICATE",
        "preposition_roles": preposition_roles,
        "common_adverb_source": "COMMON_ADVERBS",
        "common_adverb_count": len(COMMON_ADVERBS),
        "common_adverb_role": "Manner",
        "role_type": "Adv",
        "derived_role_inventory": derived_roles,
    }


def registered_modifier_role_witness_selection_contract() -> dict[str, Any]:
    return {
        "schema_version": "modifier_role_witness_selection_contract.v2",
        "selection_scope": "registered_primary_and_variant_success_cases",
        "selection_unit": "one_live_sentence_per_registered_adv_role",
        "generator": "derive_first_minimal_registered_occurrence_per_role",
        "role_inventory_source": "semantic_role_source_contract.derived_role_inventory",
        "sentence_sources": [
            "registered_primary_success_cases",
            "registered_variant_success_cases",
        ],
        "candidate_order": [
            "minimum_modifier_count",
            "primary_before_variant",
            "untimed_before_timed",
            "sentence_lexicographic",
            "modifier_lexicographic",
        ],
        "required_witness_fields": [
            "role",
            "type",
            "sentence",
            "modifier",
            "normalized_modifier",
            "source",
        ],
        "live_ast_checks": [
            "sentence_is_registered_success_case",
            "ast_contains_advertised_modifier",
            "ast_modifier_type_is_adv",
            "ast_role_matches_surface_lexicon",
            "normalized_modifier_matches_surface_lexicon",
            "surface_lexicon_source_matches_contract",
        ],
        "full_witness_generation": True,
    }


def split_top_level_arguments(arguments: str) -> list[str]:
    parts: list[str] = []
    depth = 0
    start = 0
    for index, char in enumerate(arguments):
        if char == "(":
            depth += 1
        elif char == ")" and depth:
            depth -= 1
        elif char == "," and depth == 0:
            parts.append(arguments[start:index].strip())
            start = index + 1
    tail = arguments[start:].strip()
    if tail:
        parts.append(tail)
    return parts


def application_modifier_arguments_from_fragment(fragment: str) -> list[str]:
    modifiers: list[str] = []
    for match in APPLICATION_MODIFIER_COUNT_PATTERN.finditer(fragment):
        modifier_count = int(match.group(1))
        start = match.end()
        depth = 1
        cursor = start
        while cursor < len(fragment) and depth:
            char = fragment[cursor]
            if char == "(":
                depth += 1
            elif char == ")":
                depth -= 1
            cursor += 1
        if depth:
            continue
        arguments = split_top_level_arguments(fragment[start : cursor - 1])
        modifiers.extend(arguments[:modifier_count])
    return modifiers


def derive_registered_modifier_role_witnesses(
    semantic_snapshots: list[dict[str, Any]],
    registered_variant_success_cases: list[dict[str, Any]],
) -> list[dict[str, str]]:
    candidates: dict[str, list[tuple[tuple[int, int, int, str, str], dict[str, str]]]] = {}
    source_rank = {
        "registered_primary_success_cases": 0,
        "registered_variant_success_cases": 1,
    }
    coverage_items = [
        ("registered_primary_success_cases", semantic_snapshots),
        ("registered_variant_success_cases", registered_variant_success_cases),
    ]
    for source, items in coverage_items:
        for item in items:
            sentence = item.get("sentence")
            fragments = item.get("expected_dependent_type_fragments")
            if not isinstance(sentence, str) or not isinstance(fragments, list):
                continue
            sentence_is_timed = any(
                token in sentence.lower().split()
                for token in sorted(TEMPORAL_ADVERBS)
            )
            for fragment in fragments:
                if not isinstance(fragment, str):
                    continue
                fragment_modifiers = application_modifier_arguments_from_fragment(fragment)
                modifier_count = len(fragment_modifiers)
                for modifier in fragment_modifiers:
                    if not modifier:
                        continue
                    role = modifier_semantic_role(modifier)
                    witness = {
                        "role": role,
                        "type": "Adv",
                        "sentence": sentence,
                        "modifier": modifier,
                        "normalized_modifier": normalize_surface_name(modifier),
                        "source": source,
                    }
                    score = (
                        modifier_count,
                        source_rank[source],
                        int(sentence_is_timed),
                        sentence.casefold(),
                        modifier.casefold(),
                    )
                    candidates.setdefault(role, []).append((score, witness))
    derived_roles = registered_modifier_role_source_contract()["derived_role_inventory"]
    witnesses: list[dict[str, str]] = []
    for role in derived_roles:
        role_candidates = candidates.get(str(role), [])
        if role_candidates:
            witnesses.append(copy.deepcopy(min(role_candidates, key=lambda item: item[0])[1]))
    return witnesses


def derive_registered_modifier_role_inventory(
    semantic_snapshots: list[dict[str, Any]],
    registered_variant_success_cases: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    role_counts: Counter[str] = Counter()
    coverage_items = [*semantic_snapshots, *registered_variant_success_cases]
    for item in coverage_items:
        if item.get("modifier_role_inventory_scope") == "scope_attachment_discourse_audit":
            continue
        fragments = item.get("expected_dependent_type_fragments")
        if not isinstance(fragments, list):
            continue
        for fragment in fragments:
            if not isinstance(fragment, str):
                continue
            for modifier in application_modifier_arguments_from_fragment(fragment):
                role_counts[modifier_semantic_role(modifier)] += 1
    return [
        {
            "role": str(role),
            "type": "Adv",
            "minimum_observed_occurrences": role_counts[str(role)],
        }
        for role in registered_modifier_role_source_contract()["derived_role_inventory"]
    ]


def declared_application_modifier_counts(
    coverage_items: Iterable[dict[str, Any]],
) -> list[int]:
    counts: set[int] = set()
    for item in coverage_items:
        fragments = item.get("expected_dependent_type_fragments")
        if not isinstance(fragments, list):
            continue
        for fragment in fragments:
            if not isinstance(fragment, str):
                continue
            counts.update(
                int(match.group(1))
                for match in APPLICATION_MODIFIER_COUNT_PATTERN.finditer(fragment)
            )
    return sorted(counts)


def application_modifier_sequence_summaries(ast: dict[str, Any]) -> list[dict[str, Any]]:
    summaries: list[dict[str, Any]] = []

    def walk(value: Any) -> None:
        if isinstance(value, dict):
            if value.get("kind") == "application":
                modifiers = value.get("modifiers")
                modifier_list = modifiers if isinstance(modifiers, list) else []
                modifier_vector = value.get("modifier_vector")
                vector_items = (
                    modifier_vector.get("items")
                    if isinstance(modifier_vector, dict)
                    else None
                )
                vector_item_list = vector_items if isinstance(vector_items, list) else []
                modifier_roles = value.get("modifier_roles")
                role_items = (
                    modifier_roles.get("roles")
                    if isinstance(modifier_roles, dict)
                    else None
                )
                role_item_list = role_items if isinstance(role_items, list) else []
                tail_lengths = [
                    item.get("tail_length")
                    for item in vector_item_list
                    if isinstance(item, dict)
                ]
                role_pattern = [
                    str(item.get("semantic_role", ""))
                    for item in role_item_list
                    if isinstance(item, dict)
                ]
                modifier_count = len(modifier_list)
                vector_length = (
                    modifier_vector.get("length")
                    if isinstance(modifier_vector, dict)
                    else None
                )
                vector_matches_modifiers = (
                    isinstance(modifier_vector, dict)
                    and vector_length == modifier_count
                    and len(vector_item_list) == modifier_count
                    and [
                        item.get("modifier")
                        for item in vector_item_list
                        if isinstance(item, dict)
                    ]
                    == modifier_list
                    and tail_lengths == list(range(modifier_count - 1, -1, -1))
                )
                roles_match_modifiers = (
                    isinstance(modifier_roles, dict)
                    and len(role_item_list) == modifier_count
                    and [
                        item.get("modifier")
                        for item in role_item_list
                        if isinstance(item, dict)
                    ]
                    == modifier_list
                )
                roles_are_adv = all(
                    isinstance(item, dict) and item.get("type") == "Adv"
                    for item in role_item_list
                )
                surface_lexicon_matches = all(
                    isinstance(item, dict)
                    and isinstance(item.get("surface_lexicon"), dict)
                    and item["surface_lexicon"].get("surface_modifier")
                    == item.get("modifier")
                    and item["surface_lexicon"].get("type") == "Adv"
                    and item["surface_lexicon"].get("semantic_role")
                    == item.get("semantic_role")
                    for item in role_item_list
                )
                summaries.append(
                    {
                        "function": str(value.get("function", "")),
                        "modifier_count": modifier_count,
                        "adverb_count": value.get("adverb_count"),
                        "vector_length": vector_length,
                        "vector_item_count": len(vector_item_list),
                        "role_count": len(role_item_list),
                        "tail_lengths": tail_lengths,
                        "role_pattern": role_pattern,
                        "vector_matches_modifiers": vector_matches_modifiers,
                        "roles_match_modifiers": roles_match_modifiers,
                        "roles_are_adv": roles_are_adv,
                        "surface_lexicon_matches": surface_lexicon_matches,
                    }
                )
            for child in value.values():
                walk(child)
        elif isinstance(value, list):
            for child in value:
                walk(child)

    walk(ast)
    return summaries


def application_modifier_role_occurrences(ast: dict[str, Any]) -> list[dict[str, Any]]:
    occurrences: list[dict[str, Any]] = []

    def walk(value: Any) -> None:
        if isinstance(value, dict):
            if value.get("kind") == "application":
                modifier_roles = value.get("modifier_roles")
                role_items = (
                    modifier_roles.get("roles")
                    if isinstance(modifier_roles, dict)
                    else None
                )
                role_item_list = role_items if isinstance(role_items, list) else []
                for index, role_item in enumerate(role_item_list):
                    if not isinstance(role_item, dict):
                        continue
                    surface_lexicon = role_item.get("surface_lexicon")
                    if not isinstance(surface_lexicon, dict):
                        surface_lexicon = {}
                    occurrences.append(
                        {
                            "function": str(value.get("function", "")),
                            "index": index,
                            "modifier": role_item.get("modifier"),
                            "semantic_role": role_item.get("semantic_role"),
                            "type": role_item.get("type"),
                            "surface_modifier": surface_lexicon.get(
                                "surface_modifier",
                            ),
                            "normalized_modifier": surface_lexicon.get(
                                "normalized_modifier",
                            ),
                            "surface_type": surface_lexicon.get("type"),
                            "surface_semantic_role": surface_lexicon.get(
                                "semantic_role",
                            ),
                            "source": surface_lexicon.get("source"),
                        }
                    )
            for child in value.values():
                walk(child)
        elif isinstance(value, list):
            for child in value:
                walk(child)

    walk(ast)
    return occurrences


def registered_modifier_sequence_contract_payload(
    semantic_snapshots: list[dict[str, Any]],
    registered_variant_success_cases: list[dict[str, Any]],
) -> dict[str, Any]:
    declared_counts = declared_application_modifier_counts(
        [*semantic_snapshots, *registered_variant_success_cases],
    )
    return {
        "schema_version": "registered_modifier_sequence_contract.v1",
        "source": "registered_primary_and_variant_success_cases",
        "claim": "registered_examples_only",
        "full_surface_parser_certification": False,
        "primary_case_count": len(semantic_snapshots),
        "variant_case_count": len(registered_variant_success_cases),
        "case_count": len(semantic_snapshots) + len(registered_variant_success_cases),
        "declared_application_modifier_counts": declared_counts,
        "max_declared_application_modifier_count": (
            max(declared_counts) if declared_counts else 0
        ),
        "application_family_pattern": "predicate(n)(ModifierSeq n, ...)",
        "required_invariants": [
            "modifier_vector_length_matches_modifiers",
            "modifier_vector_tail_lengths_decrease_to_zero",
            "modifier_roles_length_matches_modifiers",
            "modifier_roles_are_adv_not_entity",
            "surface_lexicon_matches_modifier_roles",
            "observed_modifier_roles_are_registered",
            "registered_modifier_role_minima_are_observed",
            "registered_modifier_role_inventory_is_coverage_derived",
            "registered_modifier_roles_are_surface_lexicon_derived",
            "registered_modifier_roles_have_live_witnesses",
            "registered_modifier_role_witnesses_are_coverage_derived",
        ],
        "registered_semantic_role_inventory": (
            derive_registered_modifier_role_inventory(
                semantic_snapshots,
                registered_variant_success_cases,
            )
        ),
        "registered_semantic_role_witnesses": (
            derive_registered_modifier_role_witnesses(
                semantic_snapshots,
                registered_variant_success_cases,
            )
        ),
        "semantic_role_witness_selection_contract": (
            registered_modifier_role_witness_selection_contract()
        ),
        "semantic_role_source_contract": registered_modifier_role_source_contract(),
        "live_validation": {
            "validator": "scripts/verify_project.py::validate_registered_modifier_sequence_contract",
            "scope": "run every registered primary and variant success case",
            "max_application_modifier_count_is_recomputed": True,
            "semantic_role_inventory_is_coverage_derived": True,
            "semantic_role_source_contract_is_recomputed": True,
            "semantic_role_witness_selection_contract_is_recomputed": True,
            "semantic_role_witnesses_are_coverage_derived": True,
            "semantic_role_witnesses_are_live_checked": True,
        },
    }


def parser_semantic_boundary_audit_payload(
    surface_parser_coverage: dict[str, Any],
    semantic_snapshots: list[dict[str, Any]],
    coverage_matrix_counts: dict[str, int],
) -> dict[str, Any]:
    surface_family_names = sorted(
        str(family)
        for family, item in surface_parser_coverage.items()
        if isinstance(family, str) and isinstance(item, dict)
    )
    surface_verified_example_count = 0
    surface_slot_probe_count = 0
    surface_matrix_example_count = 0
    for item in surface_parser_coverage.values():
        if not isinstance(item, dict):
            continue
        verified_count = item.get("verified_example_count")
        if isinstance(verified_count, int):
            surface_verified_example_count += verified_count
        slot_probes = item.get("slot_probe_examples")
        if isinstance(slot_probes, dict):
            probes = slot_probes.get("probes")
            matrix_examples = slot_probes.get("matrix_examples")
            if isinstance(probes, list):
                surface_slot_probe_count += len(
                    [probe for probe in probes if isinstance(probe, dict)]
                )
            if isinstance(matrix_examples, list):
                surface_matrix_example_count += len(
                    [row for row in matrix_examples if isinstance(row, dict)]
                )
    registered_rule_count = int(coverage_matrix_counts.get("registered_success_cases", 0))
    registered_variant_count = int(
        coverage_matrix_counts.get("registered_variant_success_cases", 0)
    )
    fallback_count = int(coverage_matrix_counts.get("fallback_success_cases", 0))
    rejected_count = int(coverage_matrix_counts.get("rejected_unsupported_cases", 0))
    total_surface_witnesses = (
        surface_verified_example_count
        + surface_slot_probe_count
        + surface_matrix_example_count
    )
    return {
        "schema_version": "parser_semantic_boundary_audit.v1",
        "audit_basis": "surface_parser_coverage_vs_registered_semantic_coverage",
        "parser_claim": "registered_examples_only",
        "semantic_claim": "registered_construction_rules_only",
        "full_surface_parser_certification": False,
        "full_natural_language_certification": False,
        "surface_parser_family_count": len(surface_family_names),
        "surface_parser_families": surface_family_names,
        "surface_verified_example_count": surface_verified_example_count,
        "surface_slot_probe_count": surface_slot_probe_count,
        "surface_matrix_example_count": surface_matrix_example_count,
        "surface_total_witness_count": total_surface_witnesses,
        "registered_semantic_rule_count": registered_rule_count,
        "registered_semantic_variant_count": registered_variant_count,
        "semantic_snapshot_count": len(semantic_snapshots),
        "fallback_success_case_count": fallback_count,
        "rejected_unsupported_case_count": rejected_count,
        "boundary_rows": [
            {
                "boundary_id": "surface_parser_front_end",
                "component": "surface_parser",
                "claim": "finite_surface_witnesses",
                "status": "open_registered_examples_only",
                "evidence_count": total_surface_witnesses,
                "blocks_completion": True,
                "blocker": "surface_parser_claim_registered_examples_only",
                "next_stage": "extend_surface_parser_beyond_registered_examples",
            },
            {
                "boundary_id": "registered_semantic_translation",
                "component": "semantic_translation",
                "claim": "registered_construction_semantics",
                "status": "verified_finite_registered_fragment",
                "evidence_count": (
                    registered_rule_count
                    + registered_variant_count
                    + len(semantic_snapshots)
                ),
                "blocks_completion": False,
                "blocker": "",
                "next_stage": "",
            },
            {
                "boundary_id": "fallback_scaffold",
                "component": "fallback",
                "claim": "shallow_scaffold_not_registered_semantics",
                "status": "open_if_used",
                "evidence_count": fallback_count,
                "blocks_completion": True,
                "blocker": "fallback_certification_level_shallow_scaffold",
                "next_stage": "promote_more_fallback_successes_to_registered_constructions",
            },
            {
                "boundary_id": "unsupported_rejection",
                "component": "unsupported_fragment_guard",
                "claim": "rejected_before_fallback_not_translated",
                "status": "guarded",
                "evidence_count": rejected_count,
                "blocks_completion": False,
                "blocker": "",
                "next_stage": "",
            },
        ],
        "required_invariants": [
            "parser_claim_is_not_semantic_claim",
            "surface_examples_do_not_imply_full_parser_certification",
            "registered_semantic_rows_remain_construction_level",
            "fallback_rows_remain_shallow_when_present",
            "unsupported_rows_stop_before_fallback",
            "completion_next_stage_targets_parser_expansion_not_completed_boundary_split",
        ],
        "live_validation": {
            "validator": (
                "scripts/verify_project.py::"
                "validate_parser_semantic_boundary_audit"
            ),
            "html_hooks": "data-parser-semantic-boundary-*",
            "source_completion_blocker": (
                "surface_parser_claim_registered_examples_only"
            ),
            "source_next_stage": "extend_surface_parser_beyond_registered_examples",
        },
    }


def construction_fragment_manifest() -> dict[str, Any]:
    rules = construction_rules()
    variant_examples_by_rule: dict[str, list[str]] = {}
    for variant in REGISTERED_VARIANT_COVERAGE_EXAMPLES:
        rule_id = str(variant.get("rule_id", ""))
        sentence = str(variant.get("sentence", ""))
        if rule_id and sentence:
            variant_examples_by_rule.setdefault(rule_id, []).append(sentence)
    registered = []
    registered_success_cases = []
    for rule in rules:
        example = CONSTRUCTION_RULE_EXAMPLES.get(rule.rule_id, "")
        accepted_examples = [example] if example else []
        accepted_examples.extend(variant_examples_by_rule.get(rule.rule_id, []))
        registered.append(
            {
                "id": rule.rule_id,
                "label": rule.label,
                "phenomenon": rule.phenomenon,
                "example": example,
                "accepted_examples": accepted_examples,
                "verification_scope_kind": "registered_construction",
                "certification_level": "construction_rule",
                "boundary_status": "registered_primary_example",
                "forbidden_coq_fragments": list(rule.forbidden_coq_fragments),
            }
        )
        if example:
            registered_success_cases.append(
                {
                    "rule_id": rule.rule_id,
                    "sentence": example,
                    "expected_verification_scope_kind": "registered_construction",
                    "expected_certification_level": "construction_rule",
                    "boundary_status": "registered_primary_example",
                }
            )
    registered_variant_success_cases = [
        dict(example) for example in REGISTERED_VARIANT_COVERAGE_EXAMPLES
    ]
    fallback_success_cases = [
        dict(example) for example in FALLBACK_COVERAGE_EXAMPLES
    ]
    rejected_unsupported_cases = [
        dict(example) for example in UNSUPPORTED_FRAGMENT_COVERAGE_EXAMPLES
    ]
    coverage_matrix_counts = {
        "registered_success_cases": len(registered_success_cases),
        "registered_variant_success_cases": len(registered_variant_success_cases),
        "fallback_success_cases": len(fallback_success_cases),
        "rejected_unsupported_cases": len(rejected_unsupported_cases),
    }
    semantic_snapshots = []
    for snapshot in CERTIFIED_FRAGMENT_SEMANTIC_SNAPSHOTS:
        snapshot_copy = copy.deepcopy(snapshot)
        ast_summary = CERTIFIED_FRAGMENT_AST_SUMMARY_SNAPSHOTS.get(
            snapshot_copy["rule_id"],
        )
        if ast_summary is not None:
            snapshot_copy["expected_ast_summary"] = copy.deepcopy(ast_summary)
        semantic_snapshots.append(snapshot_copy)
    modifier_sequence_contract = registered_modifier_sequence_contract_payload(
        semantic_snapshots,
        registered_variant_success_cases,
    )
    surface_parser_coverage = surface_parser_coverage_payload()
    return {
        "schema_version": "certified_fragment.v1",
        "full_natural_language_certification": False,
        "registered_construction_count": len(registered),
        "registered_constructions": registered,
        "surface_parser_coverage": surface_parser_coverage,
        "registered_modifier_sequence_contract": modifier_sequence_contract,
        "parser_semantic_boundary_audit": parser_semantic_boundary_audit_payload(
            surface_parser_coverage,
            semantic_snapshots,
            coverage_matrix_counts,
        ),
        "semantic_snapshot_count": len(semantic_snapshots),
        "semantic_snapshots": semantic_snapshots,
        "fallback": {
            "verification_scope_kind": "fallback_shallow",
            "certification_level": "shallow_scaffold",
            "example": (
                "Mary admired the painting in the gallery with a telescope "
                "near a window yesterday"
            ),
            "guarantees": [
                "fallback AST/type_check and semantic_readings contract are checked",
                "generated Coq/Rocq scaffold is checked when requested and available",
            ],
            "limitations": [
                "does not certify full natural-language semantics",
                "does not resolve unregistered scope, attachment, or discourse ambiguities",
            ],
            "certification_gaps": fallback_certification_gap_payload(),
        },
        "coverage_matrix": {
            "registered_success_cases": registered_success_cases,
            "registered_variant_success_cases": registered_variant_success_cases,
            "fallback_success_cases": fallback_success_cases,
            "rejected_unsupported_cases": rejected_unsupported_cases,
        },
        "fallback_promotion_candidates": fallback_promotion_candidates_payload(
            fallback_success_cases,
        ),
        "coverage_matrix_counts": coverage_matrix_counts,
        "completion_status": project_completion_status_payload(
            registered_rule_count=len(registered),
            semantic_snapshot_count=len(semantic_snapshots),
            coverage_matrix_counts=coverage_matrix_counts,
            semantic_snapshots=semantic_snapshots,
            registered_variant_success_cases=registered_variant_success_cases,
        ),
        "rejected_fragment_markers": sorted(UNSUPPORTED_CERTIFIED_CLAUSE_MARKERS),
        "scope_determiners": {
            "existential": sorted(EXISTENTIAL_SCOPE_DETERMINERS),
            "universal": sorted(UNIVERSAL_SCOPE_DETERMINERS),
            "negative": sorted(NEGATIVE_SCOPE_DETERMINERS),
        },
        "methodological_guard": (
            "A successful fallback analysis is intentionally weaker than a "
            "registered construction-rule success."
        ),
    }


