def scope_attachment_discourse_case_categories(case: dict[str, Any]) -> set[str]:
    rule_id = str(case.get("rule_id", ""))
    variant_id = str(case.get("variant_id", ""))
    sentence = str(case.get("sentence", ""))
    expected_ast_kind = str(case.get("expected_ast_kind", ""))
    text = flatten_truth_condition_witness_text(case).lower()
    categories: set[str] = set()
    if rule_id == "quantifier_scope_ambiguity" or expected_ast_kind == "scope_ambiguity":
        categories.add("quantifier_scope")
    if rule_id == "perception_nominalization":
        categories.add("perception_complement_nominalization")
        if (
            " yesterday" in f" {sentence.lower()}"
            or " after " in f" {sentence.lower()} "
            or " before " in f" {sentence.lower()} "
        ):
            categories.add("perception_temporal_attachment")
    if (
        "modified" in text
        or "instrument" in text
        or "locative" in text
        or "directional" in text
        or "manner" in text
        or re.search(r"\b(with|near|beside|under|into|from|on|in)\s*\(", text)
    ):
        categories.add("typed_modifier_attachment")
    if rule_id == "causal_because" and (
        " because it " in f" {sentence.lower()} "
        or " it was " in f" {sentence.lower()} "
        or "anaphoric" in variant_id
    ):
        categories.add("discourse_pronominal_cause")
    if (
        " who " in f" {sentence.lower()} "
        or " that " in f" {sentence.lower()} "
        or "relative_clause_restrictor" in text
    ):
        categories.add("relative_clause_restrictors")
    return categories


def scope_attachment_discourse_case_witness(
    source: str,
    case: dict[str, Any],
) -> dict[str, Any]:
    reading_names = case.get("expected_scope_audit_reading_names")
    if not isinstance(reading_names, list):
        reading_names = case.get("expected_reading_names")
    if not isinstance(reading_names, list):
        reading_names = []
    attachment_kinds = case.get("expected_scope_audit_attachment_kinds")
    if not isinstance(attachment_kinds, list):
        attachment_kinds = []
    relative_restrictor_sites = case.get(
        "expected_scope_audit_relative_restrictor_sites",
    )
    if not isinstance(relative_restrictor_sites, list):
        relative_restrictor_sites = []
    return {
        "source": source,
        "rule_id": str(case.get("rule_id", "")),
        "variant_id": str(case.get("variant_id", "")),
        "sentence": str(case.get("sentence", "")),
        "expected_event_analysis": str(case.get("expected_event_analysis", "")),
        "expected_ast_kind": str(case.get("expected_ast_kind", "")),
        "expected_reading_names": [
            str(name) for name in reading_names if isinstance(name, str)
        ],
        "expected_attachment_kinds": [
            str(kind) for kind in attachment_kinds if isinstance(kind, str)
        ],
        "expected_relative_restrictor_sites": [
            str(site)
            for site in relative_restrictor_sites
            if isinstance(site, str)
        ],
        "verification_route": (
            "semantic_snapshot_regression"
            if source == "semantic_snapshot"
            else "registered_variant_success_cases -> web_route_smoke_check"
        ),
    }


def scope_attachment_discourse_audit_payload(
    semantic_snapshots: list[dict[str, Any]],
    registered_variant_success_cases: list[dict[str, Any]],
) -> dict[str, Any]:
    witness_by_category: dict[str, list[dict[str, Any]]] = {
        str(spec["category_id"]): []
        for spec in SCOPE_ATTACHMENT_DISCOURSE_CATEGORY_SPECS
    }
    source_cases = [
        ("semantic_snapshot", item) for item in semantic_snapshots
    ] + [
        ("registered_variant_success_case", item)
        for item in registered_variant_success_cases
    ]
    for source, case in source_cases:
        if not isinstance(case, dict):
            continue
        witness = scope_attachment_discourse_case_witness(source, case)
        for category_id in scope_attachment_discourse_case_categories(case):
            if category_id in witness_by_category:
                witness_by_category[category_id].append(copy.deepcopy(witness))

    categories = []
    for spec in SCOPE_ATTACHMENT_DISCOURSE_CATEGORY_SPECS:
        category_id = str(spec["category_id"])
        witnesses = witness_by_category[category_id]
        reading_names = sorted(
            {
                name
                for witness in witnesses
                for name in witness.get("expected_reading_names", [])
                if isinstance(name, str) and name
            },
        )
        attachment_kinds = sorted(
            {
                kind
                for witness in witnesses
                for kind in witness.get("expected_attachment_kinds", [])
                if isinstance(kind, str) and kind
            },
        )
        relative_restrictor_sites = sorted(
            {
                site
                for witness in witnesses
                for site in witness.get("expected_relative_restrictor_sites", [])
                if isinstance(site, str) and site
            },
        )
        categories.append(
            {
                **spec,
                "witness_source": (
                    "semantic_snapshots_and_registered_variant_success_cases"
                ),
                "witness_scope": "finite_registered_fragment",
                "witness_count": len(witnesses),
                "semantic_snapshot_witness_count": len(
                    [
                        witness
                        for witness in witnesses
                        if witness.get("source") == "semantic_snapshot"
                    ],
                ),
                "registered_variant_witness_count": len(
                    [
                        witness
                        for witness in witnesses
                        if witness.get("source")
                        == "registered_variant_success_case"
                    ],
                ),
                "reading_name_inventory": reading_names,
                "attachment_kind_inventory": attachment_kinds,
                "relative_restrictor_site_inventory": relative_restrictor_sites,
                "sample_sentences": unique_truth_condition_witness_values(
                    witnesses,
                    "sentence",
                    9,
                ),
                "sample_variant_ids": unique_truth_condition_witness_values(
                    witnesses,
                    "variant_id",
                    9,
                ),
                "sample_witnesses": witnesses[:4],
            },
        )

    open_boundaries = [
        {
            "boundary_id": "relative_clause_attachment",
            "status": (
                "finite_relative_attachment_alternatives_registered_"
                "arbitrary_attachment_open"
            ),
            "guarded_marker": "",
            "next_stage": "generalize_stacked_relative_clause_attachment_policy",
        },
        {
            "boundary_id": "arbitrary_discourse_anaphora",
            "status": "unregistered_discourse_resolution_open",
            "guarded_marker": "",
            "next_stage": "add_discourse_referent_registry",
        },
        {
            "boundary_id": "pragmatic_attachment_disambiguation",
            "status": "unregistered_pragmatic_policy_open",
            "guarded_marker": "",
            "next_stage": "add_attachment_policy_witnesses",
        },
    ]
    return {
        "schema_version": "scope_attachment_discourse_audit.v1",
        "claim": "finite_registered_witnesses_not_full_discourse_semantics",
        "source": "semantic_snapshots_and_registered_variant_success_cases",
        "full_scope_attachment_discourse_certification": False,
        "blocker": "fallback_certification_level_shallow_scaffold",
        "next_stage": "expand_scope_attachment_discourse_coverage",
        "category_count": len(categories),
        "registered_witness_count": sum(
            int(item.get("witness_count", 0)) for item in categories
        ),
        "categories": categories,
        "open_boundary_count": len(open_boundaries),
        "open_boundaries": open_boundaries,
        "required_invariants": [
            "audit_claim_is_finite_not_complete",
            "each_category_has_registered_witnesses",
            "multi_reading_scope_cases_expose_reading_names",
            "temporal_attachment_cases_expose_attachment_kinds",
            "open_boundaries_remain_explicit",
        ],
        "live_validation": {
            "validator": (
                "scripts/verify_project.py::"
                "validate_scope_attachment_discourse_audit"
            ),
            "html_hooks": "data-scope-attachment-discourse-*",
            "source_completion_blocker": "fallback_certification_level_shallow_scaffold",
            "source_next_stage": "expand_scope_attachment_discourse_coverage",
        },
    }


TRUTH_CONDITION_OBLIGATION_WITNESS_SOURCE = (
    "semantic_snapshots_and_registered_variant_success_cases"
)
TRUTH_CONDITION_OBLIGATION_PROOF_INDEX_SCOPE = (
    "registered_fragment_entrypoints_not_general_denotation"
)


def flatten_truth_condition_witness_text(value: Any) -> str:
    if isinstance(value, dict):
        return " ".join(
            flatten_truth_condition_witness_text(item)
            for item in value.values()
        )
    if isinstance(value, (list, tuple, set)):
        return " ".join(flatten_truth_condition_witness_text(item) for item in value)
    return str(value)


def truth_condition_witness_class_ids(case: dict[str, Any]) -> set[str]:
    summary = case.get("expected_ast_summary")
    if not isinstance(summary, dict):
        summary = {}
    fragments = case.get("expected_dependent_type_fragments")
    if not isinstance(fragments, list):
        fragments = []
    text = flatten_truth_condition_witness_text(
        [
            case.get("rule_id", ""),
            case.get("variant_id", ""),
            case.get("sentence", ""),
            case.get("expected_event_analysis", ""),
            case.get("expected_ast_kind", ""),
            summary,
            fragments,
        ],
    )
    text_lower = text.lower()
    class_ids: set[str] = set()
    predicate_symbols = summary.get("predicate_symbols")
    if predicate_symbols or re.search(r"\b[A-Za-z][A-Za-z0-9_]*\s*\(", text):
        class_ids.add("lexical_application")
    if (
        "exists " in text_lower
        or "forall " in text_lower
        or "sigma" in text_lower
        or re.search(r"\bscope(?:_ambiguity|[-_ ]taking|[-_ ]scope)?\b", text_lower)
        or summary.get("binder_signatures")
        or summary.get("quantifier_signatures")
    ):
        class_ids.add("sigma_quantification")
    if (
        "time" in text_lower
        or "at_t(" in text_lower
        or "during_t(" in text_lower
        or "before_t(" in text_lower
        or "after_t(" in text_lower
        or "until_t(" in text_lower
        or "since_t(" in text_lower
        or "before(" in text_lower
        or int(summary.get("top_level_time_modifier_count") or 0) > 0
    ):
        class_ids.add("temporal_operators")
    if (
        "repeat(" in text_lower
        or "event-counting" in text_lower
        or "counting" in text_lower
        or " twice" in text_lower
        or " thrice" in text_lower
    ):
        class_ids.add("repeat_counting")
    if (
        "not_t(" in text_lower
        or "negat" in text_lower
        or "polarity" in text_lower
        or " not " in text_lower
    ):
        class_ids.add("polarity")
    if (
        "transition(" in text_lower
        or "cause(" in text_lower
        or "causewithinstrument(" in text_lower
        or "change(" in text_lower
        or "holds_state(" in text_lower
        or "causal" in text_lower
        or "resultative" in text_lower
        or summary.get("state_symbols")
    ):
        class_ids.add("transition_cause")
    if (
        "modified" in text_lower
        or "instrument" in text_lower
        or "locative" in text_lower
        or "directional" in text_lower
        or "manner" in text_lower
        or re.search(r"\b(with|near|beside|under|into|from|on|in)\s*\(", text_lower)
        or int(summary.get("top_level_modifier_count") or 0) > 0
    ):
        class_ids.add("modifier_attachment")
    return class_ids


def truth_condition_string_list(value: Any) -> list[str]:
    if not isinstance(value, list):
        return []
    return [str(item) for item in value if str(item)]


def truth_condition_witness_proof_index(
    source_kind: str,
    case: dict[str, Any],
) -> dict[str, Any]:
    rule_id = str(case.get("rule_id", ""))
    variant_id = str(case.get("variant_id", ""))
    if source_kind == "semantic_snapshot":
        coq_definitions = truth_condition_string_list(
            case.get("expected_coq_definitions"),
        )
        coq_checks = [f"Check {name}." for name in coq_definitions]
        semantic_reading_names = truth_condition_string_list(
            case.get("expected_reading_names"),
        )
        semantic_reading_sources = truth_condition_string_list(
            case.get("expected_reading_sources"),
        )
        primary_entrypoint = (
            coq_checks[0] if coq_checks else f"semantic_snapshot:{rule_id}"
        )
        return {
            "proof_index_kind": "semantic_snapshot_coq_entrypoints",
            "verification_route": "semantic_snapshot_regression",
            "primary_entrypoint": primary_entrypoint,
            "coq_definitions": coq_definitions,
            "coq_checks": coq_checks,
            "semantic_reading_names": semantic_reading_names,
            "semantic_reading_sources": semantic_reading_sources,
            "type_check_type": str(case.get("expected_type_check_type", "")),
            "runtime_checks": [],
            "truth_condition_route": (
                "semantic_snapshot_regression -> semantic_readings_check -> "
                "coq_shallow_scaffold_boundary"
            ),
        }
    primary_entrypoint = (
        f"registered_variant_success_case:{variant_id}"
        if variant_id
        else f"registered_variant_success_case:{rule_id}"
    )
    return {
        "proof_index_kind": "registered_variant_runtime_entrypoints",
        "verification_route": "registered_variant_success_cases",
        "primary_entrypoint": primary_entrypoint,
        "coq_definitions": [],
        "coq_checks": [],
        "semantic_reading_names": [],
        "semantic_reading_sources": [],
        "type_check_type": "",
        "runtime_checks": [
            "coverage_matrix.registered_variant_success_cases",
            "web_route_smoke_check:/api/analyze",
            "web_route_smoke_check:/",
        ],
        "truth_condition_route": (
            "registered_variant_success_cases -> web_route_smoke_check"
        ),
        "verification_scope_kind": str(case.get("expected_verification_scope_kind", "")),
        "certification_level": str(case.get("expected_certification_level", "")),
        "boundary_status": str(case.get("boundary_status", "")),
    }


def truth_condition_obligation_witnesses(
    semantic_snapshots: list[dict[str, Any]],
    registered_variant_success_cases: list[dict[str, Any]],
) -> dict[str, list[dict[str, Any]]]:
    witnesses: dict[str, list[dict[str, Any]]] = {
        "lexical_application": [],
        "sigma_quantification": [],
        "temporal_operators": [],
        "repeat_counting": [],
        "polarity": [],
        "transition_cause": [],
        "modifier_attachment": [],
    }
    seen: dict[str, set[tuple[str, str, str]]] = {
        class_id: set() for class_id in witnesses
    }
    source_cases = [
        ("semantic_snapshot", item) for item in semantic_snapshots
    ] + [
        ("registered_variant_success_case", item)
        for item in registered_variant_success_cases
    ]
    for source_kind, case in source_cases:
        if not isinstance(case, dict):
            continue
        rule_id = str(case.get("rule_id", ""))
        variant_id = str(case.get("variant_id", ""))
        sentence = str(case.get("sentence", ""))
        key = (source_kind, rule_id, variant_id or sentence)
        for class_id in truth_condition_witness_class_ids(case):
            if key in seen[class_id]:
                continue
            seen[class_id].add(key)
            witnesses[class_id].append(
                {
                    "source": source_kind,
                    "rule_id": rule_id,
                    "variant_id": variant_id,
                    "sentence": sentence,
                    "proof_index": truth_condition_witness_proof_index(
                        source_kind,
                        case,
                    ),
                },
            )
    return witnesses


def unique_truth_condition_witness_values(
    witnesses: list[dict[str, Any]],
    key: str,
    limit: int,
) -> list[str]:
    values: list[str] = []
    seen: set[str] = set()
    for witness in witnesses:
        value = witness.get(key, "")
        if not value or value in seen:
            continue
        seen.add(value)
        values.append(value)
        if len(values) >= limit:
            break
    return values


def summarize_truth_condition_witnesses(
    witnesses: list[dict[str, Any]],
) -> dict[str, Any]:
    return {
        "witness_source": TRUTH_CONDITION_OBLIGATION_WITNESS_SOURCE,
        "witness_scope": "finite_registered_fragment",
        "proof_index_scope": TRUTH_CONDITION_OBLIGATION_PROOF_INDEX_SCOPE,
        "registered_witness_count": len(witnesses),
        "sample_rule_ids": unique_truth_condition_witness_values(
            witnesses,
            "rule_id",
            5,
        ),
        "sample_variant_ids": unique_truth_condition_witness_values(
            witnesses,
            "variant_id",
            5,
        ),
        "sample_sentences": unique_truth_condition_witness_values(
            witnesses,
            "sentence",
            3,
        ),
        "sample_proof_entrypoints": unique_truth_condition_witness_values(
            [
                {
                    "primary_entrypoint": str(
                        witness.get("proof_index", {}).get("primary_entrypoint", ""),
                    ),
                }
                for witness in witnesses
                if isinstance(witness.get("proof_index"), dict)
            ],
            "primary_entrypoint",
            5,
        ),
        "sample_witnesses": witnesses[:3],
    }


